do
	local Core = {}
	Core.resolve = resolve or Resolve()
	if not Core.resolve then
		error("Resolve application is not available.")
	end
	Core.fusion = fu or Core.resolve:Fusion()
	if not Core.fusion then
		error("Fusion context unavailable.")
	end
	Core.ui = Core.fusion.UIManager
	Core.dispatcher = bmd.UIDispatcher(Core.ui)
	Core.timeoutHandlers = {}
	Core._timeoutFallback = Core.dispatcher and Core.dispatcher.On and Core.dispatcher.On.Timeout

	function Core.registerTimeoutHandler(id, fn)
		if not id or id == "" or type(fn) ~= "function" then
			return false, "invalid_handler"
		end
		Core.timeoutHandlers[id] = fn
		return true
	end

	function Core.removeTimeoutHandler(id)
		if not id then
			return
		end
		Core.timeoutHandlers[id] = nil
	end

	function Core.dispatchTimeout(ev)
		local handled = false
		if Core._timeoutFallback then
			local ok, result = pcall(Core._timeoutFallback, ev)
			if ok then
				handled = (result == true)
			else
				print("[DaVinci TTS][Timeout] fallback error: " .. tostring(result))
			end
		end
		local who = ev and (ev.who or ev.ID or ev.Name or ev.TimerID or ev.TimerId)
		if who and Core.timeoutHandlers[who] then
			local ok, result = pcall(Core.timeoutHandlers[who], ev)
			if ok then
				if result == nil then
					handled = true
				else
					handled = handled or (result == true)
				end
			else
				print("[DaVinci TTS][Timeout] handler error (" .. tostring(who) .. "): " .. tostring(result))
			end
		elseif not who then
			for id, fn in pairs(Core.timeoutHandlers) do
				local ok, result = pcall(fn, ev)
				if ok then
					if result == nil or result == true then
						handled = true
					end
				else
					print("[DaVinci TTS][Timeout] handler error (" .. tostring(id) .. "): " .. tostring(result))
				end
			end
		end
		return handled
	end

	if Core.dispatcher and Core.dispatcher.On then
		Core.dispatcher.On.Timeout = function(ev)
			return Core.dispatchTimeout(ev)
		end
	end

	App.Core = Core
end

