---
--- 5. 服务模块 (App.Services)
---
do
	local Services = App.Services
	local Config = App.Config
	local Utils = App.Utils

	Services.HttpClient = Services.HttpClient or {}
	Services.CurlCompat = Services.CurlCompat or {}

	do
		local okHttps, https = pcall(require, "ssl.https")
		local okLtn12, ltn12 = pcall(require, "ltn12")
		if okHttps and okLtn12 and https and ltn12 then
			Services.HttpClient.https = {
				get = function(url, headers, timeout)
					local sinkTable = {}
					local requestHeaders = {}
					if headers then
						for k, v in pairs(headers) do
							requestHeaders[k] = v
						end
					end
					requestHeaders["content-length"] = "0"
					local ok, statusCode, respHeaders, statusLine = https.request({
						url = url,
						method = "GET",
						headers = requestHeaders,
						sink = ltn12.sink.table(sinkTable),
						protocol = "tlsv1_2",
						verify = "none",
						timeout = timeout or Config.Const.SUPABASE_TIMEOUT,
					})
					if not ok then
						return nil, statusCode or statusLine or "request_failed"
					end
					local body = table.concat(sinkTable)
					local code = tonumber(statusCode) or tonumber(respHeaders and respHeaders.status) or statusCode
					return body, code
				end,
				postJson = function(url, payload, headers, timeout)
					local sinkTable = {}
					local requestHeaders = {}
					if headers then
						for k, v in pairs(headers) do
							requestHeaders[k] = v
						end
					end
					local bodyStr = payload or ""
					requestHeaders["content-type"] = "application/json"
					requestHeaders["content-length"] = tostring(#bodyStr)
					local ok, statusCode, respHeaders, statusLine = https.request({
						url = url,
						method = "POST",
						headers = requestHeaders,
						source = ltn12.source.string(bodyStr),
						sink = ltn12.sink.table(sinkTable),
						protocol = "tlsv1_2",
						verify = "none",
						timeout = timeout or Config.Const.SUPABASE_TIMEOUT,
					})
					if not ok then
						return nil, statusCode or statusLine or "request_failed"
					end
					local body = table.concat(sinkTable)
					local code = tonumber(statusCode) or tonumber(respHeaders and respHeaders.status) or statusCode
					return body, code
				end,
			}
		end
	end

	do
		local CurlCompat = Services.CurlCompat

		local function compactCurlDetail(text)
			local value = tostring(text or ""):gsub("%s+", " ")
			if #value > 220 then
				value = value:sub(1, 220) .. "..."
			end
			return value
		end

		function CurlCompat.buildTlsOption(tlsCompatFlag)
			if not IS_WINDOWS or not tlsCompatFlag or tlsCompatFlag == "" then
				return ""
			end
			return " " .. tostring(tlsCompatFlag)
		end

		function CurlCompat.isSchannelRevocationError(message)
			local lower = tostring(message or ""):lower()
			if lower == "" or not lower:find("schannel", 1, true) then
				return false
			end
			if lower:find("crypt_e_no_revocation_check", 1, true) then
				return true
			end
			if lower:find("0x80092012", 1, true) then
				return true
			end
			if lower:find("revocation", 1, true) then
				return true
			end
			if lower:find("revoca", 1, true) then
				return true
			end
			return false
		end

		function CurlCompat.isUnsupportedOptionError(message, flag)
			local lower = tostring(message or ""):lower()
			local normalizedFlag = tostring(flag or ""):lower()
			if lower == "" or normalizedFlag == "" or not lower:find(normalizedFlag, 1, true) then
				return false
			end
			return lower:find("unknown", 1, true) ~= nil or lower:find("unsupported", 1, true) ~= nil
		end

		function CurlCompat.getNextTlsFlag(currentFlag, errorText)
			if not IS_WINDOWS then
				return nil
			end
			if not currentFlag or currentFlag == "" then
				if CurlCompat.isSchannelRevocationError(errorText) then
					return "--ssl-revoke-best-effort", "schannel_revocation"
				end
				return nil
			end
			if currentFlag == "--ssl-revoke-best-effort" then
				if CurlCompat.isUnsupportedOptionError(errorText, currentFlag) then
					return "--ssl-no-revoke", "best_effort_unsupported"
				end
				if CurlCompat.isSchannelRevocationError(errorText) then
					return "--ssl-no-revoke", "schannel_revocation_persisted"
				end
			end
			return nil
		end

		function CurlCompat.logRetry(context, nextFlag, reason, errorText)
			local message = string.format(
				"Windows Schannel compatibility retry [%s]: flag=%s reason=%s detail=%s",
				tostring(context or "curl"),
				tostring(nextFlag or ""),
				tostring(reason or "unknown"),
				compactCurlDetail(errorText)
			)
			if type(logInfo) == "function" then
				logInfo(message)
			else
				print(message)
			end
		end

		function CurlCompat.runWindowsSync(buildCommand, options)
			options = options or {}
			local tlsCompatFlag = options.initialTlsFlag
			while true do
				for _, path in ipairs(options.resetPaths or {}) do
					Utils.removeFile(path)
				end

				local command = buildCommand(tlsCompatFlag)
				local commandOk = false
				if runShellCommand then
					commandOk = runShellCommand(command) == true
				else
					local res, how, code = os.execute(command)
					if type(res) == "number" then
						commandOk = res == 0
					elseif res == true then
						if how == "exit" then
							commandOk = (code or 0) == 0
						else
							commandOk = true
						end
					else
						commandOk = false
					end
				end

				local body = options.bodyPath and (Utils.readFile(options.bodyPath) or "") or ""
				local info = options.infoPath and (Utils.readFile(options.infoPath) or "") or ""
				local stderr = options.errPath and (Utils.readFile(options.errPath) or "") or ""
				local result = {
					ok = commandOk,
					body = body,
					info = info,
					stderr = stderr,
					tlsCompatFlag = tlsCompatFlag,
				}
				if commandOk then
					return result
				end

				local nextFlag, retryReason =
					CurlCompat.getNextTlsFlag(tlsCompatFlag, table.concat({ stderr, info, body }, "\n"))
				if not nextFlag then
					return result
				end
				CurlCompat.logRetry(
					options.context or "curl",
					nextFlag,
					retryReason,
					table.concat({ stderr, info, body }, "\n")
				)
				tlsCompatFlag = nextFlag
			end
		end
	end

	function Services.httpGet(url, headers, timeout)
		if Services.HttpClient.https then
			local body, code = Services.HttpClient.https.get(url, headers, timeout)
			if body then
				return body, code
			end
		end

		local headerParts = {}
		if headers then
			for k, v in pairs(headers) do
				local cleanValue = tostring(v):gsub('"', '\\"')
				table.insert(headerParts, string.format('-H "%s: %s"', k, cleanValue))
			end
		end
		local maxTime = timeout or Config.Const.SUPABASE_TIMEOUT
		local sep = package.config:sub(1, 1)

		if sep == "\\" then
			local outPath, err = Utils.makeTempPath("out")
			if not outPath then
				return nil, "tmpname_failed:" .. tostring(err)
			end
			local errPath, errErr = Utils.makeTempPath("err")
			if not errPath then
				Utils.removeFile(outPath)
				return nil, "tmpname_failed:" .. tostring(errErr)
			end
			local runResult = Services.CurlCompat.runWindowsSync(function(tlsCompatFlag)
				return string.format(
					'curl%s -sS -L -g -m %d %s "%s" > "%s" 2> "%s"',
					Services.CurlCompat.buildTlsOption(tlsCompatFlag),
					maxTime,
					table.concat(headerParts, " "),
					url,
					outPath,
					errPath
				)
			end, {
				context = "http_get",
				resetPaths = { outPath, errPath },
				bodyPath = outPath,
				errPath = errPath,
			})
			Utils.removeFile(outPath)
			Utils.removeFile(errPath)
			if not runResult.ok then
				return nil, runResult.stderr ~= "" and runResult.stderr or "curl_hidden_failed"
			end
			local body = runResult.body or ""
			if body == "" then
				return nil, "empty_response"
			end
			return body, nil
		end

		curlCommand = curlCommand .. " 2>/dev/null"
		local pipe = io.popen(curlCommand, "r")
		if not pipe then
			return nil, "curl_popen_failed"
		end
		local body = pipe:read("*a") or ""
		pipe:close()
		if body == "" then
			return nil, "empty_response"
		end
		return body, nil
	end

	local function removeTempPaths(paths)
		if type(paths) ~= "table" then
			return
		end
		for _, path in ipairs(paths) do
			if type(path) == "string" and path ~= "" then
				Utils.removeFile(path)
			end
		end
	end

	function Services._buildCurlHeaders(headers, defaults)
		local headerParts = {}
		local seenHeaders = {}
		if type(headers) == "table" then
			for k, v in pairs(headers) do
				local key = tostring(k or "")
				local lower = key:lower()
				seenHeaders[lower] = true
				local cleanValue = tostring(v):gsub('"', '\\"')
				table.insert(headerParts, string.format('-H "%s: %s"', key, cleanValue))
			end
		end

		defaults = defaults or {}
		if defaults.contentType and not seenHeaders["content-type"] then
			table.insert(headerParts, string.format('-H "Content-Type: %s"', tostring(defaults.contentType)))
		end
		if defaults.accept and not seenHeaders["accept"] then
			table.insert(headerParts, string.format('-H "Accept: %s"', tostring(defaults.accept)))
		end
		if defaults.clearExpect then
			table.insert(headerParts, '-H "Expect:"')
		end
		return headerParts
	end

	function Services._writeTempPayload(payloadStr)
		local tempPayload, err1 = Utils.makeTempPath("json")
		if not tempPayload then
			return nil, "tmpname_failed:" .. tostring(err1)
		end
		local f, err2 = Utils.openBinaryWriter(tempPayload)
		if not f then
			Utils.removeFile(tempPayload)
			return nil, "payload_tmp_open_failed:" .. tostring(err2)
		end
		f:write(payloadStr or "")
		f:close()
		return tempPayload
	end

	function Services._runCurlAndCollect(commandSpec)
		local command = commandSpec and commandSpec.command or ""
		if command == "" then
			return {
				ok = false,
				code = -1,
				stderr = "missing_command",
				http = nil,
				body = "",
				info = "",
			}
		end

		local commandOk = false
		local exitCode = nil
		if runShellCommand then
			commandOk = runShellCommand(command)
			exitCode = commandOk and 0 or 1
		else
			local res, how, code = os.execute(command)
			if type(res) == "number" then
				exitCode = res
				commandOk = res == 0
			elseif res == true then
				if how == "exit" then
					exitCode = code or 0
					commandOk = exitCode == 0
				else
					exitCode = 0
					commandOk = true
				end
			else
				exitCode = type(code) == "number" and code or 1
				commandOk = false
			end
		end

		local body = ""
		if commandSpec and commandSpec.outputPath then
			body = Utils.readFile(commandSpec.outputPath) or ""
		end
		local info = ""
		if commandSpec and commandSpec.infoPath then
			info = Utils.readFile(commandSpec.infoPath) or ""
		end
		local errBody = ""
		if commandSpec and commandSpec.errPath then
			errBody = Utils.readFile(commandSpec.errPath) or ""
		end

		removeTempPaths(commandSpec and commandSpec.cleanupPaths)

		local httpCode = nil
		local matchCode = info:match("(%d%d%d)")
		if matchCode then
			httpCode = tonumber(matchCode)
		end

		return {
			ok = commandOk,
			code = exitCode,
			stderr = errBody,
			http = httpCode,
			body = body,
			info = info,
		}
	end

	function Services.httpPostJson(url, payload, headers, timeout)
		local bodyStr = payload or ""
		if Services.HttpClient.https and Services.HttpClient.https.postJson then
			local body, code = Services.HttpClient.https.postJson(url, bodyStr, headers, timeout)
			if body then
				return body, code
			end
		end

		local headerParts = Services._buildCurlHeaders(headers, { contentType = "application/json" })
		local maxTime = timeout or Config.Const.SUPABASE_TIMEOUT
		local sep = package.config:sub(1, 1)
		local tempPayload, payloadErr = Services._writeTempPayload(bodyStr)
		if not tempPayload then
			return nil, payloadErr
		end

		if sep == "\\" then
			local outputPath, outErr = Utils.makeTempPath("out")
			if not outputPath then
				Utils.removeFile(tempPayload)
				return nil, "tmpname_failed:" .. tostring(outErr)
			end
			local errPath, errErr = Utils.makeTempPath("err")
			if not errPath then
				removeTempPaths({ tempPayload, outputPath })
				return nil, "tmpname_failed:" .. tostring(errErr)
			end
			local runResult = Services.CurlCompat.runWindowsSync(function(tlsCompatFlag)
				return string.format(
					'curl%s -sS -L -g -m %d -X POST %s --data-binary "@%s" "%s" > "%s" 2> "%s"',
					Services.CurlCompat.buildTlsOption(tlsCompatFlag),
					maxTime,
					table.concat(headerParts, " "),
					tempPayload,
					url,
					outputPath,
					errPath
				)
			end, {
				context = "http_post_json",
				resetPaths = { outputPath, errPath },
				bodyPath = outputPath,
				errPath = errPath,
			})
			removeTempPaths({ tempPayload, outputPath, errPath })
			if not runResult.ok then
				local errMsg = runResult.stderr ~= "" and runResult.stderr or "curl_failed"
				return nil, errMsg
			end
			if runResult.body == "" then
				return nil, "empty_response"
			end
			return runResult.body, nil
		end

		local outputPath, outErr = Utils.makeTempPath("out")
		if not outputPath then
			Utils.removeFile(tempPayload)
			return nil, "tmpname_failed:" .. tostring(outErr)
		end
		local infoPath, infoErr = Utils.makeTempPath("info")
		if not infoPath then
			removeTempPaths({ tempPayload, outputPath })
			return nil, "tmpname_failed:" .. tostring(infoErr)
		end
		local errPath, errErr = Utils.makeTempPath("err")
		if not errPath then
			removeTempPaths({ tempPayload, outputPath, infoPath })
			return nil, "tmpname_failed:" .. tostring(errErr)
		end

		local userAgent = string.format("%s/%s", Config.Const.SCRIPT_NAME, trim(Config.Const.SCRIPT_VERSION))
		local macFlags = string.format(
			'--http1.1 -sS -L -g --connect-timeout 30 --keepalive-time 1 --compressed -4 --no-sessionid --tcp-nodelay -A "%s"',
			userAgent
		)
		local curlCommand = string.format(
			'curl %s -m %d -X POST %s --data-binary @%q "%s" -o %q -w "%%{http_code}" > %q 2> %q',
			macFlags,
			maxTime,
			table.concat(headerParts, " "),
			tempPayload,
			url,
			outputPath,
			infoPath,
			errPath
		)
		local runResult = Services._runCurlAndCollect({
			command = curlCommand,
			outputPath = outputPath,
			infoPath = infoPath,
			errPath = errPath,
			cleanupPaths = { tempPayload, outputPath, infoPath, errPath },
		})
		if not runResult.ok then
			local errMsg = runResult.stderr ~= "" and runResult.stderr or "curl_failed"
			return nil, errMsg
		end
		if runResult.body == "" then
			return nil, "empty_response"
		end
		return runResult.body, runResult.http
	end

	function Services.httpPostEventStream(url, payload, headers, timeout, onEvent)
		local bodyStr = payload or ""
		local headerParts = Services._buildCurlHeaders(headers, {
			contentType = "application/json",
			accept = "application/json",
			clearExpect = true,
		})
		local maxTime = timeout or Config.Const.SUPABASE_TIMEOUT
		local sep = package.config:sub(1, 1)
		local tempPayload, payloadErr = Services._writeTempPayload(bodyStr)
		if not tempPayload then
			return false, payloadErr
		end

		local streamError = nil
		local statusCode = nil
		local sseDataLines = {}
		local lineBuffer = ""
		local doneMarkers = {
			["[done]"] = true,
			["[end]"] = true,
			["[complete]"] = true,
			["done"] = true,
			["end"] = true,
			["complete"] = true,
		}

		local function invokeOnEvent(eventObj)
			if type(onEvent) ~= "function" then
				return true
			end
			local ok, result, err = pcall(onEvent, eventObj)
			if not ok then
				return false, tostring(result)
			end
			if result == false then
				return false, tostring(err or "event_callback_failed")
			end
			return true
		end

		local function dispatchEventPayload(rawPayload)
			rawPayload = trim(rawPayload or "")
			rawPayload = rawPayload:gsub("^\239\187\191", "")
			if rawPayload == "" then
				return true
			end
			local lowerPayload = rawPayload:lower()
			local compactPayload = lowerPayload:gsub("%s+", "")
			if doneMarkers[lowerPayload] or doneMarkers[compactPayload] then
				return invokeOnEvent({ _done = true })
			end
			if rawPayload:match("^data:%s*") then
				rawPayload = trim(rawPayload:gsub("^data:%s*", "", 1))
				lowerPayload = rawPayload:lower()
				compactPayload = lowerPayload:gsub("%s+", "")
				if doneMarkers[lowerPayload] or doneMarkers[compactPayload] then
					return invokeOnEvent({ _done = true })
				end
			end
			local firstChar = rawPayload:sub(1, 1)
			if firstChar ~= "{" and firstChar ~= "[" then
				local objStart = rawPayload:find("{", 1, true)
				local arrStart = rawPayload:find("[", 1, true)
				local startPos = nil
				if objStart and arrStart then
					startPos = math.min(objStart, arrStart)
				else
					startPos = objStart or arrStart
				end
				if not startPos then
					return true
				end
				rawPayload = trim(rawPayload:sub(startPos))
			end
			if rawPayload:sub(1, 1) == "[" then
				local compactControl = rawPayload:gsub("%s+", "")
				local lowerControl = compactControl:lower()
				if doneMarkers[lowerControl] then
					return invokeOnEvent({ _done = true })
				end
				if compactControl:match("^%[[A-Za-z_%-]+%]$") then
					return true
				end
			end
			local decoded, decodePos, decodeErr = json.decode(rawPayload)
			if type(decoded) ~= "table" then
				local reason = tostring(decodeErr or decodePos or "unknown")
				local payloadPreview = rawPayload:gsub("%s+", " ")
				if #payloadPreview > 120 then
					payloadPreview = payloadPreview:sub(1, 120) .. "..."
				end
				return false, "stream_json_decode_failed:" .. reason .. "|payload=" .. payloadPreview
			end
			return invokeOnEvent(decoded)
		end

		local function flushSseEvent()
			if #sseDataLines == 0 then
				return true
			end
			local payloadText = table.concat(sseDataLines, "\n")
			sseDataLines = {}
			return dispatchEventPayload(payloadText)
		end

		local function processParsedLine(line)
			line = (line or ""):gsub("\r$", "")
			local normalizedLine = trim(line)
			if normalizedLine:match("^__CURL_HTTP_CODE__:") then
				statusCode = tonumber(normalizedLine:match(":(%d%d%d)$")) or tonumber(normalizedLine:match("(%d%d%d)"))
				return true
			end
			if normalizedLine:match("^%%?%{http_code%}$") then
				return true
			end
			if normalizedLine:match("^data:%s*") then
				sseDataLines[#sseDataLines + 1] = normalizedLine:gsub("^data:%s*", "")
				return true
			end
			if normalizedLine == "" then
				return flushSseEvent()
			end
			if
				normalizedLine:match("^event:%s*")
				or normalizedLine:match("^id:%s*")
				or normalizedLine:match("^retry:%s*")
				or normalizedLine:match("^:%s*")
			then
				return true
			end
			local okFlush, flushErr = flushSseEvent()
			if not okFlush then
				return false, flushErr
			end
			return dispatchEventPayload(normalizedLine)
		end

		local function processChunkText(chunk, finalize)
			if chunk and chunk ~= "" then
				lineBuffer = lineBuffer .. chunk
			end
			while true do
				local pos = lineBuffer:find("\n", 1, true)
				if not pos then
					break
				end
				local line = lineBuffer:sub(1, pos - 1)
				lineBuffer = lineBuffer:sub(pos + 1)
				local ok, err = processParsedLine(line)
				if not ok then
					return false, err
				end
			end
			if finalize and lineBuffer ~= "" then
				local ok, err = processParsedLine(lineBuffer)
				if not ok then
					return false, err
				end
				lineBuffer = ""
			end
			return true
		end

		if sep == "\\" then
			if type(runHiddenWindowsCommandAsync) ~= "function" then
				Utils.removeFile(tempPayload)
				return false, "event_stream_windows_async_unavailable"
			end

			local streamPath, streamErr = Utils.makeTempPath("stream")
			if not streamPath then
				Utils.removeFile(tempPayload)
				return false, "tmpname_failed:" .. tostring(streamErr)
			end
			local infoPath, infoErr = Utils.makeTempPath("info")
			if not infoPath then
				removeTempPaths({ tempPayload, streamPath })
				return false, "tmpname_failed:" .. tostring(infoErr)
			end
			local errPath, errErr = Utils.makeTempPath("err")
			if not errPath then
				removeTempPaths({ tempPayload, streamPath, infoPath })
				return false, "tmpname_failed:" .. tostring(errErr)
			end

			local userAgent = string.format("%s/%s", Config.Const.SCRIPT_NAME, trim(Config.Const.SCRIPT_VERSION))
			local function readDelta(path, offset)
				local f = io.open(path, "rb")
				if f then
					local size = f:seek("end") or 0
					if size < offset then
						offset = 0
					end
					if size > offset then
						f:seek("set", offset)
						local content = f:read(size - offset) or ""
						f:close()
						return content, size
					end
					f:close()
					return "", offset
				end
				local all = Utils.readFile(path) or ""
				local size = #all
				if size < offset then
					offset = 0
				end
				if size > offset then
					return all:sub(offset + 1), size
				end
				return "", offset
			end

			local tlsCompatFlag = nil
			while true do
				streamError = nil
				statusCode = nil
				sseDataLines = {}
				lineBuffer = ""
				Utils.removeFile(streamPath)
				Utils.removeFile(infoPath)
				Utils.removeFile(errPath)

				local winFlags = string.format(
					'--http1.1 -sS -N --no-buffer -L -g --connect-timeout 30 --keepalive-time 1 --tcp-nodelay -A "%s"%s',
					userAgent,
					Services.CurlCompat.buildTlsOption(tlsCompatFlag)
				)
				local curlCommand = string.format(
					'curl %s -m %d -X POST %s --data-binary "@%s" "%s" -o "%s" -w "__CURL_HTTP_CODE__:%s" > "%s" 2> "%s"',
					winFlags,
					maxTime,
					table.concat(headerParts, " "),
					tempPayload,
					url,
					streamPath,
					"%{http_code}",
					infoPath,
					errPath
				)

				local processHandle, launchErr = runHiddenWindowsCommandAsync(curlCommand)
				if not processHandle then
					removeTempPaths({ tempPayload, streamPath, infoPath, errPath })
					return false, "curl_hidden_async_failed:" .. tostring(launchErr)
				end

				local streamOffset = 0
				local exitCode = nil
				while true do
					local chunk
					chunk, streamOffset = readDelta(streamPath, streamOffset)
					if chunk ~= "" then
						local ok, err = processChunkText(chunk, false)
						if not ok then
							streamError = err
							break
						end
					end
					local done, code = processHandle:poll(120)
					if done then
						exitCode = code
						break
					end
				end

				if streamError then
					pcall(function()
						processHandle:terminate(1)
					end)
				end
				pcall(function()
					processHandle:close()
				end)

				if not streamError then
					local finalChunk
					finalChunk, streamOffset = readDelta(streamPath, streamOffset)
					if finalChunk ~= "" then
						local ok, err = processChunkText(finalChunk, false)
						if not ok then
							streamError = err
						end
					end
				end
				if not streamError then
					local okChunk, chunkErr = processChunkText("", true)
					if not okChunk then
						streamError = chunkErr
					end
				end
				if not streamError then
					local okFlush, flushErr = flushSseEvent()
					if not okFlush then
						streamError = flushErr
					end
				end

				local infoBody = Utils.readFile(infoPath) or ""
				if not statusCode then
					statusCode = tonumber(infoBody:match("__CURL_HTTP_CODE__:(%d%d%d)"))
						or tonumber(infoBody:match("(%d%d%d)"))
				end
				local errBody = Utils.readFile(errPath) or ""

				if streamError then
					removeTempPaths({ tempPayload, streamPath, infoPath, errPath })
					return false, streamError
				end
				if tonumber(exitCode or 1) == 0 then
					removeTempPaths({ tempPayload, streamPath, infoPath, errPath })
					return true, {
						status = statusCode,
						stderr = errBody,
					}
				end

				local combinedError = table.concat({ errBody, infoBody }, "\n")
				local nextFlag, retryReason = Services.CurlCompat.getNextTlsFlag(tlsCompatFlag, combinedError)
				if not nextFlag then
					removeTempPaths({ tempPayload, streamPath, infoPath, errPath })
					local errMsg = errBody ~= "" and errBody or ("curl_failed:" .. tostring(exitCode))
					return false, errMsg
				end

				Services.CurlCompat.logRetry("http_post_event_stream", nextFlag, retryReason, combinedError)
				tlsCompatFlag = nextFlag
			end
		end

		local errPath, errErr = Utils.makeTempPath("err")
		if not errPath then
			Utils.removeFile(tempPayload)
			return false, "tmpname_failed:" .. tostring(errErr)
		end

		local userAgent = string.format("%s/%s", Config.Const.SCRIPT_NAME, trim(Config.Const.SCRIPT_VERSION))
		local unixFlags = string.format(
			'--http1.1 -sS -N -L -g --connect-timeout 30 --keepalive-time 1 --compressed -4 --no-sessionid --tcp-nodelay -A "%s"',
			userAgent
		)
		local curlCommand = string.format(
			'curl %s -m %d -X POST %s --data-binary @%q "%s" -w "\\n__CURL_HTTP_CODE__:%s\\n" 2> %q',
			unixFlags,
			maxTime,
			table.concat(headerParts, " "),
			tempPayload,
			url,
			"%{http_code}",
			errPath
		)

		local pipe = io.popen(curlCommand, "r")
		if not pipe then
			removeTempPaths({ tempPayload, errPath })
			return false, "curl_popen_failed"
		end

		for line in pipe:lines() do
			local ok, err = processParsedLine(line)
			if not ok then
				streamError = err
				break
			end
		end

		if not streamError then
			local okFlush, flushErr = flushSseEvent()
			if not okFlush then
				streamError = flushErr
			end
		end

		local closeOk, closeHow, closeCode = pipe:close()
		local commandOk = false
		if type(closeOk) == "number" then
			commandOk = closeOk == 0
		elseif closeOk == true then
			if closeHow == "exit" then
				commandOk = (closeCode or 0) == 0
			else
				commandOk = true
			end
		end

		local errBody = Utils.readFile(errPath) or ""
		removeTempPaths({ tempPayload, errPath })

		if streamError then
			return false, streamError
		end
		if not commandOk then
			local errMsg = errBody ~= "" and errBody or "curl_failed"
			return false, errMsg
		end
		return true, {
			status = statusCode,
			stderr = errBody,
		}
	end

	function Services.supabaseCheckUpdate(pluginId)
		if not pluginId or pluginId == "" then
			return nil
		end
		local url =
			string.format("%s/functions/v1/check_update?pid=%s", Config.Const.SUPABASE_URL, Utils.urlEncode(pluginId))
		local headers = {
			Authorization = "Bearer " .. Config.Const.SUPABASE_ANON_KEY,
			apikey = Config.Const.SUPABASE_ANON_KEY,
			["Content-Type"] = "application/json",
			["User-Agent"] = string.format("%s/%s", Config.Const.SCRIPT_NAME, Config.Const.SCRIPT_VERSION),
		}
		local body, status = Services.httpGet(url, headers, Config.Const.SUPABASE_TIMEOUT)
		if not body then
			if status then
				print(string.format("[Update] Supabase request failed: %s", tostring(status)))
			end
			return nil
		end
		if status and status ~= 200 then
			if status ~= 400 and status ~= 404 then
				print(string.format("[Update] Unexpected status code: %s", tostring(status)))
			end
			return nil
		end
		local decoded, pos, err = json.decode(body)
		if type(decoded) ~= "table" then
			print(
				string.format(
					"[Update] Invalid response: %s (pos=%s, err=%s)",
					tostring(body),
					tostring(pos),
					tostring(err)
				)
			)
			return nil
		end
		return decoded
	end

	App.Services = Services
end

local SEP = package.config:sub(1, 1)

local IS_WINDOWS = (SEP == "\\")
local IS_MACOS = false
if not IS_WINDOWS then
	local jitOs = type(jit) == "table" and type(jit.os) == "string" and jit.os:lower() or ""
	if jitOs == "osx" or jitOs == "macos" then
		IS_MACOS = true
	else
		local okPipe, pipe = pcall(io.popen, "uname -s 2>/dev/null", "r")
		if okPipe and pipe then
			local value = (pipe:read("*a") or ""):gsub("%s+", ""):lower()
			pcall(function()
				pipe:close()
			end)
			IS_MACOS = (value == "darwin")
		end
	end
end

---
--- 3. 工具模块 (App.Utils)
---
do
	local Utils = App.Utils
	local function isUtf8ContinuationByte(byte)
		return byte and byte >= 0x80 and byte <= 0xBF
	end

	function Utils.trim(str)
		return (str:gsub("^%s*(.-)%s*$", "%1"))
	end

	function Utils.utf8CharCount(text)
		text = tostring(text or "")
		local length = #text
		local index = 1
		local count = 0
		while index <= length do
			local first = text:byte(index)
			if first < 0x80 then
				index = index + 1
			elseif first >= 0xC2 and first <= 0xDF then
				if isUtf8ContinuationByte(text:byte(index + 1)) then
					index = index + 2
				else
					index = index + 1
				end
			elseif first >= 0xE0 and first <= 0xEF then
				if isUtf8ContinuationByte(text:byte(index + 1)) and isUtf8ContinuationByte(text:byte(index + 2)) then
					index = index + 3
				else
					index = index + 1
				end
			elseif first >= 0xF0 and first <= 0xF4 then
				if
					isUtf8ContinuationByte(text:byte(index + 1))
					and isUtf8ContinuationByte(text:byte(index + 2))
					and isUtf8ContinuationByte(text:byte(index + 3))
				then
					index = index + 4
				else
					index = index + 1
				end
			else
				index = index + 1
			end
			count = count + 1
		end
		return count
	end

	trim = Utils.trim
	utf8CharCount = Utils.utf8CharCount

	function Utils.runShellCommand(command)
		if IS_WINDOWS and type(runHiddenWindowsCommand) == "function" then
			local ok, code = runHiddenWindowsCommand(command)
			if not ok then
				print(string.format("Command failed (%s)", tostring(code)))
			end
			return ok == true
		end

		local res, how, code = os.execute(command)
		if type(res) == "number" then
			return res == 0
		end
		if res == true then
			if how == "exit" then
				return (code or 0) == 0
			end
			return true
		end
		return false
	end
	runShellCommand = Utils.runShellCommand

	local function shellQuoteUnix(str)
		str = tostring(str or "")
		return "'" .. str:gsub("'", [['"'"']]) .. "'"
	end

	function Utils.runShellCommandAsync(command)
		command = tostring(command or "")
		if command == "" then
			return nil, "missing_command"
		end
		if IS_WINDOWS then
			if type(runHiddenWindowsCommandAsync) == "function" then
				return runHiddenWindowsCommandAsync(command)
			end
			return nil, "windows_async_unavailable"
		end

		local scriptPath, scriptErr = App.Utils.makeTempPath("sh")
		if not scriptPath then
			return nil, "tmpname_failed:" .. tostring(scriptErr)
		end
		local statusPath, statusErr = App.Utils.makeTempPath("status")
		if not statusPath then
			Utils.removeFile(scriptPath)
			return nil, "tmpname_failed:" .. tostring(statusErr)
		end

		local scriptContent = table.concat({
			"#!/bin/sh",
			command,
			"status=$?",
			string.format("printf '%%s' \"$status\" > %s", shellQuoteUnix(statusPath)),
			'exit "$status"',
			"",
		}, "\n")
		local wroteScript, writeErr = App.Utils.writeFile(scriptPath, scriptContent)
		if not wroteScript then
			Utils.removeFile(scriptPath)
			Utils.removeFile(statusPath)
			return nil, "async_script_write_failed:" .. tostring(writeErr)
		end
		os.execute(string.format("chmod +x %s >/dev/null 2>&1", shellQuoteUnix(scriptPath)))

		local launchCommand = string.format("sh %s >/dev/null 2>&1 & echo $!", shellQuoteUnix(scriptPath))
		local pipe = io.popen("sh -c " .. shellQuoteUnix(launchCommand), "r")
		if not pipe then
			Utils.removeFile(scriptPath)
			Utils.removeFile(statusPath)
			return nil, "async_launch_failed"
		end
		local pidText = pipe:read("*a") or ""
		pipe:close()
		local pid = tonumber(trim(pidText))
		if not pid then
			Utils.removeFile(scriptPath)
			Utils.removeFile(statusPath)
			return nil, "async_pid_unavailable"
		end

		local function readExitCode(path)
			local body = App.Utils.readFile(path)
			local code = body and tonumber((body:gsub("%s+", ""))) or nil
			return code
		end

		local handle = {
			_pid = pid,
			_scriptPath = scriptPath,
			_statusPath = statusPath,
			_closed = false,
			_exitCode = nil,
		}

		local function cleanupHandle(self)
			if self._scriptPath and self._scriptPath ~= "" then
				Utils.removeFile(self._scriptPath)
				self._scriptPath = nil
			end
			if self._statusPath and self._statusPath ~= "" then
				Utils.removeFile(self._statusPath)
				self._statusPath = nil
			end
			self._closed = true
		end

		function handle:poll(_)
			if self._closed then
				return true, self._exitCode or 1
			end
			local probe = os.execute(string.format("kill -0 %d >/dev/null 2>&1", self._pid))
			local running = false
			if type(probe) == "number" then
				running = probe == 0
			elseif probe == true then
				running = true
			end
			if running then
				return false, nil
			end
			self._exitCode = readExitCode(self._statusPath) or 1
			cleanupHandle(self)
			return true, self._exitCode
		end

		function handle:terminate(exitCode)
			if self._closed then
				return true, self._exitCode or exitCode or 1
			end
			local signal = tonumber(exitCode) or 15
			if signal <= 0 then
				signal = 15
			end
			os.execute(string.format("kill -%d %d >/dev/null 2>&1", signal, self._pid))
			self._exitCode = readExitCode(self._statusPath) or 1
			cleanupHandle(self)
			return true, self._exitCode
		end

		function handle:close()
			if self._closed then
				return true
			end
			cleanupHandle(self)
			return true
		end

		return handle
	end
	runShellCommandAsync = Utils.runShellCommandAsync
	------------------------------------------------------------------
	-- runShellCommand
	------------------------------------------------------------------

	function Utils.clampIndex(value, size)
		if type(value) ~= "number" then
			return 0
		end
		if size <= 0 then
			return 0
		end
		if value < 0 then
			return 0
		end
		if value > size - 1 then
			return size - 1
		end
		return value
	end
	clampIndex = Utils.clampIndex

	function Utils.joinPath(...)
		local parts = { ... }
		if #parts == 0 then
			return ""
		end
		local path = tostring(parts[1] or "")
		for i = 2, #parts do
			local part = tostring(parts[i] or "")
			if part ~= "" then
				local last = path:sub(-1)
				if
					path ~= ""
					and last ~= PATH_SEP
					and last ~= "/"
					and last ~= "\\"
					and part:sub(1, 1) ~= PATH_SEP
					and part:sub(1, 1) ~= "/"
				then
					path = path .. PATH_SEP
				elseif
					path ~= ""
					and (last == "/" or last == "\\")
					and (part:sub(1, 1) == "/" or part:sub(1, 1) == "\\")
				then
					part = part:sub(2)
				end
				path = path .. part
			end
		end
		return path
	end

	-- Windows helpers (ffi): hidden command + UTF-8 safe file IO
	local winfs = {}
	if IS_WINDOWS then
		local okFfi, ffi = pcall(require, "ffi")
		if okFfi and ffi then
			local okKernel, kernel32 = pcall(ffi.load, "kernel32")
			local okMsvcrt, msvcrt = pcall(ffi.load, "msvcrt")

			if okKernel and kernel32 then
				local CP_UTF8 = 65001
				local CREATE_NO_WINDOW = 0x08000000
				local STARTF_USESHOWWINDOW = 0x00000001
				local INFINITE = 0xFFFFFFFF

				pcall(
					ffi.cdef,
					[[
                typedef unsigned short WORD;
                typedef unsigned long DWORD;
                typedef int BOOL;
                typedef void* HANDLE;
                typedef wchar_t* LPWSTR;
                typedef const wchar_t* LPCWSTR;
                typedef void* LPVOID;
                typedef unsigned char BYTE;

                typedef struct _STARTUPINFOW {
                    DWORD cb;
                    LPWSTR lpReserved;
                    LPWSTR lpDesktop;
                    LPWSTR lpTitle;
                    DWORD dwX;
                    DWORD dwY;
                    DWORD dwXSize;
                    DWORD dwYSize;
                    DWORD dwXCountChars;
                    DWORD dwYCountChars;
                    DWORD dwFillAttribute;
                    DWORD dwFlags;
                    WORD wShowWindow;
                    WORD cbReserved2;
                    BYTE *lpReserved2;
                    HANDLE hStdInput;
                    HANDLE hStdOutput;
                    HANDLE hStdError;
                } STARTUPINFOW;

                typedef struct _PROCESS_INFORMATION {
                    HANDLE hProcess;
                    HANDLE hThread;
                    DWORD dwProcessId;
                    DWORD dwThreadId;
                } PROCESS_INFORMATION;

                BOOL CreateProcessW(
                    LPCWSTR lpApplicationName,
                    LPWSTR lpCommandLine,
                    LPVOID lpProcessAttributes,
                    LPVOID lpThreadAttributes,
                    BOOL bInheritHandles,
                    DWORD dwCreationFlags,
                    LPVOID lpEnvironment,
                    LPCWSTR lpCurrentDirectory,
                    STARTUPINFOW *lpStartupInfo,
                    PROCESS_INFORMATION *lpProcessInformation
                );

                DWORD WaitForSingleObject(HANDLE hHandle, DWORD dwMilliseconds);
                BOOL GetExitCodeProcess(HANDLE hProcess, DWORD *lpExitCode);
                BOOL TerminateProcess(HANDLE hProcess, unsigned int uExitCode);
                BOOL CloseHandle(HANDLE hObject);
                DWORD GetLastError(void);
                int MultiByteToWideChar(unsigned int CodePage, DWORD dwFlags,
                const char *lpMultiByteStr, int cbMultiByte,
                wchar_t *lpWideCharStr, int cchWideChar);
                ]]
				)

				local function utf8ToWideBuffer(str)
					local okReq, required = pcall(function()
						return kernel32.MultiByteToWideChar(CP_UTF8, 0, str, -1, nil, 0)
					end)
					if not okReq or required == 0 then
						return nil
					end
					local buffer = ffi.new("wchar_t[?]", required)
					local okFill, filled = pcall(function()
						return kernel32.MultiByteToWideChar(CP_UTF8, 0, str, -1, buffer, required)
					end)
					if not okFill or filled == 0 then
						return nil
					end
					return buffer
				end

				local okCreate = pcall(function()
					return kernel32.CreateProcessW
				end)
				local okM2W = pcall(function()
					return kernel32.MultiByteToWideChar
				end)
				local okWait = pcall(function()
					return kernel32.WaitForSingleObject
				end)
				local okExit = pcall(function()
					return kernel32.GetExitCodeProcess
				end)
				local okClose = pcall(function()
					return kernel32.CloseHandle
				end)
				local okTerminate = pcall(function()
					return kernel32.TerminateProcess
				end)
				if okCreate and okM2W and okWait and okExit and okClose then
					local WAIT_TIMEOUT = 0x00000102
					local STILL_ACTIVE = 259

					local function closeProcessHandles(processState)
						if not processState then
							return
						end
						if processState.hProcess then
							pcall(function()
								kernel32.CloseHandle(processState.hProcess)
							end)
							processState.hProcess = nil
						end
						if processState.hThread then
							pcall(function()
								kernel32.CloseHandle(processState.hThread)
							end)
							processState.hThread = nil
						end
					end

					local function createHiddenProcess(command)
						local comspec = os.getenv("COMSPEC") or "C:\\Windows\\System32\\cmd.exe"
						local fullCommand = string.format('"%s" /c %s', comspec, command)
						local cmdBuffer = utf8ToWideBuffer(fullCommand)
						if not cmdBuffer then
							return nil, "command_encoding_failed"
						end

						local startupInfo = ffi.new("STARTUPINFOW")
						startupInfo.cb = ffi.sizeof(startupInfo)
						startupInfo.dwFlags = STARTF_USESHOWWINDOW
						startupInfo.wShowWindow = 0 -- SW_HIDE

						local processInfo = ffi.new("PROCESS_INFORMATION")
						local created = kernel32.CreateProcessW(
							nil,
							cmdBuffer,
							nil,
							nil,
							false,
							CREATE_NO_WINDOW,
							nil,
							nil,
							startupInfo,
							processInfo
						)
						if created == 0 then
							return nil, kernel32.GetLastError()
						end
						return {
							hProcess = processInfo.hProcess,
							hThread = processInfo.hThread,
						}
					end

					runHiddenWindowsCommand = function(command)
						local processState, createErr = createHiddenProcess(command)
						if not processState then
							return false, createErr
						end
						kernel32.WaitForSingleObject(processState.hProcess, INFINITE)
						local exitCodeArr = ffi.new("DWORD[1]", 0)
						local hasCode = kernel32.GetExitCodeProcess(processState.hProcess, exitCodeArr) ~= 0
						local exitCode = hasCode and tonumber(exitCodeArr[0]) or 1
						closeProcessHandles(processState)
						return exitCode == 0, exitCode
					end

					runHiddenWindowsCommandAsync = function(command)
						local processState, createErr = createHiddenProcess(command)
						if not processState then
							return nil, createErr
						end

						local handle = {
							_process = processState,
							_closed = false,
							_exitCode = nil,
						}

						function handle:poll(waitMs)
							if self._closed then
								return true, self._exitCode or 1
							end
							waitMs = tonumber(waitMs) or 0
							if waitMs < 0 then
								waitMs = 0
							end
							local waitResult = kernel32.WaitForSingleObject(self._process.hProcess, waitMs)
							local exitCodeArr = ffi.new("DWORD[1]", 0)
							local hasCode = kernel32.GetExitCodeProcess(self._process.hProcess, exitCodeArr) ~= 0
							local exitCode = hasCode and tonumber(exitCodeArr[0]) or nil
							if waitResult == WAIT_TIMEOUT and exitCode == STILL_ACTIVE then
								return false, nil
							end
							self._exitCode = exitCode or 1
							self:close()
							return true, self._exitCode
						end

						function handle:terminate(exitCode)
							if self._closed then
								return true, self._exitCode
							end
							if okTerminate and self._process and self._process.hProcess then
								local code = tonumber(exitCode) or 1
								pcall(function()
									kernel32.TerminateProcess(self._process.hProcess, code)
								end)
							end
							return self:poll(0)
						end

						function handle:close()
							if self._closed then
								return true
							end
							closeProcessHandles(self._process)
							self._closed = true
							return true
						end

						return handle
					end
				end
			end

			if okKernel and okMsvcrt and kernel32 and msvcrt then
				local CP_UTF8 = 65001

				local okSizeT = pcall(function()
					return ffi.sizeof("size_t")
				end)
				if not okSizeT then
					pcall(ffi.cdef, [[ typedef unsigned long size_t; ]])
				end

				pcall(
					ffi.cdef,
					[[
                typedef struct _iobuf FILE;
                FILE* _wfopen(const wchar_t* filename, const wchar_t* mode);
                int fclose(FILE* stream);
                size_t fread(void* ptr, size_t size, size_t count, FILE* stream);
                size_t fwrite(const void* ptr, size_t size, size_t count, FILE* stream);
                int fseek(FILE* stream, long offset, int origin);
                long ftell(FILE* stream);
                int fflush(FILE* stream);
                int _wrename(const wchar_t* oldname, const wchar_t* newname);
                int _wremove(const wchar_t* path);
                ]]
				)

				local okM2W = pcall(function()
					return kernel32.MultiByteToWideChar
				end)
				local okWfopen = pcall(function()
					return msvcrt._wfopen
				end)
				local okFclose = pcall(function()
					return msvcrt.fclose
				end)
				local okFseek = pcall(function()
					return msvcrt.fseek
				end)
				local okFtell = pcall(function()
					return msvcrt.ftell
				end)
				local okFread = pcall(function()
					return msvcrt.fread
				end)
				local okFwrite = pcall(function()
					return msvcrt.fwrite
				end)
				local okFflush = pcall(function()
					return msvcrt.fflush
				end)
				local okWrename = pcall(function()
					return msvcrt._wrename
				end)
				local okWremove = pcall(function()
					return msvcrt._wremove
				end)
				local canWinfs = okM2W and okWfopen and okFclose and okFseek and okFtell and okFread and okFwrite

				if canWinfs then
					local function utf8ToWide(str)
						local okReq, needed = pcall(function()
							return kernel32.MultiByteToWideChar(CP_UTF8, 0, str, -1, nil, 0)
						end)
						if not okReq or needed == 0 then
							return nil
						end
						local buf = ffi.new("wchar_t[?]", needed)
						local okFill, filled = pcall(function()
							return kernel32.MultiByteToWideChar(CP_UTF8, 0, str, -1, buf, needed)
						end)
						if not okFill or filled == 0 then
							return nil
						end
						return buf
					end

					local function openWide(path, mode)
						local wpath = utf8ToWide(path or "")
						local wmode = utf8ToWide(mode or "rb")
						if not wpath or not wmode then
							return nil, "path_encoding_failed"
						end
						local f = msvcrt._wfopen(wpath, wmode)
						if f == nil then
							return nil, "wfopen_failed"
						end
						return f
					end

					function winfs.readFile(path)
						local f, err = openWide(path, "rb")
						if not f then
							return nil, err
						end
						msvcrt.fseek(f, 0, 2) -- SEEK_END
						local size = tonumber(msvcrt.ftell(f)) or 0
						if size < 0 then
							size = 0
						end
						msvcrt.fseek(f, 0, 0) -- SEEK_SET
						local buf = ffi.new("uint8_t[?]", size)
						local read = msvcrt.fread(buf, 1, size, f)
						msvcrt.fclose(f)
						return ffi.string(buf, read)
					end

					function winfs.writeFile(path, content)
						local f, err = openWide(path, "wb")
						if not f then
							return false, err
						end
						local data = content or ""
						local len = #data
						local written = msvcrt.fwrite(data, 1, len, f)
						msvcrt.fclose(f)
						if written ~= len then
							return false, "write_failed"
						end
						return true
					end

					function winfs.fileExists(path)
						local f = select(1, openWide(path, "rb"))
						if f then
							msvcrt.fclose(f)
							return true
						end
						return false
					end

					function winfs.getFileSize(path)
						local f = select(1, openWide(path, "rb"))
						if not f then
							return nil
						end
						msvcrt.fseek(f, 0, 2)
						local size = tonumber(msvcrt.ftell(f))
						msvcrt.fclose(f)
						return size
					end

					if okFflush then
						function winfs.openBinaryWriter(path)
							local f, err = openWide(path, "wb")
							if not f then
								return nil, err
							end
							local closed = false
							local writer = {}

							function writer:write(data)
								if closed then
									return nil, "file_closed"
								end
								local chunk = data or ""
								local len = #chunk
								if len == 0 then
									return true
								end
								local written = msvcrt.fwrite(chunk, 1, len, f)
								if written ~= len then
									return nil, "write_failed"
								end
								return true
							end

							function writer:flush()
								if closed then
									return nil, "file_closed"
								end
								if msvcrt.fflush(f) ~= 0 then
									return nil, "flush_failed"
								end
								return true
							end

							function writer:close()
								if closed then
									return true
								end
								msvcrt.fclose(f)
								closed = true
								return true
							end

							return writer
						end
					end

					if okWrename then
						function winfs.renameFile(oldPath, newPath)
							local wold = utf8ToWide(oldPath or "")
							local wnew = utf8ToWide(newPath or "")
							if not wold or not wnew then
								return false, "path_encoding_failed"
							end
							if msvcrt._wrename(wold, wnew) ~= 0 then
								return false, "rename_failed"
							end
							return true
						end
					end

					if okWremove then
						function winfs.removeFile(path)
							if not path or path == "" then
								return true
							end
							if winfs.fileExists and not winfs.fileExists(path) then
								return true
							end
							local wpath = utf8ToWide(path or "")
							if not wpath then
								return false, "path_encoding_failed"
							end
							if msvcrt._wremove(wpath) ~= 0 then
								return false, "remove_failed"
							end
							return true
						end
					end
				end
			end
		end
	end

	function Utils.readFile(path)
		if IS_WINDOWS and winfs.readFile then
			local content, err = winfs.readFile(path)
			if content then
				return content
			end
		end
		local fh, err = io.open(path, "r")
		if not fh then
			return nil, err
		end
		local content = fh:read("*a")
		fh:close()
		return content
	end

	function Utils.writeFile(path, content)
		if IS_WINDOWS and winfs.writeFile then
			local ok, err = winfs.writeFile(path, content)
			if ok ~= nil then
				return ok, err
			end
		end
		local fh, err = io.open(path, "wb")
		if not fh then
			return false, err
		end
		fh:write(content or "")
		fh:close()
		return true
	end

	function Utils.openBinaryWriter(path)
		if IS_WINDOWS and winfs.openBinaryWriter then
			local writer, err = winfs.openBinaryWriter(path)
			if writer then
				return writer
			end
			return nil, err
		end
		return io.open(path, "wb")
	end

	function Utils.renameFile(oldPath, newPath)
		if not oldPath or oldPath == "" or not newPath or newPath == "" then
			return false, "invalid_path"
		end
		if IS_WINDOWS and winfs.renameFile then
			local ok, err = winfs.renameFile(oldPath, newPath)
			if ok ~= nil then
				return ok, err
			end
		end
		local ok, err = os.rename(oldPath, newPath)
		if not ok then
			return false, err
		end
		return true
	end

	function Utils.removeFile(path)
		if not path or path == "" then
			return true
		end
		if IS_WINDOWS and winfs.removeFile then
			local ok, err = winfs.removeFile(path)
			if ok ~= nil then
				return ok, err
			end
		end
		local ok, err = os.remove(path)
		if ok == nil then
			return false, err
		end
		return true
	end

	local BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local BASE64_LOOKUP = {}
	for i = 1, #BASE64_ALPHABET do
		BASE64_LOOKUP[BASE64_ALPHABET:sub(i, i)] = i - 1
	end

	local function stripDataUrlPrefix(raw)
		local text = tostring(raw or "")
		if text:match("^data:[^,]+,") then
			text = text:gsub("^data:[^,]+,", "")
		end
		text = text:gsub("[^%w%+/%=]", "")
		return text
	end

	function Utils.base64Decode(raw)
		local payload = stripDataUrlPrefix(raw)
		if payload == "" then
			return ""
		end

		local chunks = {}
		local outIndex = 1
		local length = #payload
		local i = 1
		while i <= length do
			local c1 = payload:sub(i, i)
			local c2 = payload:sub(i + 1, i + 1)
			local c3 = payload:sub(i + 2, i + 2)
			local c4 = payload:sub(i + 3, i + 3)
			i = i + 4

			local n1 = BASE64_LOOKUP[c1]
			local n2 = BASE64_LOOKUP[c2]
			if n1 == nil or n2 == nil then
				break
			end

			local n3 = (c3 ~= "=" and BASE64_LOOKUP[c3]) or 0
			local n4 = (c4 ~= "=" and BASE64_LOOKUP[c4]) or 0

			local b1 = n1 * 4 + math.floor(n2 / 16)
			local b2 = (n2 % 16) * 16 + math.floor(n3 / 4)
			local b3 = (n3 % 4) * 64 + n4

			if c3 == "=" then
				chunks[outIndex] = string.char(b1)
				outIndex = outIndex + 1
				break
			elseif c4 == "=" then
				chunks[outIndex] = string.char(b1, b2)
				outIndex = outIndex + 1
				break
			else
				chunks[outIndex] = string.char(b1, b2, b3)
				outIndex = outIndex + 1
			end
		end
		return table.concat(chunks)
	end

	function Utils.decodeBase64ToFile(dataUrl, destPath)
		if type(destPath) ~= "string" or destPath == "" then
			return false, "invalid_dest_path"
		end
		local bytes = App.Utils.base64Decode(dataUrl)
		if not bytes or bytes == "" then
			return false, "decode_failed"
		end
		return App.Utils.writeFile(destPath, bytes)
	end

	function Utils.getTempDir()
		return App.Paths.tempDir
	end

	function Utils.makeTempPath(ext)
		local dir = App.Utils.getTempDir() or App.Paths.scriptDir
		if not App.Utils.ensureDir(dir) then
			return nil, "temp_dir_unavailable"
		end
		local prefix = string.format("tmp_%s_%d_", App.Config.Const.SCRIPT_NAME:gsub("%s+", ""):lower(), os.time())
		local counter = 0
		local suffix = ext or ""
		if suffix ~= "" and suffix:sub(1, 1) ~= "." then
			suffix = "." .. suffix
		end
		local path
		repeat
			counter = counter + 1
			path = App.Utils.joinPath(dir, string.format("%s%04d%s", prefix, counter, suffix))
			if counter > 1000 then
				return nil, "temp_name_exhausted"
			end
		until not App.Utils.fileExists(path)
		return path
	end

	function Utils.urlEncode(str)
		if not str then
			return ""
		end
		return tostring(str):gsub("[^%w%-%._~]", function(ch)
			return string.format("%%%02X", ch:byte())
		end)
	end

	local function tableIsArray(tbl)
		if type(tbl) ~= "table" then
			return false
		end
		local maxIndex = 0
		local count = 0
		for k, _ in pairs(tbl) do
			if type(k) ~= "number" then
				return false
			end
			if k > maxIndex then
				maxIndex = k
			end
			count = count + 1
		end
		if maxIndex == 0 then
			return true
		end
		return maxIndex == count
	end

	local function cloneForJson(value)
		if type(value) ~= "table" then
			return value
		end
		if tableIsArray(value) then
			local result = {}
			local length = #value
			for i = 1, length do
				result[i] = cloneForJson(value[i])
			end
			return result
		end
		local result = {}
		local order = rawget(value, "__order")
		local metaOrder = {}
		if type(order) == "table" then
			for _, key in ipairs(order) do
				if key ~= "__order" and value[key] ~= nil then
					table.insert(metaOrder, key)
				end
			end
		end
		for k, v in pairs(value) do
			if k ~= "__order" then
				result[k] = cloneForJson(v)
			end
		end
		if #metaOrder > 0 then
			setmetatable(result, { __jsonorder = metaOrder })
		end
		return result
	end

	function Utils.writeJsonOrdered(path, data, state)
		local prepared = cloneForJson(data)
		local encodeState = state or { indent = "  " }
		local ok, content = pcall(json.encode, prepared, encodeState)
		if not ok then
			return false, content
		end
		return App.Utils.writeFile(path, content)
	end

	function Utils.fileExists(path)
		if not path or path == "" then
			return false
		end
		if IS_WINDOWS and winfs.fileExists then
			return winfs.fileExists(path)
		end
		local fh = io.open(path, "rb")
		if fh then
			fh:close()
			return true
		end
		return false
	end

	function Utils.getFileSize(path)
		if IS_WINDOWS and winfs.getFileSize then
			return winfs.getFileSize(path)
		end
		local fh = io.open(path, "rb")
		if not fh then
			return nil
		end
		local size = fh:seek("end")
		fh:close()
		return size
	end

	function Utils.ensureDir(path)
		if not path or path == "" then
			return true
		end

		local okLfs, lfs = pcall(require, "lfs")
		if okLfs and lfs then
			local attr = lfs.attributes(path)
			if attr and attr.mode == "directory" then
				return true
			end
		elseif bmd and type(bmd.fileexists) == "function" then
			local ok, exists = pcall(bmd.fileexists, path)
			if ok and exists then
				return true
			end
		end

		if PATH_SEP == "\\" then
			local command = string.format('if not exist "%s" mkdir "%s"', path, path)
			local ok = runShellCommand(command)
			if not ok then
				print("Failed to create directory: " .. tostring(path))
				return false
			end
			return true
		else
			local escaped = path:gsub("'", "'\\''")
			local ok = runShellCommand("mkdir -p '" .. escaped .. "'")
			if not ok then
				print("Failed to create directory: " .. tostring(path))
				return false
			end
			return true
		end
	end

	function Utils.removeDir(path)
		if not path or path == "" then
			return true
		end
		local sep = package.config:sub(1, 1)
		local command
		if sep == "\\" then
			command = string.format('rmdir /S /Q "%s"', path)
		else
			command = string.format("rm -rf '%s'", path:gsub("'", "'\\''"))
		end
		local ok = runShellCommand(command)
		return ok ~= false
	end

	function Utils.sanitizeFileName(text, maxLen)
		maxLen = maxLen or 32
		local sanitized = tostring(text or ""):gsub("[\r\n]", " ")
		sanitized = sanitized:gsub("[%z\1-\31]", " ")
		sanitized = sanitized:gsub('[<>:"/\\|%?*]', " ")
		sanitized = sanitized:gsub("%s+", " ")
		sanitized = sanitized:match("^%s*(.-)%s*$") or ""

		if sanitized == "" then
			sanitized = "audio"
		end
		-- 6. UTF-8 安全截取 (防止切断汉字)
		if #sanitized > maxLen then
			local tmp = sanitized:sub(1, maxLen)
			local byte = string.byte(tmp, -1)
			-- 如果最后一个字节是 UTF-8 后续字节 (10xxxxxx, 即 128-191)，说明切在字中间了
			while byte and byte >= 128 and byte < 192 do
				tmp = tmp:sub(1, -2)
				byte = string.byte(tmp, -1)
			end
			-- 如果剩下一个孤立的起始字节 (11xxxxxx, 即 >= 192)，也去掉
			if byte and byte >= 192 then
				tmp = tmp:sub(1, -2)
			end
			sanitized = tmp
		end

		return sanitized
	end

	function Utils.nextAvailableFile(dir, options)
		options = options or {}
		if not dir or dir == "" then
			return nil, "missing_dir"
		end

		local baseName = App.Utils.sanitizeFileName(options.baseName or "audio", options.maxBaseLength or 32)
		if options.replaceSpaces then
			baseName = baseName:gsub("%s+", "_")
		end

		local extension = options.extension or ""
		if extension ~= "" and extension:sub(1, 1) ~= "." then
			extension = "." .. extension
		end

		local timestamp
		if options.timestamp ~= nil then
			timestamp = tostring(options.timestamp)
		else
			local fmt = options.timestampFormat or "%Y%m%d-%H%M%S"
			timestamp = os.date(fmt)
		end

		local pattern = options.pattern or "%s_%s_%02d%s"
		local index = options.startIndex or 1
		local maxAttempts = options.maxAttempts
		local attempts = 0

		while true do
			local candidateName = string.format(pattern, baseName, timestamp, index, extension)
			local candidatePath = App.Utils.joinPath(dir, candidateName)
			if not App.Utils.fileExists(candidatePath) then
				return candidatePath
			end
			index = index + 1
			attempts = attempts + 1
			if maxAttempts and attempts >= maxAttempts then
				return nil, "name_exhausted"
			end
		end
	end

	local jsonObjectMeta = {
		__newindex = function(t, k, v)
			rawset(t, k, v)
			if type(k) ~= "number" then
				local order = rawget(t, "__order")
				if not order then
					order = {}
					rawset(t, "__order", order)
				end
				order[#order + 1] = k
			end
		end,
	}

	function Utils.decodeJsonWithOrder(content)
		if not content then
			return nil, "empty content"
		end
		local data, pos, err = json.decode(content, 1, nil, jsonObjectMeta)
		if not data then
			local msg = err or ("JSON decode error at position " .. tostring(pos))
			return nil, msg
		end
		return data
	end

	function Utils.readJson(path)
		local content, err = App.Utils.readFile(path)
		if not content then
			return nil, err
		end
		return App.Utils.decodeJsonWithOrder(content)
	end

	function Utils.iterObject(tbl)
		if type(tbl) ~= "table" then
			return function() end
		end
		local order = rawget(tbl, "__order")
		if order and #order > 0 then
			local index = 0
			local count = #order
			return function()
				index = index + 1
				if index <= count then
					local key = order[index]
					return key, rawget(tbl, key)
				end
			end
		end
		return pairs(tbl)
	end
end

---
--- 4. 路径模块 (App.Paths)
---
do
	local Paths = {}
	local Utils = App.Utils

	local function discoverScriptDir()
		local info = debug.getinfo(1, "S")
		local source = info and info.source or ""
		if source:sub(1, 1) == "@" then
			source = source:sub(2)
		end
		local dir = source:match("(.*[\\/])")
		if not dir or dir == "" then
			return "."
		end
		dir = dir:gsub("[\\/]+$", "")
		return dir
	end

	Paths.scriptDir = discoverScriptDir()
	Paths.configDir = Utils.joinPath(Paths.scriptDir, "config")
	Paths.voicesDir = Utils.joinPath(Paths.scriptDir, "voices")
	Paths.tempDir = Utils.joinPath(Paths.scriptDir, "temp")

	function Paths.inConfig(...)
		return Utils.joinPath(Paths.configDir, ...)
	end

	function Paths.inVoices(...)
		return Utils.joinPath(Paths.voicesDir, ...)
	end

	App.Paths = Paths
end

---
--- 7. 状态模块 + 配置加载 (App.State/App.Config.load)
---
do
	local State = App.State or {}
	local Config = App.Config

	State.providerSecrets = State.providerSecrets or {}
	State.azure = State.azure or {}
	State.minimax = State.minimax or {}
	State.openai = State.openai or {}

	buildLabelPair = function(cn, en)
		local textCn = cn or en or ""
		local textEn = en or cn or ""
		return { cn = textCn, en = textEn }
	end

	normalizeVoiceLabel = function(name, fallback)
		if type(name) == "string" and #name > 0 then
			return buildLabelPair(name, name)
		end
		return buildLabelPair(fallback or "Unknown", fallback or "Unknown")
	end

	mapGenderLabel = function(gender)
		return App.Config.Const.GENDER_LABELS[gender] or buildLabelPair(gender or "Other", gender or "Other")
	end

	resolveLocaleLabels = function(locale, localeName)
		local entry = LOCALE_NAME_LABELS[locale]
		local cn = (entry and entry.cn) or localeName or locale
		local en = (entry and entry.en) or localeName or locale
		if entry and not entry.en then
			entry.en = en
		end
		return { cn = cn, en = en }
	end

	normalizeCloneVoiceStorage = function(data)
		if type(data) ~= "table" then
			return false
		end

		local merged = {}
		local seenIds = {}
		local seenNames = {}
		local changed = false

		local function normalizeKey(value)
			if value == nil then
				return ""
			end
			return tostring(value):gsub("^%s*(.-)%s*$", "%1")
		end

		local function appendEntries(list)
			if type(list) ~= "table" then
				return
			end
			for _, entry in ipairs(list) do
				if type(entry) ~= "table" then
					changed = true
				else
					local voiceId = normalizeKey(entry.voice_id)
					local voiceName = normalizeKey(entry.voice_name):lower()
					local duplicated = false
					if voiceId ~= "" and seenIds[voiceId] then
						duplicated = true
					elseif voiceName ~= "" and seenNames[voiceName] then
						duplicated = true
					end
					if duplicated then
						changed = true
					else
						table.insert(merged, entry)
						if voiceId ~= "" then
							seenIds[voiceId] = true
						end
						if voiceName ~= "" then
							seenNames[voiceName] = true
						end
					end
				end
			end
		end

		local current = data.minimax_clone_voices
		local hasPrimaryKey = rawget(data, "minimax_clone_voices") ~= nil
		local hasLegacyKey = rawget(data, "minimax_clone_voices_cn") ~= nil
			or rawget(data, "minimax_clone_voices_en") ~= nil
		appendEntries(current)
		appendEntries(data.minimax_clone_voices_cn)
		appendEntries(data.minimax_clone_voices_en)

		local function sameArray(a, b)
			if type(a) ~= "table" then
				return false
			end
			if #a ~= #b then
				return false
			end
			for i = 1, #b do
				if a[i] ~= b[i] then
					return false
				end
			end
			return true
		end

		if #merged > 0 or hasPrimaryKey or hasLegacyKey then
			if not sameArray(current, merged) then
				changed = true
			end
			data.minimax_clone_voices = merged
		elseif rawget(data, "minimax_clone_voices") ~= nil then
			data.minimax_clone_voices = nil
			changed = true
		end
		if data.minimax_clone_voices_cn ~= nil then
			data.minimax_clone_voices_cn = nil
			changed = true
		end
		if data.minimax_clone_voices_en ~= nil then
			data.minimax_clone_voices_en = nil
			changed = true
		end
		return changed
	end

	function Config.load()
		local settings = App.Utils.readJson(App.Paths.inConfig("TTS_settings.json")) or {}
		local defaultSettings = App.Config.Const.DEFAULT_SETTINGS or {}
		local function readSavedValue(key, fallback, aliases)
			local value = settings[key]
			if value ~= nil then
				return value
			end
			for _, alias in ipairs(aliases or {}) do
				value = settings[alias]
				if value ~= nil then
					return value
				end
			end
			return fallback
		end
		local defaultLocale = defaultSettings.EN and "en" or ((defaultSettings.CN and "cn") or "en")
		local savedLocale = readSavedValue("EN", defaultSettings.EN) and "en"
			or ((readSavedValue("CN", defaultSettings.CN) and "cn") or defaultLocale)
		local defaultOutputFormatIndex =
			clampIndex(defaultSettings.OUTPUT_FORMATS or 0, #App.Config.Const.SHARED_FORMATS)

		App.Config.Settings.saved = settings
		App.Config.Settings.defaults = {
			outputPath = defaultSettings.Path or "",
			locale = defaultLocale,
			outputFormatIndex = defaultOutputFormatIndex,
		}
		App.Config.Settings.loaded = {
			outputPath = readSavedValue("Path", App.Config.Settings.defaults.outputPath),
			locale = savedLocale,
			outputFormatIndex = clampIndex(
				readSavedValue("OUTPUT_FORMATS", App.Config.Settings.defaults.outputFormatIndex),
				#App.Config.Const.SHARED_FORMATS
			),
		}
		App.Config.Settings.locale = App.Config.Settings.loaded.locale
		App.Config.Settings.outputPath = App.Config.Settings.loaded.outputPath
		App.Config.Settings.cloneInfo = {
			cn = App.Utils.readFile(App.Paths.inConfig("script_clone_info_cn.html")) or "",
			en = App.Utils.readFile(App.Paths.inConfig("script_clone_info_en.html")) or "",
		}
		App.Config.Status = App.Utils.readJson(App.Paths.inConfig("status.json")) or {}

		-- 加载语言标签 JSON
		local localeLabelsPath = App.Paths.inConfig("locale_labels.json")
		local localeLabels = App.Utils.readJson(localeLabelsPath)
		if type(localeLabels) == "table" then
			LOCALE_NAME_LABELS = localeLabels
		else
			LOCALE_NAME_LABELS = {}
		end
		-- 新增：加载风格标签 JSON
		local styleLabelsPath = App.Paths.inConfig("style_labels.json")
		local styleLabelsData = App.Utils.readJson(styleLabelsPath)
		if type(styleLabelsData) == "table" then
			AZURE_STYLE_LABELS = styleLabelsData
		else
			AZURE_STYLE_LABELS = {}
		end

		local minimaxVoicesPath = App.Paths.inVoices("minimax_voices.json")
		local minimaxVoicesData = App.Utils.readJson(minimaxVoicesPath) or {}
		if normalizeCloneVoiceStorage(minimaxVoicesData) then
			local ok, writeErr = App.Utils.writeJsonOrdered(minimaxVoicesPath, minimaxVoicesData, { indent = "  " })
			if not ok then
				print("[DaVinci TTS] Failed to normalize MiniMax clone storage: " .. tostring(writeErr))
			end
		end
		local openaiVoicesPath = App.Paths.inVoices("openai_voices.json")
		local openaiVoicesData = App.Utils.readJson(openaiVoicesPath) or {}
		local azureVoiceListPath = App.Paths.inVoices("azure_voices.json")
		local azureVoiceList = App.Utils.readJson(azureVoiceListPath) or {}
		local edgeVoiceListPath = App.Paths.inVoices("edge_voices.json")
		local edgeVoicesData = App.Utils.readJson(edgeVoiceListPath) or {}

		App.Config.Settings.formats = App.Config.Const.SHARED_FORMATS

		local azure = App.Config.Azure
		local styleLabels = {}
		azure.languageOrder = {}
		azure.languagesList = {}
		azure.languages = {}
		azure.voiceTypeOrder = {}
		azure.voiceTypes = {}
		azure.voiceTypesList = {}
		azure.voiceMultilingualMap = {}
		azure.edgeVoices = edgeVoicesData or {}
		azure.outputFormats = {}
		for _, fmt in ipairs(App.Config.Const.SHARED_FORMATS) do
			table.insert(azure.outputFormats, { id = fmt.azureId, label = fmt.label, formatId = fmt.id })
		end
		azure.styleLabels = styleLabels

		local seenLocales = {}
		local seenVoiceTypes = {}
		for _, voiceInfo in ipairs(azureVoiceList) do
			if type(voiceInfo) == "table" then
				local locale = voiceInfo.Locale or voiceInfo.LocaleName or "Unknown"
				local localeName = voiceInfo.LocaleName or locale
				if locale and not seenLocales[locale] then
					seenLocales[locale] = true
					local langLabels = resolveLocaleLabels(locale, localeName)
					table.insert(azure.languageOrder, locale)
					table.insert(azure.languagesList, {
						id = locale,
						labels = langLabels,
					})
					azure.languages[locale] = {
						labels = langLabels,
						voices = {},
					}
				end
				local langBucket = azure.languages[locale]
				if langBucket then
					local voiceId = voiceInfo.ShortName
						or voiceInfo.Name
						or string.format("%s_%d", locale or "voice", #langBucket.voices + 1)
					local gender = voiceInfo.Gender or "Neutral"
					if gender and not seenVoiceTypes[gender] then
						seenVoiceTypes[gender] = true
						azure.voiceTypes[gender] = { labels = mapGenderLabel(gender) }
						table.insert(azure.voiceTypeOrder, gender)
					end
					local styles = {}
					if type(voiceInfo.StyleList) == "table" then
						for _, styleCode in ipairs(voiceInfo.StyleList) do
							if styleCode and styleCode ~= "" then
								table.insert(styles, styleCode)
								-- 修改：使用加载的 JSON 数据填充 styleLabels
								if not styleLabels[styleCode] then
									local labelData = AZURE_STYLE_LABELS[styleCode]
									if labelData then
										styleLabels[styleCode] = labelData
									else
										styleLabels[styleCode] = { en = styleCode, cn = styleCode }
									end
								end
							end
						end
					end
					local multilingual = {}
					if type(voiceInfo.SecondaryLocaleList) == "table" then
						for _, code in ipairs(voiceInfo.SecondaryLocaleList) do
							if code and code ~= "" then
								table.insert(multilingual, code)
							end
						end
					end
					local labelSource = voiceInfo.LocalName or voiceInfo.DisplayName or voiceInfo.Name or voiceId
					local voiceEntry = {
						id = voiceId,
						type = gender or "Neutral",
						labels = normalizeVoiceLabel(labelSource, voiceId),
						styles = styles,
						multilingual = multilingual,
					}
					table.insert(langBucket.voices, voiceEntry)
					if #multilingual > 0 then
						azure.voiceMultilingualMap[voiceId] = multilingual
					end
				end
			end
		end

		if #azure.languageOrder == 0 then
			local fallbackLocale = "zh-CN"
			azure.languageOrder = { fallbackLocale }
			azure.languagesList = {
				{ id = fallbackLocale, labels = buildLabelPair("中文（普通话）", "Chinese (Mandarin)") },
			}
			azure.languages[fallbackLocale] = {
				labels = buildLabelPair("中文（普通话）", "Chinese (Mandarin)"),
				voices = {
					{
						id = "zh-CN-XiaoxiaoNeural",
						type = "Female",
						labels = buildLabelPair("晓晓", "Xiaoxiao"),
						styles = {},
						multilingual = {},
					},
				},
			}
			azure.voiceTypes.Female = { labels = mapGenderLabel("Female") }
			azure.voiceTypeOrder = { "Female" }
		end

		if #azure.voiceTypeOrder == 0 then
			azure.voiceTypeOrder = { "Neutral" }
			azure.voiceTypes.Neutral = { labels = mapGenderLabel("Neutral") }
		end

		azure.voiceTypesList = {}
		for _, typeId in ipairs(azure.voiceTypeOrder) do
			local typeEntry = azure.voiceTypes[typeId]
			if typeEntry then
				table.insert(azure.voiceTypesList, { id = typeId, labels = typeEntry.labels })
			end
		end
		azure.languageTranslations = {}
		for k, v in pairs(LOCALE_NAME_LABELS) do
			if v and v.cn then
				azure.languageTranslations[k] = v.cn
			end
		end

		local minimax = App.Config.MiniMax
		minimax.models = {}
		for _, id in ipairs(App.Config.Const.MINIMAX_MODELS) do
			table.insert(minimax.models, { id = id, labels = buildLabelPair(id, id) })
		end

		minimax.soundEffects = {}
		for _, entry in ipairs(App.Config.Const.MINIMAX_SOUND_EFFECTS) do
			table.insert(minimax.soundEffects, { id = entry.id, labels = buildLabelPair(entry.cn, entry.en) })
		end

		minimax.emotions = {}
		for _, entry in ipairs(App.Config.Const.MINIMAX_EMOTIONS) do
			table.insert(minimax.emotions, { id = entry.id, labels = buildLabelPair(entry.cn, entry.en) })
		end

		minimax.languages = {}
		minimax.voices = {}
		local languageOrder = {}
		local languageSeen = {}
		minimax.cloneMap = {}
		minimax.cloneLangCounts = {}
		minimax.voiceFilePath = voicesListPath

		local function ensureLanguageEntry(lang)
			if not minimax.voices[lang] then
				minimax.voices[lang] = {}
			end
			if not languageSeen[lang] then
				table.insert(languageOrder, lang)
				languageSeen[lang] = true
			end
			if minimax.cloneLangCounts[lang] == nil then
				minimax.cloneLangCounts[lang] = 0
			end
			return minimax.voices[lang]
		end

		local function appendVoices(list, options)
			options = options or {}
			local isClone = options.isClone
			for _, voice in ipairs(list or {}) do
				if type(voice) == "table" then
					local lang = trim(voice.language or "")
					local voiceId = trim(voice.voice_id or "")
					local voiceName = trim(voice.voice_name or "")
					if lang ~= "" and not (voiceId == "" and voiceName == "") then
						local voiceList = ensureLanguageEntry(lang)
						local entry = {
							id = (voiceId ~= "" and voiceId) or voiceName,
							labels = buildLabelPair(
								(voiceName ~= "" and voiceName) or voiceId,
								(voiceName ~= "" and voiceName) or voiceId
							),
							isClone = isClone and true or nil,
						}
						if isClone then
							local insertAt = (minimax.cloneLangCounts[lang] or 0) + 1
							table.insert(voiceList, insertAt, entry)
							minimax.cloneLangCounts[lang] = insertAt
							if voiceId ~= "" then
								minimax.cloneMap[voiceId] = lang
							end
						else
							table.insert(voiceList, entry)
						end
					end
				end
			end
		end

		-- 根据 intl 设置选择加载 EN 或 CN 系统语音；克隆语音统一使用单桶
		local isIntl = readSavedValue("minimax_intlCheckBox", defaultSettings.minimax_intlCheckBox) and true or false
		if isIntl then
			appendVoices(minimaxVoicesData.minimax_clone_voices or {}, { isClone = true })
			appendVoices(minimaxVoicesData.minimax_system_voice_en or {})
		else
			appendVoices(minimaxVoicesData.minimax_clone_voices or {}, { isClone = true })
			appendVoices(minimaxVoicesData.minimax_system_voice_cn or {})
		end
		-- 保存原始数据引用以便动态切换
		minimax.rawVoicesData = minimaxVoicesData

		for _, lang in ipairs(languageOrder) do
			table.insert(minimax.languages, { id = lang, labels = buildLabelPair(lang, lang) })
		end

		minimax.defaults = {
			apiKey = defaultSettings.minimax_API_KEY or "",
			groupId = defaultSettings.minimax_GROUP_ID or "",
			intl = defaultSettings.minimax_intlCheckBox and true or false,
			modelIndex = clampIndex(defaultSettings.minimax_Model or 0, #minimax.models),
			languageIndex = clampIndex(defaultSettings.minimax_Language or 0, #minimax.languages),
			voiceIndex = defaultSettings.minimax_Voice or 0,
			emotionIndex = clampIndex(defaultSettings.minimax_Emotion or 0, #minimax.emotions),
			soundEffectIndex = clampIndex(defaultSettings.minimaxVoiceEffect or 0, #minimax.soundEffects),
			voiceTimbre = defaultSettings.minimaxVoiceTimbre or 0,
			voiceIntensity = defaultSettings.minimaxVoiceIntensity or 0,
			voicePitch = defaultSettings.minimaxVoicePitch or 0,
			rate = defaultSettings.minimax_Rate or 1.0,
			volume = defaultSettings.minimax_Volume or 1.0,
			pitch = defaultSettings.minimax_Pitch or 0,
			subtitle = defaultSettings.minimax_SubtitleCheckBox and true or false,
			breakMs = defaultSettings.minimax_Break or 50,
		}
		minimax.loaded = {
			apiKey = readSavedValue("minimax_API_KEY", minimax.defaults.apiKey),
			groupId = readSavedValue("minimax_GROUP_ID", minimax.defaults.groupId),
			intl = isIntl,
			modelIndex = clampIndex(readSavedValue("minimax_Model", minimax.defaults.modelIndex), #minimax.models),
			languageIndex = clampIndex(
				readSavedValue("minimax_Language", minimax.defaults.languageIndex),
				#minimax.languages
			),
			voiceIndex = readSavedValue("minimax_Voice", minimax.defaults.voiceIndex),
			emotionIndex = clampIndex(
				readSavedValue("minimax_Emotion", minimax.defaults.emotionIndex),
				#minimax.emotions
			),
			soundEffectIndex = clampIndex(
				readSavedValue("minimax_VoiceEffect", minimax.defaults.soundEffectIndex, { "minimaxVoiceEffect" }),
				#minimax.soundEffects
			),
			voiceTimbre = readSavedValue(
				"minimax_VoiceTimbre",
				minimax.defaults.voiceTimbre,
				{ "minimaxVoiceTimbre" }
			),
			voiceIntensity = readSavedValue(
				"minimax_VoiceIntensity",
				minimax.defaults.voiceIntensity,
				{ "minimaxVoiceIntensity" }
			),
			voicePitch = readSavedValue(
				"minimax_VoicePitch",
				minimax.defaults.voicePitch,
				{ "minimaxVoicePitch" }
			),
			rate = readSavedValue("minimax_Rate", minimax.defaults.rate),
			volume = readSavedValue("minimax_Volume", minimax.defaults.volume),
			pitch = readSavedValue("minimax_Pitch", minimax.defaults.pitch),
			subtitle = readSavedValue("minimax_SubtitleCheckBox", minimax.defaults.subtitle) and true or false,
			breakMs = readSavedValue("minimax_Break", minimax.defaults.breakMs),
		}

		minimax.cloneDefaults = {
			onlyAddId = true,
			needNoiseReduction = false,
			needVolumeNormalization = false,
			previewText = "",
			displayInfo = App.Config.Settings.cloneInfo.cn or "",
		}

		local openai = App.Config.OpenAI
		openai.models = {}
		for _, id in ipairs(App.Config.Const.OPENAI_MODELS) do
			table.insert(openai.models, { id = id, labels = buildLabelPair(id, id) })
		end

		openai.voices = {}
		for _, voiceId in ipairs((openaiVoicesData or {}).voices or {}) do
			table.insert(openai.voices, { id = voiceId, labels = buildLabelPair(voiceId, voiceId) })
		end
		if #openai.voices == 0 then
			openai.voices = {
				{ id = "alloy", labels = buildLabelPair("alloy", "alloy") },
			}
		end

		local instructionData = App.Utils.readJson(App.Paths.inConfig("instruction.json")) or {}
		openai.presets = {}
		openai.presetMap = {}
		for presetName, presetInfo in App.Utils.iterObject(instructionData) do
			local description = ""
			if type(presetInfo) == "table" then
				description = presetInfo.Description or ""
			end
			local entry = {
				id = presetName,
				labels = buildLabelPair(presetName, presetName),
				description = description,
			}
			table.insert(openai.presets, entry)
			openai.presetMap[presetName] = entry
		end
		if #openai.presets == 0 then
			local entry = { id = "Custom", labels = buildLabelPair("Custom", "Custom"), description = "" }
			openai.presets = { entry }
			openai.presetMap = { Custom = entry }
		end

		openai.defaults = {
			apiKey = defaultSettings.OpenAI_API_KEY or "",
			baseUrl = defaultSettings.OpenAI_BASE_URL or "",
			modelIndex = clampIndex(defaultSettings.OpenAI_Model or 0, #openai.models),
			voiceIndex = clampIndex(defaultSettings.OpenAI_Voice or 0, #openai.voices),
			presetIndex = clampIndex(defaultSettings.OpenAI_Preset or 0, #openai.presets),
			rate = defaultSettings.OpenAI_Rate or 1.0,
			instruction = defaultSettings.OpenAI_Instruction or "",
		}
		openai.loaded = {
			apiKey = readSavedValue("OpenAI_API_KEY", openai.defaults.apiKey),
			baseUrl = readSavedValue("OpenAI_BASE_URL", openai.defaults.baseUrl),
			modelIndex = clampIndex(readSavedValue("OpenAI_Model", openai.defaults.modelIndex), #openai.models),
			voiceIndex = clampIndex(readSavedValue("OpenAI_Voice", openai.defaults.voiceIndex), #openai.voices),
			presetIndex = clampIndex(
				readSavedValue("OpenAI_Preset", openai.defaults.presetIndex),
				#openai.presets
			),
			rate = readSavedValue("OpenAI_Rate", openai.defaults.rate),
			instruction = readSavedValue("OpenAI_Instruction", openai.defaults.instruction),
		}

		local useApiSetting = readSavedValue("USE_API", nil)
		if useApiSetting == nil then
			local legacyDisable = readSavedValue("UNUSE_API", nil)
			if legacyDisable ~= nil then
				useApiSetting = not legacyDisable
			else
				useApiSetting = defaultSettings.USE_API and true or false
			end
		end
		App.Config.Azure.defaults = {
			apiKey = defaultSettings.API_KEY or "",
			region = defaultSettings.REGION or "",
			useApi = defaultSettings.USE_API and true or false,
			languageIndex = clampIndex(defaultSettings.LANGUAGE or 0, #azure.languageOrder),
			voiceTypeIndex = clampIndex(defaultSettings.TYPE or 0, #azure.voiceTypeOrder),
			voiceIndex = defaultSettings.NAME or 0,
			styleIndex = defaultSettings.STYLE or 0,
			multilingualIndex = defaultSettings.MULTILINGUAL or 0,
			breakMs = defaultSettings.BREAKTIME or 50,
			styleDegree = defaultSettings.STYLEDEGREE or 1.0,
			rate = defaultSettings.RATE or 1.0,
			pitch = defaultSettings.PITCH or 1.0,
			volume = defaultSettings.VOLUME or 1.0,
			outputFormatIndex = clampIndex(App.Config.Settings.defaults.outputFormatIndex or 0, #azure.outputFormats),
		}
		App.Config.Azure.loaded = {
			apiKey = readSavedValue("API_KEY", App.Config.Azure.defaults.apiKey),
			region = readSavedValue("REGION", App.Config.Azure.defaults.region),
			useApi = useApiSetting and true or false,
			languageIndex = clampIndex(readSavedValue("LANGUAGE", App.Config.Azure.defaults.languageIndex), #azure.languageOrder),
			voiceTypeIndex = clampIndex(
				readSavedValue("TYPE", App.Config.Azure.defaults.voiceTypeIndex),
				#azure.voiceTypeOrder
			),
			voiceIndex = readSavedValue("NAME", App.Config.Azure.defaults.voiceIndex),
			styleIndex = readSavedValue("STYLE", App.Config.Azure.defaults.styleIndex),
			multilingualIndex = readSavedValue("MULTILINGUAL", App.Config.Azure.defaults.multilingualIndex),
			breakMs = readSavedValue("BREAKTIME", App.Config.Azure.defaults.breakMs, { "BREAK" }),
			styleDegree = readSavedValue("STYLEDEGREE", App.Config.Azure.defaults.styleDegree),
			rate = readSavedValue("RATE", App.Config.Azure.defaults.rate),
			pitch = readSavedValue("PITCH", App.Config.Azure.defaults.pitch),
			volume = readSavedValue("VOLUME", App.Config.Azure.defaults.volume),
			outputFormatIndex = clampIndex(App.Config.Settings.loaded.outputFormatIndex or 0, #azure.outputFormats),
		}
	end

	Config.load()
	State.locale = Config.Settings.locale or "en"

	App.Config = Config
	App.State = State
end

