local donationQrCache = nil

local function ensureDonationQrs()
	local cached = donationQrCache
	if
		cached
		and cached.paypal
		and cached.wechat
		and App.Utils.fileExists(cached.paypal)
		and App.Utils.fileExists(cached.wechat)
	then
		return cached
	end

	local tempDir = App.Utils.getTempDir() or App.Paths.scriptDir
	if not App.Utils.ensureDir(tempDir) then
		return nil, "temp_dir_unavailable"
	end

	local paypalPath = App.Utils.joinPath(tempDir, "sponsor_paypal_qr.png")
	local wechatPath = App.Utils.joinPath(tempDir, "sponsor_wechat_qr.png")

	if not App.Utils.fileExists(paypalPath) then
		local ok, err = App.Utils.decodeBase64ToFile(App.Config.Const.QR_PAYPAL_BASE64, paypalPath)
		if not ok then
			return nil, err or "create_paypal_qr_failed"
		end
	end
	if not App.Utils.fileExists(wechatPath) then
		local ok, err = App.Utils.decodeBase64ToFile(App.Config.Const.QR_WECHAT_BASE64, wechatPath)
		if not ok then
			return nil, err or "create_wechat_qr_failed"
		end
	end

	donationQrCache = { paypal = paypalPath, wechat = wechatPath }
	return donationQrCache
end

local donationQrs = ensureDonationQrs() or { paypal = "", wechat = "" }
local DEFAULT_WINDOW_STYLESHEET = "*{font-size:14px;}"

local function createSimpleDialogWindow(windowSpec, content)
	return dispatcher:AddWindow({
		ID = windowSpec.id,
		WindowTitle = windowSpec.title,
		Geometry = windowSpec.geometry,
		Hidden = windowSpec.hidden ~= false,
		StyleSheet = windowSpec.styleSheet or DEFAULT_WINDOW_STYLESHEET,
	}, content)
end

local function createDialogLineEditRow(options)
	options = options or {}
	local labelProps = {
		Text = options.labelText or "",
		Alignment = { AlignRight = false },
		Weight = options.labelWeight or 0.2,
	}
	if options.labelId and options.labelId ~= "" then
		labelProps.ID = options.labelId
	end
	local inputProps = {
		ID = options.inputId,
		Text = options.inputText or "",
		Weight = options.inputWeight or 0.8,
	}
	if options.placeholderText ~= nil then
		inputProps.PlaceholderText = options.placeholderText
	end
	if options.echoMode ~= nil then
		inputProps.EchoMode = options.echoMode
	end
	return ui:HGroup({
		Weight = options.rowWeight or 1,
		ui:Label(labelProps),
		ui:LineEdit(inputProps),
	})
end

local function createDialogButtonsRow(confirmId, confirmText, registerId, registerText)
	return ui:HGroup({
		Weight = 1,
		ui:Button({
			ID = confirmId,
			Text = confirmText,
			Weight = 1,
		}),
		ui:Button({
			ID = registerId,
			Text = registerText,
			Weight = 1,
		}),
	})
end

