		SAMPLE_RATE = 48000,
		CHANNELS = 1,
		BITS_PER_SAMPLE = 16,
		FRAME_BYTES = 2,
		CHUNK_BYTES = 8192,
	}

	local okFfi, ffi = pcall(require, "ffi")
	if okFfi and ffi then
		Audio.ffi = ffi
	end

	local function readLe16(str, pos)
		local b1, b2 = str:byte(pos, pos + 1)
		if not b1 or not b2 then
			return nil
		end
		return b1 + (b2 * 256)
	end

	local function readLe32(str, pos)
		local b1, b2, b3, b4 = str:byte(pos, pos + 3)
		if not b1 or not b2 or not b3 or not b4 then
			return nil
		end
		return b1 + (b2 * 256) + (b3 * 65536) + (b4 * 16777216)
	end

	local WavStreamParser = {}
	WavStreamParser.__index = WavStreamParser

	function WavStreamParser.new()
		return setmetatable({
			buffer = "",
			riffChecked = false,
			formatInfo = nil,
			dataStart = nil,
			dataSize = nil,
			chunkScanPos = 13,
			ready = false,
			errorMessage = nil,
		}, WavStreamParser)
	end

	function WavStreamParser:_validateFormat(payloadStart, chunkSize)
		if chunkSize < 16 then
			return false, localizedText("WAV fmt 数据无效。", "Invalid WAV fmt chunk.")
		end
		local audioFormat = readLe16(self.buffer, payloadStart)
		local channels = readLe16(self.buffer, payloadStart + 2)
		local sampleRate = readLe32(self.buffer, payloadStart + 4)
		local byteRate = readLe32(self.buffer, payloadStart + 8)
		local blockAlign = readLe16(self.buffer, payloadStart + 12)
		local bitsPerSample = readLe16(self.buffer, payloadStart + 14)
		if audioFormat ~= 1 then
			return false, localizedText("Azure 试听只支持 PCM WAV。", "Azure preview requires PCM WAV.")
		end
		if
			channels ~= Audio.Const.CHANNELS
			or sampleRate ~= Audio.Const.SAMPLE_RATE
			or bitsPerSample ~= Audio.Const.BITS_PER_SAMPLE
		then
			return false,
				localizedText(
					"Azure 试听只支持 48kHz / 16-bit / 单声道 PCM。",
					"Azure preview requires 48kHz / 16-bit / mono PCM."
				)
		end
		self.formatInfo = {
			audioFormat = audioFormat,
			channels = channels,
			sampleRate = sampleRate,
			byteRate = byteRate,
			blockAlign = blockAlign,
			bitsPerSample = bitsPerSample,
		}
		return true
	end

	function WavStreamParser:_finalizeHeader()
		if self.ready or not self.formatInfo or not self.dataStart then
			return
		end
		self.buffer = self.buffer:sub(self.dataStart)
		self.dataStart = 1
		self.chunkScanPos = 1
		self.ready = true
	end

	function WavStreamParser:_parseHeader()
		local length = #self.buffer
		if length < 12 then
			return true
		end
		if not self.riffChecked then
			if self.buffer:sub(1, 4) ~= "RIFF" or self.buffer:sub(9, 12) ~= "WAVE" then
				return false,
					localizedText("Azure 返回的不是 WAV 音频。", "Azure preview did not return WAV audio.")
			end
			self.riffChecked = true
			self.chunkScanPos = 13
		end

		local pos = self.chunkScanPos or 13
		while not self.dataStart do
			if length < (pos + 7) then
				break
			end
			local chunkId = self.buffer:sub(pos, pos + 3)
			local chunkSize = readLe32(self.buffer, pos + 4)
			if not chunkSize then
				break
			end
			local payloadStart = pos + 8
			if chunkId == "data" then
				self.dataStart = payloadStart
				self.dataSize = chunkSize
				break
			end
			local payloadEnd = payloadStart + chunkSize - 1
			if length < payloadEnd then
				break
			end
			if chunkId == "fmt " then
				local ok, err = self:_validateFormat(payloadStart, chunkSize)
				if not ok then
					return false, err
				end
			end
			pos = payloadStart + chunkSize
			if (chunkSize % 2) == 1 then
				pos = pos + 1
			end
		end
		self.chunkScanPos = pos
		self:_finalizeHeader()
		return true
	end

	function WavStreamParser:push(bytes)
		if type(bytes) ~= "string" then
			bytes = tostring(bytes or "")
		end
		if bytes ~= "" then
			self.buffer = self.buffer .. bytes
		end
		if not self.ready then
			local ok, err = self:_parseHeader()
			if not ok then
				self.errorMessage = err
				return false, err
			end
		end
		return true
	end

	function WavStreamParser:isReady()
		return self.ready == true
	end

	function WavStreamParser:getFormatInfo()
		return self.formatInfo
	end

	function WavStreamParser:getBufferedBytes()
		if not self.ready then
			return 0
		end
		return #self.buffer
	end

	function WavStreamParser:popPcmChunk(maxBytes)
		if not self.ready or self.buffer == "" then
			return nil
		end
		local available = #self.buffer
		local limit = math.floor(tonumber(maxBytes) or available)
		if limit <= 0 then
			return nil
		end
		local take = math.min(available, limit)
		local chunk = self.buffer:sub(1, take)
		self.buffer = self.buffer:sub(take + 1)
		return chunk
	end

	function WavStreamParser:pushBackPcm(bytes)
		if not self.ready or type(bytes) ~= "string" or bytes == "" then
			return
		end
		self.buffer = bytes .. self.buffer
	end

	Audio.WavStreamParser = WavStreamParser

	function Audio.readGrowingFileChunk(path, readOffset)
		readOffset = tonumber(readOffset) or 0
		local fh, openErr = io.open(path, "rb")
		if not fh then
			return nil, openErr or "open_failed", readOffset
		end
		local size = fh:seek("end") or 0
		if size <= readOffset then
			fh:close()
			return "", nil, readOffset, size
		end
		fh:seek("set", readOffset)
		local payload = fh:read(size - readOffset) or ""
		fh:close()
		return payload, nil, readOffset + #payload, size
	end

	local function loadMacFrameworkLibrary(ffi, candidates)
		local failures = {}
		for _, candidate in ipairs(candidates or {}) do
			local okLoad, lib = pcall(ffi.load, candidate)
			if okLoad and lib then
				return lib, candidate
			end
			failures[#failures + 1] = tostring(candidate) .. ": " .. tostring(lib or "load_failed")
		end
		return nil, table.concat(failures, " | ")
	end

	local function createWindowsSink(formatInfo)
		local ffi = Audio.ffi
		if not ffi then
			return nil,
				localizedText(
					"当前环境缺少 ffi，无法直接播放试听。",
					"ffi is unavailable, so direct preview playback cannot start."
				)
		end
		if not Audio._winmmInitAttempted then
			Audio._winmmInitAttempted = true
			local okCdef = pcall(
				ffi.cdef,
				[[
                typedef void* HANDLE;
                typedef HANDLE HWAVEOUT;
                typedef unsigned short WORD;
                typedef unsigned int UINT;
                typedef unsigned long DWORD;
                typedef uintptr_t DWORD_PTR;
                typedef char* LPSTR;

                typedef struct waveformat_tag {
                    WORD  wFormatTag;
                    WORD  nChannels;
                    DWORD nSamplesPerSec;
                    DWORD nAvgBytesPerSec;
                    WORD  nBlockAlign;
                    WORD  wBitsPerSample;
                    WORD  cbSize;
                } WAVEFORMATEX;

                typedef struct wavehdr_tag {
                    LPSTR lpData;
                    DWORD dwBufferLength;
                    DWORD dwBytesRecorded;
                    DWORD_PTR dwUser;
                    DWORD dwFlags;
                    DWORD dwLoops;
                    struct wavehdr_tag* lpNext;
                    DWORD_PTR reserved;
                } WAVEHDR;

                unsigned int waveOutOpen(HWAVEOUT* phwo, unsigned int uDeviceID, const WAVEFORMATEX* pwfx, DWORD_PTR dwCallback, DWORD_PTR dwCallbackInstance, DWORD fdwOpen);
                unsigned int waveOutPrepareHeader(HWAVEOUT hwo, WAVEHDR* pwh, unsigned int cbwh);
                unsigned int waveOutWrite(HWAVEOUT hwo, WAVEHDR* pwh, unsigned int cbwh);
                unsigned int waveOutUnprepareHeader(HWAVEOUT hwo, WAVEHDR* pwh, unsigned int cbwh);
                unsigned int waveOutReset(HWAVEOUT hwo);
                unsigned int waveOutClose(HWAVEOUT hwo);
            ]]
			)
			if okCdef then
				local okLoad, lib = pcall(ffi.load, "winmm")
				if okLoad and lib then
					Audio._winmm = lib
				else
					Audio._winmmError = lib or "winmm_load_failed"
				end
			else
				Audio._winmmError = "winmm_cdef_failed"
			end
		end
		local winmm = Audio._winmm
		if not winmm then
			return nil,
				localizedText("Windows 音频接口初始化失败。", "Windows audio backend initialization failed.")
					.. " "
					.. tostring(Audio._winmmError or "winmm_unavailable")
		end

		local waveOutHandle = ffi.new("HWAVEOUT[1]")
		local waveFormat = ffi.new("WAVEFORMATEX[1]")
		waveFormat[0].wFormatTag = 1
		waveFormat[0].nChannels = formatInfo.channels or Audio.Const.CHANNELS
		waveFormat[0].nSamplesPerSec = formatInfo.sampleRate or Audio.Const.SAMPLE_RATE
		waveFormat[0].wBitsPerSample = formatInfo.bitsPerSample or Audio.Const.BITS_PER_SAMPLE
		waveFormat[0].nBlockAlign = formatInfo.blockAlign or Audio.Const.FRAME_BYTES
		waveFormat[0].nAvgBytesPerSec = formatInfo.byteRate
			or (waveFormat[0].nSamplesPerSec * waveFormat[0].nBlockAlign)
		waveFormat[0].cbSize = 0

		local openResult = tonumber(winmm.waveOutOpen(waveOutHandle, 0xFFFFFFFF, waveFormat, 0, 0, 0)) or -1
		if openResult ~= 0 then
			return nil,
				localizedText("Windows 默认扬声器打开失败。", "Unable to open the default Windows speaker.")
					.. " waveOutOpen="
					.. tostring(openResult)
		end

		local sink = {
			backend = "windows_waveout",
			handle = waveOutHandle[0],
			queuedBytes = 0,
			started = false,
			closed = false,
			drainRequested = false,
			buffers = {},
		}

		local function closeWindowsSink(self, immediate)
			if self.closed then
				return true
			end
			if self.handle ~= nil then
				if immediate then
					pcall(function()
						winmm.waveOutReset(self.handle)
					end)
				end
				for _, info in ipairs(self.buffers) do
					if info.prepared then
						pcall(function()
							winmm.waveOutUnprepareHeader(self.handle, info.header, ffi.sizeof("WAVEHDR"))
						end)
						info.prepared = false
					end
					info.inUse = false
					info.lastBytes = 0
				end
				pcall(function()
					winmm.waveOutClose(self.handle)
				end)
			end
			self.handle = nil
			self.closed = true
			self.queuedBytes = 0
			return true
		end

		function sink:_refresh()
			if self.closed then
				return
			end
			for _, info in ipairs(self.buffers) do
				if info.inUse then
					local flags = tonumber(info.header[0].dwFlags) or 0
					if (flags % 2) == 1 then
						self.queuedBytes = math.max(0, self.queuedBytes - (info.lastBytes or 0))
						info.lastBytes = 0
						info.inUse = false
					end
				end
			end
			if self.drainRequested and self.queuedBytes <= 0 then
				closeWindowsSink(self, false)
			end
		end

		function sink:start()
			if self.closed then
				return false, "sink_closed"
			end
			self.started = true
			return true
		end

		function sink:write(pcmBytes)
			if self.closed then
				return false, "sink_closed"
			end
			if type(pcmBytes) ~= "string" or pcmBytes == "" then
				return true
			end
			self:_refresh()
			local slot = nil
			for _, info in ipairs(self.buffers) do
				if not info.inUse then
					slot = info
					break
				end
			end
			if not slot then
				return false, "buffer_full"
			end
			if slot.prepared then
				local unprepareResult = tonumber(
					winmm.waveOutUnprepareHeader(self.handle, slot.header, ffi.sizeof("WAVEHDR"))
				) or 0
				if unprepareResult ~= 0 then
					return false, "waveOutUnprepareHeader:" .. tostring(unprepareResult)
				end
				slot.prepared = false
			end
			local byteCount = math.min(#pcmBytes, Audio.Const.CHUNK_BYTES)
			ffi.copy(slot.data, pcmBytes, byteCount)
			slot.header[0].lpData = ffi.cast("char*", slot.data)
			slot.header[0].dwBufferLength = byteCount
			slot.header[0].dwBytesRecorded = 0
			slot.header[0].dwUser = 0
			slot.header[0].dwFlags = 0
			slot.header[0].dwLoops = 0
			slot.header[0].lpNext = nil
			slot.header[0].reserved = 0
			local prepareResult = tonumber(winmm.waveOutPrepareHeader(self.handle, slot.header, ffi.sizeof("WAVEHDR")))
				or -1
			if prepareResult ~= 0 then
				return false, "waveOutPrepareHeader:" .. tostring(prepareResult)
			end
			slot.prepared = true
			local writeResult = tonumber(winmm.waveOutWrite(self.handle, slot.header, ffi.sizeof("WAVEHDR"))) or -1
			if writeResult ~= 0 then
				return false, "waveOutWrite:" .. tostring(writeResult)
			end
			slot.inUse = true
			slot.lastBytes = byteCount
			self.queuedBytes = self.queuedBytes + byteCount
			self.started = true
			return true
		end

		function sink:getQueuedBytes()
			self:_refresh()
			return self.queuedBytes
		end

		function sink:drainAndStop()
			self.drainRequested = true
			self:_refresh()
		end

		function sink:abort()
			return closeWindowsSink(self, true)
		end

		for _ = 1, 4 do
			sink.buffers[#sink.buffers + 1] = {
				data = ffi.new("uint8_t[?]", Audio.Const.CHUNK_BYTES),
				header = ffi.new("WAVEHDR[1]"),
				prepared = false,
				inUse = false,
				lastBytes = 0,
			}
		end

		return sink
	end

	local function createMacSink(formatInfo)
		local ffi = Audio.ffi
		if not ffi then
			return nil,
				localizedText(
					"当前环境缺少 ffi，无法直接播放试听。",
					"ffi is unavailable, so direct preview playback cannot start."
				)
		end
		if not Audio._audioQueueInitAttempted then
			Audio._audioQueueInitAttempted = true
			local okCdef = pcall(
				ffi.cdef,
				[[
                typedef double Float64;
                typedef uint32_t UInt32;
                typedef int32_t OSStatus;
                typedef uint32_t AudioFormatID;
                typedef uint32_t AudioFormatFlags;
                typedef int Boolean;
                typedef const void* CFRunLoopRef;
                typedef const void* CFStringRef;

                typedef struct AudioStreamBasicDescription {
                    Float64 mSampleRate;
                    AudioFormatID mFormatID;
                    AudioFormatFlags mFormatFlags;
                    UInt32 mBytesPerPacket;
                    UInt32 mFramesPerPacket;
                    UInt32 mBytesPerFrame;
                    UInt32 mChannelsPerFrame;
                    UInt32 mBitsPerChannel;
                    UInt32 mReserved;
                } AudioStreamBasicDescription;

                typedef struct OpaqueAudioQueue* AudioQueueRef;
                typedef struct AudioQueueBuffer {
                    UInt32 mAudioDataBytesCapacity;
                    void* mAudioData;
                    UInt32 mAudioDataByteSize;
                    void* mUserData;
                    UInt32 mPacketDescriptionCapacity;
                    void* mPacketDescriptions;
                    UInt32 mPacketDescriptionCount;
                } AudioQueueBuffer;
                typedef AudioQueueBuffer* AudioQueueBufferRef;

                typedef void (*AudioQueueOutputCallback)(void* inUserData, AudioQueueRef inAQ, AudioQueueBufferRef inBuffer);

                OSStatus AudioQueueNewOutput(const AudioStreamBasicDescription* inFormat, AudioQueueOutputCallback inCallbackProc, void* inUserData, CFRunLoopRef inCallbackRunLoop, CFStringRef inCallbackRunLoopMode, UInt32 inFlags, AudioQueueRef* outAQ);
                OSStatus AudioQueueAllocateBuffer(AudioQueueRef inAQ, UInt32 inBufferByteSize, AudioQueueBufferRef* outBuffer);
                OSStatus AudioQueueEnqueueBuffer(AudioQueueRef inAQ, AudioQueueBufferRef inBuffer, UInt32 inNumPacketDescs, const void* inPacketDescs);
                OSStatus AudioQueueStart(AudioQueueRef inAQ, const void* inStartTime);
                OSStatus AudioQueueStop(AudioQueueRef inAQ, Boolean inImmediate);
                OSStatus AudioQueueDispose(AudioQueueRef inAQ, Boolean inImmediate);
            ]]
			)
			if okCdef then
				local lib, loadResult = loadMacFrameworkLibrary(ffi, {
					-- Resolve 在 macOS 下是 hardened app，必须优先走 framework 绝对路径。
					"/System/Library/Frameworks/AudioToolbox.framework/AudioToolbox",
					"/System/Library/Frameworks/AudioToolbox.framework/Versions/Current/AudioToolbox",
					"/System/Library/Frameworks/AudioToolbox.framework/Versions/A/AudioToolbox",
					"AudioToolbox",
				})
				if lib then
					Audio._audioQueue = lib
					Audio._audioQueuePath = loadResult
				else
					Audio._audioQueueError = loadResult or "audiotoolbox_load_failed"
				end
			else
				Audio._audioQueueError = "audiotoolbox_cdef_failed"
			end
		end
		local audioQueue = Audio._audioQueue
		if not audioQueue then
			return nil,
				localizedText("macOS 音频接口初始化失败。", "macOS audio backend initialization failed.")
					.. " "
					.. tostring(Audio._audioQueueError or "audiotoolbox_unavailable")
		end

		Audio._macSinkRegistry = Audio._macSinkRegistry or {}
		Audio._macSinkCounter = Audio._macSinkCounter or 0
		if not Audio._macOutputCallback then
			Audio._macOutputCallback = ffi.cast("AudioQueueOutputCallback", function(userData, _, inBuffer)
				local id = tonumber(ffi.cast("int*", userData)[0]) or 0
				local sink = Audio._macSinkRegistry[id]
				if not sink then
					return
				end
				local key = tonumber(ffi.cast("uintptr_t", inBuffer)) or 0
				local info = sink.bufferMap[key]
				if info and info.inUse then
					sink.queuedBytes = math.max(0, sink.queuedBytes - (info.lastBytes or 0))
					info.lastBytes = 0
					info.inUse = false
					if inBuffer ~= nil then
						inBuffer.mAudioDataByteSize = 0
					end
				end
				if sink.drainRequested and sink.queuedBytes <= 0 then
					sink:_close(false)
				end
			end)
		end

		local streamDesc = ffi.new("AudioStreamBasicDescription[1]")
		streamDesc[0].mSampleRate = formatInfo.sampleRate or Audio.Const.SAMPLE_RATE
		streamDesc[0].mFormatID = 1819304813
		streamDesc[0].mFormatFlags = 12
		streamDesc[0].mBytesPerPacket = formatInfo.blockAlign or Audio.Const.FRAME_BYTES
		streamDesc[0].mFramesPerPacket = 1
		streamDesc[0].mBytesPerFrame = formatInfo.blockAlign or Audio.Const.FRAME_BYTES
		streamDesc[0].mChannelsPerFrame = formatInfo.channels or Audio.Const.CHANNELS
		streamDesc[0].mBitsPerChannel = formatInfo.bitsPerSample or Audio.Const.BITS_PER_SAMPLE
		streamDesc[0].mReserved = 0

		local queueRef = ffi.new("AudioQueueRef[1]")
		Audio._macSinkCounter = Audio._macSinkCounter + 1
		local sinkId = Audio._macSinkCounter
		local userData = ffi.new("int[1]", sinkId)
		local createStatus = tonumber(
			audioQueue.AudioQueueNewOutput(streamDesc, Audio._macOutputCallback, userData, nil, nil, 0, queueRef)
		) or -1
		if createStatus ~= 0 then
			return nil,
				localizedText("macOS 默认扬声器打开失败。", "Unable to open the default macOS speaker.")
					.. " AudioQueueNewOutput="
					.. tostring(createStatus)
		end

		local sink = {
			backend = "mac_audioqueue",
			queue = queueRef[0],
			queuedBytes = 0,
			started = false,
			closed = false,
			drainRequested = false,
			id = sinkId,
			userData = userData,
			buffers = {},
			bufferMap = {},
		}

		function sink:_close(immediate)
			if self.closed then
				return true
			end
			if self.queue ~= nil then
				pcall(function()
					audioQueue.AudioQueueStop(self.queue, immediate and 1 or 0)
				end)
				pcall(function()
					audioQueue.AudioQueueDispose(self.queue, immediate and 1 or 0)
				end)
			end
			Audio._macSinkRegistry[self.id] = nil
			self.queue = nil
			self.closed = true
			self.queuedBytes = 0
			return true
		end

		function sink:start()
			if self.closed then
				return false, "sink_closed"
			end
			if self.started then
				return true
			end
			local status = tonumber(audioQueue.AudioQueueStart(self.queue, nil)) or -1
			if status ~= 0 then
				return false, "AudioQueueStart:" .. tostring(status)
			end
			self.started = true
			return true
		end

		function sink:write(pcmBytes)
			if self.closed then
				return false, "sink_closed"
			end
			if type(pcmBytes) ~= "string" or pcmBytes == "" then
				return true
			end
			local slot = nil
			for _, info in ipairs(self.buffers) do
				if not info.inUse then
					slot = info
					break
				end
			end
			if not slot then
				return false, "buffer_full"
			end
			local byteCount = math.min(#pcmBytes, Audio.Const.CHUNK_BYTES)
			ffi.copy(slot.buffer[0].mAudioData, pcmBytes, byteCount)
			slot.buffer[0].mAudioDataByteSize = byteCount
			local enqueueStatus = tonumber(audioQueue.AudioQueueEnqueueBuffer(self.queue, slot.buffer, 0, nil)) or -1
			if enqueueStatus ~= 0 then
				return false, "AudioQueueEnqueueBuffer:" .. tostring(enqueueStatus)
			end
			slot.inUse = true
			slot.lastBytes = byteCount
			self.queuedBytes = self.queuedBytes + byteCount
			if not self.started then
				local ok, err = self:start()
				if not ok then
					return false, err
				end
			end
			return true
		end

		function sink:getQueuedBytes()
			if self.drainRequested and self.queuedBytes <= 0 then
				self:_close(false)
			end
			return self.queuedBytes
		end

		function sink:drainAndStop()
			self.drainRequested = true
			if self.queuedBytes <= 0 then
				self:_close(false)
			end
		end

		function sink:abort()
			return self:_close(true)
		end

		for _ = 1, 4 do
			local bufferRef = ffi.new("AudioQueueBufferRef[1]")
			local status = tonumber(audioQueue.AudioQueueAllocateBuffer(sink.queue, Audio.Const.CHUNK_BYTES, bufferRef))
				or -1
			if status ~= 0 then
				sink:_close(true)
				return nil, "AudioQueueAllocateBuffer:" .. tostring(status)
			end
			local buffer = bufferRef[0]
			local entry = {
				buffer = buffer,
				inUse = false,
				lastBytes = 0,
			}
			sink.buffers[#sink.buffers + 1] = entry
			sink.bufferMap[tonumber(ffi.cast("uintptr_t", buffer)) or #sink.buffers] = entry
		end

		Audio._macSinkRegistry[sink.id] = sink
		return sink
	end

	function Audio.Sink.create(formatInfo)
		formatInfo = formatInfo or {}
		if
			(formatInfo.channels or Audio.Const.CHANNELS) ~= Audio.Const.CHANNELS
			or (formatInfo.sampleRate or Audio.Const.SAMPLE_RATE) ~= Audio.Const.SAMPLE_RATE
			or (formatInfo.bitsPerSample or Audio.Const.BITS_PER_SAMPLE) ~= Audio.Const.BITS_PER_SAMPLE
		then
			return nil,
				localizedText(
					"当前试听播放链路只支持 48kHz / 16-bit / 单声道 PCM。",
					"This preview playback path only supports 48kHz / 16-bit / mono PCM."
				)
		end
		if IS_WINDOWS then
			return createWindowsSink(formatInfo)
		end
		if IS_MACOS then
			return createMacSink(formatInfo)
		end
		return nil,
			localizedText(
				"当前平台暂不支持 Azure 直接流式试听。",
				"Azure direct streaming preview is not supported on this platform."
			)
	end
end

---
--- 6b. 提供者模块 (App.Providers)
---
do
	local Utils = App.Utils
	local Providers = App.Providers or {
		Azure = {},
		MiniMax = {},
		OpenAI = {},
	}
	Providers.Azure = Providers.Azure or {}
	Providers.MiniMax = Providers.MiniMax or {}
	Providers.OpenAI = Providers.OpenAI or {}

	local function fetch_provider_secret(provider)
		local cleanProvider = trim(provider or "")
		if cleanProvider == "" then
			return nil, "missing_provider"
		end
		local cached = App.State.providerSecrets[cleanProvider]
		if cached ~= nil then
			return cached
		end
		local encoder = (Utils and Utils.urlEncode)
			or function(text)
				return tostring(text or ""):gsub("[^%w%-%._~]", function(ch)
					return string.format("%%%02X", string.byte(ch))
				end)
			end
		local url = string.format(
			"%s/functions/v1/getApiKey?provider=%s",
			App.Config.Const.SUPABASE_URL,
			encoder(cleanProvider)
		)
		local headers = {
			Authorization = "Bearer " .. App.Config.Const.SUPABASE_ANON_KEY,
			apikey = App.Config.Const.SUPABASE_ANON_KEY,
			["Content-Type"] = "application/json",
			["User-Agent"] = string.format("%s/%s", App.Config.Const.SCRIPT_NAME, App.Config.Const.SCRIPT_VERSION),
		}
		local body, status = App.Services.httpGet(url, headers, App.Config.Const.SUPABASE_TIMEOUT)
		if not body then
			return nil, status or "request_failed"
		end
		local ok, decoded = pcall(json.decode, body)
		if not ok or type(decoded) ~= "table" then
			return nil, "decode_failed"
		end
		local apiKey = decoded.api_key or decoded.apiKey or decoded.key or decoded.secret
		apiKey = type(apiKey) == "string" and trim(apiKey) or ""
		if apiKey == "" then
			return nil, "missing_key"
		end
		App.State.providerSecrets[cleanProvider] = apiKey
		return apiKey
	end

	Providers.fetchProviderSecret = fetch_provider_secret

	local function resolveAzureCredentials(params)
		local apiKey = trim(params.apiKey or "")
		local region = trim(params.region or "")
		if not params.useApi then
			local secret, fetchErr = fetch_provider_secret(App.Config.Const.AZURE_SPEECH_PROVIDER)
			if not secret then
				local prefix = App.State.locale == "cn" and "自动获取 Azure Key 失败："
					or "Failed to fetch Azure key: "
				return nil, prefix .. tostring(fetchErr or "unknown")
			end
			apiKey = secret
			region = "eastus"
		end
		return {
			apiKey = apiKey,
			region = region,
		}
	end

	Providers.Azure.resolveCredentials = resolveAzureCredentials

	local function quoteShellArg(str)
		str = tostring(str or "")
		if PATH_SEP == "\\" then
			return '"' .. str:gsub('"', '\\"') .. '"'
		end
		return "'" .. str:gsub("'", [['"'"']]) .. "'"
	end

	local function removeTaskPaths(paths)
		if type(paths) ~= "table" then
			return
		end
		for _, path in ipairs(paths) do
			if type(path) == "string" and path ~= "" then
				Utils.removeFile(path)
			end
		end
	end

	local function readTrimmedFileSafe(path)
		return trim(Utils.readFile(path) or "")
	end

	local function closeTaskProcess(handle, terminateProcess)
		if not handle then
			return
		end
		if terminateProcess and handle.terminate then
			pcall(function()
				handle:terminate(15)
			end)
		end
		if handle.close then
			pcall(function()
				handle:close()
			end)
		end
	end

	local function makeAsyncTaskBase(providerId, params, timeoutSeconds)
		local task = {
			providerId = providerId,
			params = params,
			timeoutSeconds = timeoutSeconds or 120,
			processHandle = nil,
			cleanupPaths = {},
		}

		function task:addCleanupPath(path)
			if type(path) == "string" and path ~= "" then
				self.cleanupPaths[#self.cleanupPaths + 1] = path
			end
		end

		function task:cleanup(options)
			options = options or {}
			closeTaskProcess(self.processHandle, options.terminateProcess == true)
			self.processHandle = nil
			removeTaskPaths(self.cleanupPaths)
			self.cleanupPaths = {}
		end

		return task
	end

	local function launchAsyncCommand(command)
		if type(runShellCommandAsync) ~= "function" then
			return nil,
				localizedText(
					"当前环境不支持异步命令执行。",
					"Async shell execution is unavailable in this environment."
				)
		end
		return runShellCommandAsync(command)
	end

	local function buildStandardCurlFlags(tlsCompatFlag)
		local userAgent = string.format("%s/%s", App.Config.Const.SCRIPT_NAME, trim(App.Config.Const.SCRIPT_VERSION))
		return string.format(
			'--http1.1 -sS -L -g --connect-timeout 30 --keepalive-time 1 --compressed -4 --no-sessionid --tcp-nodelay -A "%s"%s',
			userAgent,
			(App.Services.CurlCompat and App.Services.CurlCompat.buildTlsOption(tlsCompatFlag) or "")
		)
	end

	local function buildStreamCurlFlags(tlsCompatFlag)
		local userAgent = string.format("%s/%s", App.Config.Const.SCRIPT_NAME, trim(App.Config.Const.SCRIPT_VERSION))
		return string.format(
			'--http1.1 -sS -N --no-buffer -L -g --connect-timeout 30 --keepalive-time 1 --tcp-nodelay -A "%s"%s',
			userAgent,
			(App.Services.CurlCompat and App.Services.CurlCompat.buildTlsOption(tlsCompatFlag) or "")
		)
	end

	local function tryStartWindowsCurlCompatRetry(currentFlag, errorText, context, restartFn)
		local compat = App.Services and App.Services.CurlCompat
		if not (compat and compat.getNextTlsFlag) then
			return false
		end
		local nextFlag, retryReason = compat.getNextTlsFlag(currentFlag, errorText)
		if not nextFlag then
			return false
		end
		if compat.logRetry then
			compat.logRetry(context, nextFlag, retryReason, errorText)
		end
		local okRestart, restartErr = restartFn(nextFlag)
		if not okRestart then
			return nil, restartErr
		end
		return true
	end

	local function parseHttpCode(infoText)
		infoText = tostring(infoText or "")
		return tonumber(infoText:match("__CURL_HTTP_CODE__:(%d%d%d)")) or tonumber(infoText:match("(%d%d%d)"))
	end

	local function parseMiniMaxResponseBody(body)
		local resp, decodePos, decodeErr = json.decode(body or "")
		if not resp then
			logInfo(
				string.format("MiniMax JSON decode failed (pos=%s, err=%s)", tostring(decodePos), tostring(decodeErr))
			)
			local statusCode = tostring(body or ""):match('"status_code"%s*:%s*(%d+)')
			local statusMsg = tostring(body or ""):match('"status_msg"%s*:%s*"([^"]*)"')
			if statusCode and tonumber(statusCode) ~= 0 then
				return nil,
					localizedFormat(
						"MiniMax API 错误 (%s)：%s",
						"MiniMax API error (%s): %s",
						tostring(statusCode),
						tostring(statusMsg or localizedText("未知错误", "Unknown error"))
					)
			end
			local audioHexFallback = tostring(body or ""):match('"audio"%s*:%s*"([0-9A-Fa-f]+)"')
			if audioHexFallback then
				resp = {
					data = {
						audio = audioHexFallback,
						subtitle_file = tostring(body or ""):match('"subtitle_file"%s*:%s*"([^"]*)"'),
					},
				}
			else
				local errDetail = decodeErr or "unknown"
				if decodePos then
					errDetail = string.format("%s (pos=%s)", tostring(errDetail), tostring(decodePos))
				end
				return nil,
					localizedFormat("MiniMax 响应解析失败：%s", "MiniMax response parse failed: %s", errDetail)
			end
		end

		local baseResp = resp.base_resp or resp.baseResp or {}
		local statusCode = tonumber(baseResp.status_code or baseResp.statusCode)
		if statusCode and statusCode ~= 0 then
			local statusMsg = baseResp.status_msg
				or baseResp.statusMsg
				or localizedText("未知错误", "Unknown error")
			return nil,
				localizedFormat(
					"MiniMax API 错误 (%s)：%s",
					"MiniMax API error (%s): %s",
					tostring(statusCode),
					tostring(statusMsg)
				)
		end

		local data = resp.data or {}
		local audioHex = data.audio or data.audio_data
		if not audioHex or audioHex == "" then
			return nil, localizedText("MiniMax 返回空音频数据", "MiniMax returned empty audio data")
		end

		return {
			data = data,
			audioHex = audioHex,
		}
	end

	local function createEventStreamProcessor(onEvent)
		local doneMarkers = {
			["[done]"] = true,
			["[end]"] = true,
			["[complete]"] = true,
			["done"] = true,
			["end"] = true,
			["complete"] = true,
		}
		local lineBuffer = ""
		local sseDataLines = {}

		local function invokeOnEvent(eventObj)
			if type(onEvent) ~= "function" then
				return true
			end
			local ok, result, err = pcall(onEvent, eventObj)
			if not ok then
				return false, tostring(result)
			end
			if result == false then
				return false, tostring(err or "event_callback_failed")
			end
			return true
		end

		local function dispatchEventPayload(rawPayload)
			rawPayload = trim(rawPayload or "")
			rawPayload = rawPayload:gsub("^\239\187\191", "")
			if rawPayload == "" then
				return true
			end
			local lowerPayload = rawPayload:lower()
			local compactPayload = lowerPayload:gsub("%s+", "")
			if doneMarkers[lowerPayload] or doneMarkers[compactPayload] then
				return invokeOnEvent({ _done = true })
			end
			if rawPayload:match("^data:%s*") then
				rawPayload = trim(rawPayload:gsub("^data:%s*", "", 1))
				lowerPayload = rawPayload:lower()
				compactPayload = lowerPayload:gsub("%s+", "")
				if doneMarkers[lowerPayload] or doneMarkers[compactPayload] then
					return invokeOnEvent({ _done = true })
				end
			end
			local firstChar = rawPayload:sub(1, 1)
			if firstChar ~= "{" and firstChar ~= "[" then
				local objStart = rawPayload:find("{", 1, true)
				local arrStart = rawPayload:find("[", 1, true)
				local startPos = nil
				if objStart and arrStart then
					startPos = math.min(objStart, arrStart)
				else
					startPos = objStart or arrStart
				end
				if not startPos then
					return true
				end
				rawPayload = trim(rawPayload:sub(startPos))
			end
			if rawPayload:sub(1, 1) == "[" then
				local compactControl = rawPayload:gsub("%s+", "")
				local lowerControl = compactControl:lower()
				if doneMarkers[lowerControl] then
					return invokeOnEvent({ _done = true })
				end
				if compactControl:match("^%[[A-Za-z_%-]+%]$") then
					return true
				end
			end
			local decoded, decodePos, decodeErr = json.decode(rawPayload)
			if type(decoded) ~= "table" then
				local reason = tostring(decodeErr or decodePos or "unknown")
				local payloadPreview = rawPayload:gsub("%s+", " ")
				if #payloadPreview > 120 then
					payloadPreview = payloadPreview:sub(1, 120) .. "..."
				end
				return false, "stream_json_decode_failed:" .. reason .. "|payload=" .. payloadPreview
			end
			return invokeOnEvent(decoded)
		end

		local function flushSseEvent()
			if #sseDataLines == 0 then
				return true
			end
			local payloadText = table.concat(sseDataLines, "\n")
			sseDataLines = {}
			return dispatchEventPayload(payloadText)
		end

		local function processParsedLine(line)
			line = (line or ""):gsub("\r$", "")
			local normalizedLine = trim(line)
			if normalizedLine:match("^data:%s*") then
				sseDataLines[#sseDataLines + 1] = normalizedLine:gsub("^data:%s*", "")
				return true
			end
			if normalizedLine == "" then
				return flushSseEvent()
			end
			if
				normalizedLine:match("^event:%s*")
				or normalizedLine:match("^id:%s*")
				or normalizedLine:match("^retry:%s*")
				or normalizedLine:match("^:%s*")
			then
				return true
			end
			local okFlush, flushErr = flushSseEvent()
			if not okFlush then
				return false, flushErr
			end
			return dispatchEventPayload(normalizedLine)
		end

		return {
			processChunkText = function(chunk, finalize)
				if chunk and chunk ~= "" then
					lineBuffer = lineBuffer .. chunk
				end
				while true do
					local pos = lineBuffer:find("\n", 1, true)
					if not pos then
						break
					end
					local line = lineBuffer:sub(1, pos - 1)
					lineBuffer = lineBuffer:sub(pos + 1)
					local ok, err = processParsedLine(line)
					if not ok then
						return false, err
					end
				end
				if finalize and lineBuffer ~= "" then
					local ok, err = processParsedLine(lineBuffer)
					if not ok then
						return false, err
					end
					lineBuffer = ""
				end
				if finalize then
					local okFlush, flushErr = flushSseEvent()
					if not okFlush then
						return false, flushErr
					end
				end
				return true
			end,
		}
	end

	local function normalizeOpenAIBaseUrl(url)
		url = trim(url or "")
		if url == "" then
			return "https://api.openai.com"
		end
		url = url:gsub("%s+$", "")
		url = url:gsub("/+$", "")
		if url == "" then
			return "https://api.openai.com"
		end
		return url
	end

	local function selectOpenAIEntry(list, combo, fallbackIndex, fallbackId)
		list = list or {}
		local index = 0
		if combo and combo.CurrentIndex ~= nil then
			index = clampIndex(combo.CurrentIndex, #list)
		elseif fallbackIndex ~= nil then
			index = clampIndex(fallbackIndex, #list)
		end
		local entry = list[index + 1]
		if entry then
			return entry, entry.id, index
		end
		return nil, fallbackId, index
	end

	local function buildOpenAIRequestContext(params)
		local items = App.UI.items or {}
		local cfg = App.Config.OpenAI or {}
		local text = trim(params.text or "")
		local apiKey = trim(params.apiKey or "")
		local baseUrl = normalizeOpenAIBaseUrl(params.baseUrl or "")
		local versionedBase = baseUrl
		if not versionedBase:match("/v%d+$") then
			versionedBase = versionedBase .. "/v1"
		end
		local url = versionedBase .. "/audio/speech"

		local models = cfg.models or {}
		local _, modelId = selectOpenAIEntry(
			models,
			items.OpenAIModelCombo,
			App.State.openai and App.State.openai.modelIndex,
			App.State.openai and App.State.openai.model or "gpt-4o-mini-tts"
		)
		modelId = modelId or (models[1] and models[1].id) or "gpt-4o-mini-tts"

		local voices = cfg.voices or {}
		local _, voiceId = selectOpenAIEntry(
			voices,
			items.OpenAIVoiceCombo,
			App.State.openai and App.State.openai.voiceIndex,
			App.State.openai and App.State.openai.voice or "alloy"
		)
		voiceId = voiceId or (voices[1] and voices[1].id) or "alloy"

		local formatId = (App.Settings.getSharedFormatId() or "mp3"):lower()
		local speed = tonumber(params.rate) or (App.State.openai and App.State.openai.rate) or 1.0
		if speed < 0.25 then
			speed = 0.25
		end
		if speed > 4.0 then
			speed = 4.0
		end

		local instructions = trim(params.instruction or "")
		if instructions ~= "" and (modelId == "tts-1" or modelId == "tts-1-hd") then
			instructions = ""
		end

		local payload = {
			model = modelId,
			input = text,
			voice = voiceId,
			response_format = formatId,
			speed = speed,
			stream = false,
		}
		if instructions ~= "" then
			payload.instructions = instructions
		end

		return {
			url = url,
			payload = payload,
			payloadStr = json.encode(payload),
			headers = {
				Authorization = "Bearer " .. apiKey,
				["Content-Type"] = "application/json",
			},
			text = text,
			formatId = formatId,
			outputDir = trim(params.outputDir or ""),
		}
	end

	local function decodeOpenAIJson(bodyStr)
		local ok, decoded = pcall(json.decode, bodyStr)
		if ok and type(decoded) == "table" then
			return decoded
		end
		return nil
	end

	function Providers.Azure.speak(params)
		local debugParams = {}
		for k, v in pairs(params or {}) do
			if k ~= "apiKey" then
				debugParams[k] = v
			end
		end
		logInfo(string.format("Azure.speak called with params: %s", json.encode(debugParams)))
		local credentials, credentialErr = resolveAzureCredentials(params)
		if not credentials then
			return false, credentialErr
		end
		local apiKey = credentials.apiKey
		local region = credentials.region
		local ssml = App.Azure.buildSsml(params)
		local ssmlPath, tmpErr = App.Utils.makeTempPath("ssml")
		if not ssmlPath then
			return false,
				localizedText("创建临时 SSML 文件失败：", "Failed to create temporary SSML file: ")
					.. tostring(tmpErr)
		end
		local wrote, writeErr = App.Utils.writeFile(ssmlPath, ssml)
		if not wrote then
			return false,
				localizedText("写入 SSML 文件失败：", "Failed to write SSML file: ") .. tostring(writeErr)
		end

		local responseInfoPath, infoErr = App.Utils.makeTempPath("curlinfo")
		if not responseInfoPath then
			App.Utils.removeFile(ssmlPath)
			return false,
				localizedText("创建临时信息文件失败：", "Failed to create temporary response info file: ")
					.. tostring(infoErr)
		end
		local errPath, errErr = App.Utils.makeTempPath("curlerr")
		if not errPath then
			App.Utils.removeFile(ssmlPath)
			App.Utils.removeFile(responseInfoPath)
			return false,
				localizedText("创建临时错误文件失败：", "Failed to create temporary error file: ")
					.. tostring(errErr)
		end

		local outputPath
		if params.outputPath and params.outputPath ~= "" then
			outputPath = params.outputPath
		else
			local generatedPath, pathErr = App.Azure.buildOutputPath(params)
			if not generatedPath then
				return false,
					localizedText("无法准备保存输出文件：", "Unable to prepare output file: ") .. tostring(
						pathErr or "unknown"
					)
			end
			outputPath = generatedPath
		end
		App.Utils.ensureDir(outputPath:match("^(.*)[/\\]") or "")

		local function escapeQuotes(str)
			return (str or ""):gsub('"', '\\"')
		end

		local ok = true
		local responseInfo = ""
		local errBody = ""
		if IS_WINDOWS and App.Services and App.Services.CurlCompat then
			local runResult = App.Services.CurlCompat.runWindowsSync(function(tlsCompatFlag)
				return string.format(
					'curl %s -f -w "%%{http_code}" -X POST "https://%s.tts.speech.microsoft.com/cognitiveservices/v1" -H "Content-Type: application/ssml+xml" -H "X-Microsoft-OutputFormat: %s" -H "Ocp-Apim-Subscription-Key: %s" -H "User-Agent: heiba-azure-tts-curl/1.0" --data-binary @"%s" --output "%s" > "%s" 2> "%s"',
					buildStandardCurlFlags(tlsCompatFlag),
					region,
					params.outputFormat or "riff-24khz-16bit-mono-pcm",
					escapeQuotes(apiKey),
					escapeQuotes(ssmlPath),
					escapeQuotes(outputPath),
					escapeQuotes(responseInfoPath),
					escapeQuotes(errPath)
				)
			end, {
				context = "azure_sync_speak",
				resetPaths = { outputPath, responseInfoPath, errPath },
				infoPath = responseInfoPath,
				errPath = errPath,
			})
			ok = runResult.ok
			responseInfo = runResult.info or ""
			errBody = runResult.stderr or ""
		else
			local command = string.format(
				'curl -sS -f -w "%%{http_code}" -X POST "https://%s.tts.speech.microsoft.com/cognitiveservices/v1" -H "Content-Type: application/ssml+xml" -H "X-Microsoft-OutputFormat: %s" -H "Ocp-Apim-Subscription-Key: %s" -H "User-Agent: heiba-azure-tts-curl/1.0" --data-binary @"%s" --output "%s" > "%s" 2> "%s"',
				region,
				params.outputFormat or "riff-24khz-16bit-mono-pcm",
				escapeQuotes(apiKey),
				escapeQuotes(ssmlPath),
				escapeQuotes(outputPath),
				escapeQuotes(responseInfoPath),
				escapeQuotes(errPath)
			)
			ok = runShellCommand(command)
			responseInfo = App.Utils.readFile(responseInfoPath) or ""
			errBody = App.Utils.readFile(errPath) or ""
		end
		App.Utils.removeFile(ssmlPath)
		if responseInfo and responseInfo ~= "" then
			responseInfo = responseInfo:gsub("%s+$", "")
			logInfo(string.format("Azure response info: %s", truncateForLog(responseInfo, 800)))
		else
			responseInfo = ""
			logInfo("Azure response info: <empty>")
		end
		App.Utils.removeFile(responseInfoPath)
		App.Utils.removeFile(errPath)
		if not ok then
			local errMessage = (errBody ~= "" and errBody)
				or (responseInfo ~= "" and responseInfo)
				or localizedText("curl 调用失败", "curl invocation failed")
			return false, localizedFormat("调用 Azure API 失败：%s", "Azure API request failed: %s", errMessage)
		end

		local size = App.Utils.getFileSize(outputPath)
		if not size or size == 0 then
			return false, localizedText("Azure API 返回空音频文件。", "Azure API returned an empty audio file.")
		end

		local sampleRate = App.Azure.deriveSampleRate(params.outputFormat)
		return true,
			{
				path = outputPath,
				durationSamples = params.durationSamples or 0,
				sampleRate = sampleRate,
				debugInfo = responseInfo and responseInfo:gsub("%s+$", "") or "",
			}
	end

	local function minimaxHexToBinary(hex)
		if type(hex) ~= "string" then
			return nil, "invalid_hex_string"
		end
		hex = hex:gsub("%s+", "")
		if hex == "" then
			return nil, "empty_hex_string"
		end
		if #hex % 2 == 1 then
			hex = "0" .. hex
		end
		local buffer = {}
		for i = 1, #hex, 2 do
			local byte = tonumber(hex:sub(i, i + 1), 16)
			if not byte then
				return nil, "hex_decode_failed"
			end
			buffer[#buffer + 1] = string.char(byte)
		end
		return table.concat(buffer)
	end

	local function minimaxExtractStreamAudioHex(eventObj)
		if type(eventObj) ~= "table" then
			return nil
		end
		local data = eventObj.data
		if type(data) == "table" then
			if type(data.audio) == "string" and data.audio ~= "" then
				return data.audio
			end
			if type(data.audio_data) == "string" and data.audio_data ~= "" then
				return data.audio_data
			end
		end
		if type(eventObj.audio) == "string" and eventObj.audio ~= "" then
			return eventObj.audio
		end
		return nil
	end

	local function minimaxIsDoneEvent(eventObj)
		if type(eventObj) ~= "table" then
			return false
		end
		if eventObj._done then
			return true
		end
		local data = eventObj.data
		if type(data) == "table" then
			local statusValue = tonumber(data.status or data.stream_status)
			if statusValue == 2 then
				return true
			end
			if data.is_final == true or data.finish == true then
				return true
			end
			local finishReason = tostring(data.finish_reason or ""):lower()
			if finishReason == "stop" or finishReason == "done" then
				return true
			end
		end
		local statusValue = tonumber(eventObj.status or eventObj.stream_status)
		if statusValue == 2 then
			return true
		end
		if eventObj.is_final == true then
			return true
		end
		local eventType = tostring(eventObj.type or eventObj.event or ""):lower()
		if eventType == "done" or eventType == "finish" or eventType == "completed" then
			return true
		end
		return false
	end

	function Providers.MiniMax.speakStreamMp3(params, context)
		context = context or {}
		local outputDir = context.outputDir or ""
		local outputPath, nameErr = App.Utils.nextAvailableFile(outputDir, {
			baseName = params.text or "audio",
			extension = "mp3",
			maxBaseLength = 24,
			maxAttempts = 99,
		})
		if not outputPath then
			local reason = nameErr and (": " .. tostring(nameErr)) or ""
			return false,
				localizedText("MiniMax 无法生成输出文件名", "MiniMax failed to create output filename")
					.. reason
		end

		local partialPath = outputPath .. ".partial"
		local partialFile, openErr = App.Utils.openBinaryWriter(partialPath)
		if not partialFile then
			return false,
				localizedFormat(
					"MiniMax 流式写入文件失败：%s",
					"MiniMax failed to open stream output file: %s",
					tostring(openErr)
				)
		end

		local streamDone = false
		local chunkCount = 0
		local totalBytes = 0
		local subtitleUrl = nil
		local streamPlatform = (package.config:sub(1, 1) == "\\") and "windows" or "unix"
		logInfo(string.format("[MiniMax][stream][%s] begin", streamPlatform))

		local function closePartial()
			if partialFile then
				pcall(function()
					partialFile:close()
				end)
				partialFile = nil
			end
		end

		local function failAndCleanup(reason)
			closePartial()
			App.Utils.removeFile(partialPath)
			logInfo(string.format("[MiniMax][stream][%s] failed: %s", streamPlatform, tostring(reason)))
			logInfo(string.format("MiniMax stream failed: %s", tostring(reason)))
			return false, tostring(reason)
		end

		local function onStreamEvent(eventObj)
			if type(eventObj) ~= "table" then
				return false, "stream_event_not_table"
			end
			local baseResp = eventObj.base_resp or eventObj.baseResp or {}
			local statusCode = tonumber(baseResp.status_code or baseResp.statusCode)
			if statusCode and statusCode ~= 0 then
				local statusMsg = baseResp.status_msg
					or baseResp.statusMsg
					or localizedText("未知错误", "Unknown error")
				return false,
					localizedFormat(
						"MiniMax API 错误 (%s)：%s",
						"MiniMax API error (%s): %s",
						tostring(statusCode),
						tostring(statusMsg)
					)
			end

			local eventError = eventObj.error
			if eventError then
				if type(eventError) == "table" then
					local msg = eventError.message or eventError.msg or eventError.type or "unknown_error"
					return false,
						localizedFormat("MiniMax 流式错误：%s", "MiniMax stream error: %s", tostring(msg))
				end
				return false,
					localizedFormat("MiniMax 流式错误：%s", "MiniMax stream error: %s", tostring(eventError))
			end

			local data = eventObj.data
			if type(data) == "table" and type(data.subtitle_file) == "string" and data.subtitle_file ~= "" then
				subtitleUrl = data.subtitle_file
			elseif type(eventObj.subtitle_file) == "string" and eventObj.subtitle_file ~= "" then
				subtitleUrl = eventObj.subtitle_file
			end

			local isDoneEvent = minimaxIsDoneEvent(eventObj)
			if isDoneEvent then
				streamDone = true
				return true
			end

			local audioHex = minimaxExtractStreamAudioHex(eventObj)
			if audioHex and audioHex ~= "" then
				local audioBinary, hexErr = minimaxHexToBinary(audioHex)
				if not audioBinary then
					return false,
						localizedFormat(
							"MiniMax 流式音频解码失败：%s",
							"MiniMax stream audio decode failed: %s",
							tostring(hexErr)
						)
				end
				local okWrite, writeErr = partialFile:write(audioBinary)
				if not okWrite then
					return false,
						localizedFormat(
							"MiniMax 流式写入失败：%s",
							"MiniMax stream write failed: %s",
							tostring(writeErr)
						)
				end
				local okFlush, flushErr = partialFile:flush()
				if not okFlush then
					return false,
						localizedFormat(
							"MiniMax 流式写入失败：%s",
							"MiniMax stream write failed: %s",
							tostring(flushErr)
						)
				end
				chunkCount = chunkCount + 1
				totalBytes = totalBytes + #audioBinary
				logInfo(string.format("MiniMax stream chunk received: %d", #audioBinary))
			end

			return true
		end

		local ok, streamResult = App.Services.httpPostEventStream(
			context.url,
			context.payloadStr,
			context.headers,
			context.timeout or 120,
			onStreamEvent
		)
		closePartial()

		if not ok then
			return failAndCleanup(
				localizedFormat(
					"MiniMax 流式请求失败：%s",
					"MiniMax stream request failed: %s",
					tostring(streamResult)
				)
			)
		end

		local streamStatus = streamResult and tonumber(streamResult.status)
		logInfo(
			string.format("[MiniMax][stream][%s] HTTP status: %s", streamPlatform, tostring(streamStatus or "unknown"))
		)
		logInfo(string.format("MiniMax stream HTTP status: %s", tostring(streamStatus or "unknown")))
		if streamStatus and streamStatus ~= 200 then
			return failAndCleanup(
				localizedFormat(
					"MiniMax HTTP 状态码异常：%s",
					"MiniMax HTTP status is unexpected: %s",
					tostring(streamStatus)
				)
			)
		end
		if not streamDone then
			return failAndCleanup(localizedText("MiniMax 流式返回未完成", "MiniMax stream did not complete."))
		end
		if chunkCount == 0 or totalBytes <= 0 then
			return failAndCleanup(
				localizedText("MiniMax 流式返回空音频数据", "MiniMax stream returned empty audio data.")
			)
		end
		local fileSize = App.Utils.getFileSize(partialPath) or 0
		if fileSize <= 0 then
			return failAndCleanup(
				localizedText(
					"MiniMax 流式落盘后音频为空",
					"MiniMax stream audio file is empty after writing."
				)
			)
		end

		local renamed, renameErr = App.Utils.renameFile(partialPath, outputPath)
		if not renamed then
			App.Utils.removeFile(partialPath)
			logInfo(
				string.format("[MiniMax][stream][%s] failed: rename_failed:%s", streamPlatform, tostring(renameErr))
			)
			logInfo(string.format("MiniMax stream failed: rename_failed:%s", tostring(renameErr)))
			return false,
				localizedFormat(
					"MiniMax 流式音频文件落盘失败：%s",
					"MiniMax failed to finalize stream audio file: %s",
					tostring(renameErr)
				)
		end

		logInfo(string.format("[MiniMax][stream][%s] completed", streamPlatform))
		logInfo("MiniMax stream completed")
		local sampleRate = (
			context.payload
			and context.payload.audio_setting
			and context.payload.audio_setting.sample_rate
		) or 24000
		return true,
			{
				path = outputPath,
				durationSamples = params.durationSamples or 0,
				sampleRate = sampleRate,
				subtitleUrl = subtitleUrl,
			}
	end

	function Providers.MiniMax._buildContext(params)
		logInfo("[MiniMax] buildContext")
		local items = App.UI.items or {}
		local cfg = App.Config.MiniMax or {}

		local function readComboEntry(list, combo, fallbackIndex)
			list = list or {}
			local index = 0
			if combo and combo.CurrentIndex ~= nil then
				index = clampIndex(combo.CurrentIndex, #list)
			else
				index = clampIndex(fallbackIndex or 0, #list)
			end
			return list[index + 1], index
		end

		local apiKey = trim(params.apiKey or "")
		local groupId = trim(params.groupId or "")
		local isIntl = params.intl == true
		local outputDir = trim(params.outputDir or "")

		local models = cfg.models or {}
		local modelEntry = readComboEntry(models, items.minimaxModelCombo, App.State.minimax.modelIndex)
		local modelId = (modelEntry and modelEntry.id)
			or params.modelDisplay
			or App.State.minimax.model
			or (models[1] and models[1].id)
			or "speech-2.5-hd-preview"

		local voiceId = params.voiceId or App.State.minimax.voice
		if not voiceId or voiceId == "" then
			return false, localizedText("MiniMax 音色未选择", "MiniMax voice is not selected")
		end

		local emotions = cfg.emotions or {}
		local emotionEntry = readComboEntry(emotions, items.minimaxEmotionCombo, App.State.minimax.emotionIndex)
		local emotionId = emotionEntry and emotionEntry.id or App.State.minimax.emotion
		if emotionId == "default" or emotionId == "" then
			emotionId = nil
		end

		local soundEffects = cfg.soundEffects or {}
		local effectEntry = readComboEntry(
			soundEffects,
			(App.UI.minimaxVoiceModifyItems and App.UI.minimaxVoiceModifyItems.minimaxSoundEffectCombo),
			App.State.minimax.voiceEffectIndex or App.State.minimax.soundEffectIndex
		)
		local effectId = effectEntry and effectEntry.id or App.State.minimax.soundEffect
		if effectId == "default" or effectId == "" then
			effectId = nil
		end
		if App.UI.minimaxVoiceModifyItems and App.UI.minimaxVoiceModifyItems.minimaxSoundEffectCombo then
			App.State.minimax.voiceEffectIndex = App.UI.minimaxVoiceModifyItems.minimaxSoundEffectCombo.CurrentIndex
				or 0
		else
			App.State.minimax.voiceEffectIndex = App.State.minimax.voiceEffectIndex
				or App.State.minimax.soundEffectIndex
		end
		App.State.minimax.soundEffect = effectId or App.State.minimax.soundEffect

		local formatId = tostring(App.Settings.getSharedFormatId() or "wav"):lower()
		local isStreamMp3 = (formatId == "mp3")
		local baseUrl = isIntl and "https://api.minimax.io" or "https://api.minimaxi.com"
		local url = string.format("%s/v1/t2a_v2?GroupId=%s", baseUrl, groupId)

		return true,
			{
				outputDir = outputDir,
				modelId = modelId,
				voiceId = voiceId,
				emotionId = emotionId,
				effectId = effectId,
				formatId = formatId,
				isStreamMp3 = isStreamMp3,
				url = url,
				timeout = 120,
				headers = {
					Authorization = "Bearer " .. apiKey,
					["Content-Type"] = "application/json",
				},
			}
	end

	function Providers.MiniMax._buildPayload(context, mode, params)
		logInfo(string.format("[MiniMax] buildPayload mode=%s", tostring(mode)))
		local isStreamMp3 = (mode == "stream_mp3")
		local outputFormat = isStreamMp3 and "mp3" or tostring(context.formatId or "wav")
		local sampleRate = isStreamMp3 and 24000 or 32000
		local bitrate = isStreamMp3 and 64000 or 128000

		local payload = {
			model = context.modelId,
			text = params.text,
			stream = isStreamMp3 and true or false,
			subtitle_enable = params.subtitle and true or false,
			voice_setting = {
				voice_id = context.voiceId,
				speed = params.rate or 1.0,
				vol = params.volume or 1.0,
				pitch = params.pitch or 0,
			},
			audio_setting = {
				sample_rate = sampleRate,
				bitrate = bitrate,
				format = outputFormat,
				channel = 2,
			},
		}

		if context.emotionId then
			payload.voice_setting.emotion = context.emotionId
		end

		local voiceModify = {}
		local timbre = App.State.minimax.voiceTimbre or 0
		local intensity = App.State.minimax.voiceIntensity or 0
		local vmPitch = App.State.minimax.voicePitch or 0
		if timbre ~= 0 then
			voiceModify.timbre = timbre
		end
		if intensity ~= 0 then
			voiceModify.intensity = intensity
		end
		if vmPitch ~= 0 then
			voiceModify.pitch = vmPitch
		end
		if context.effectId then
			voiceModify.sound_effects = context.effectId
		end
		if next(voiceModify) then
			payload.voice_modify = voiceModify
		end
		return payload, json.encode(payload)
	end

	function Providers.MiniMax.speakNonStream(params, context)
		logInfo("[MiniMax] request non-stream")
		local body, status =
			App.Services.httpPostJson(context.url, context.payloadStr, context.headers, context.timeout or 120)
		logInfo(string.format("MiniMax HTTP status: %s", tostring(status or "unknown")))
		if not body then
			return false, localizedFormat("MiniMax 请求失败：%s", "MiniMax request failed: %s", tostring(status))
		end
		logInfo(string.format("MiniMax raw response: %s", truncateForLog(body, 1200)))
		if status and status ~= 200 then
			return false,
				localizedFormat(
					"MiniMax HTTP 状态码异常：%s",
					"MiniMax HTTP status is unexpected: %s",
					tostring(status)
				)
		end

		logInfo("[MiniMax] decode non-stream response")
		local resp, decodePos, decodeErr = json.decode(body)
		if not resp then
			logInfo(
				string.format("MiniMax JSON decode failed (pos=%s, err=%s)", tostring(decodePos), tostring(decodeErr))
			)
			local statusCode = body:match('"status_code"%s*:%s*(%d+)')
			local statusMsg = body:match('"status_msg"%s*:%s*"([^"]*)"')
			if statusCode and tonumber(statusCode) ~= 0 then
				return false,
					localizedFormat(
						"MiniMax API 错误 (%s)：%s",
						"MiniMax API error (%s): %s",
						tostring(statusCode),
						tostring(statusMsg or localizedText("未知错误", "Unknown error"))
					)
			end
			local audioHexFallback = body:match('"audio"%s*:%s*"([0-9A-Fa-f]+)"')
			if audioHexFallback then
				resp = {
					data = {
						audio = audioHexFallback,
						subtitle_file = body:match('"subtitle_file"%s*:%s*"([^"]*)"'),
					},
				}
			else
				local errDetail = decodeErr or "unknown"
				if decodePos then
					errDetail = string.format("%s (pos=%s)", tostring(errDetail), tostring(decodePos))
				end
				return false,
					localizedFormat("MiniMax 响应解析失败：%s", "MiniMax response parse failed: %s", errDetail)
			end
		end

		local baseResp = resp.base_resp or resp.baseResp or {}
		local statusCode = tonumber(baseResp.status_code or baseResp.statusCode)
		if statusCode and statusCode ~= 0 then
			local statusMsg = baseResp.status_msg
				or baseResp.statusMsg
				or localizedText("未知错误", "Unknown error")
			return false,
				localizedFormat(
					"MiniMax API 错误 (%s)：%s",
					"MiniMax API error (%s): %s",
					tostring(statusCode),
					tostring(statusMsg)
				)
		end

		local data = resp.data or {}
		local audioHex = data.audio or data.audio_data
		if not audioHex or audioHex == "" then
			return false, localizedText("MiniMax 返回空音频数据", "MiniMax returned empty audio data")
		end

		local audioBinary, hexErr = minimaxHexToBinary(audioHex)
		if not audioBinary then
			return false,
				localizedFormat("MiniMax 音频解码失败：%s", "MiniMax audio decode failed: %s", tostring(hexErr))
		end

		logInfo("[MiniMax] write non-stream output")
		local outputPath, nameErr = App.Utils.nextAvailableFile(context.outputDir, {
			baseName = params.text or "audio",
			extension = context.formatId,
			maxBaseLength = 24,
			maxAttempts = 99,
		})
		if not outputPath then
			local reason = nameErr and (": " .. tostring(nameErr)) or ""
			return false,
				localizedText("MiniMax 无法生成输出文件名", "MiniMax failed to create output filename")
					.. reason
		end

		local wrote, writeErr = App.Utils.writeFile(outputPath, audioBinary)
		if not wrote then
			return false,
				localizedFormat(
					"MiniMax 写入音频失败：%s",
					"MiniMax failed to write audio file: %s",
					tostring(writeErr)
				)
		end

		local sampleRate = (
			context.payload
			and context.payload.audio_setting
			and context.payload.audio_setting.sample_rate
		) or 24000
		return true,
			{
				path = outputPath,
				durationSamples = params.durationSamples or 0,
				sampleRate = sampleRate,
				subtitleUrl = data.subtitle_file,
			}
	end

	function Providers.MiniMax.speak(params)
		logInfo(string.format("MiniMax.speak called with params: %s", json.encode(params)))
		local okContext, contextOrErr = Providers.MiniMax._buildContext(params)
		if not okContext then
			return false, contextOrErr
		end
		local context = contextOrErr

		local mode = context.isStreamMp3 and "stream_mp3" or "non_stream"
		local payload, payloadStr = Providers.MiniMax._buildPayload(context, mode, params)
		context.payload = payload
		context.payloadStr = payloadStr
		logInfo(string.format("MiniMax payload: %s", truncateForLog(payloadStr or "", 1200)))

		if context.isStreamMp3 then
			logInfo("MiniMax stream mode enabled (mp3)")
			return Providers.MiniMax.speakStreamMp3(params, context)
		end
		return Providers.MiniMax.speakNonStream(params, context)
	end

	function Providers.OpenAI.speak(params)
		logInfo(string.format("OpenAI.speak called with params: %s", json.encode(params)))

		local items = App.UI.items or {}
		local cfg = App.Config.OpenAI or {}

		local rawText = params.text or ""
		local text = trim(rawText)

		local function normalizeBaseUrl(url)
			url = trim(url or "")
			if url == "" then
				return "https://api.openai.com"
			end
			url = url:gsub("%s+$", "")
			url = url:gsub("/+$", "")
			if url == "" then
				return "https://api.openai.com"
			end
			return url
		end

		local function selectEntry(list, combo, fallbackIndex, fallbackId)
			list = list or {}
			local index = 0
			if combo and combo.CurrentIndex ~= nil then
				index = clampIndex(combo.CurrentIndex, #list)
			elseif fallbackIndex ~= nil then
				index = clampIndex(fallbackIndex, #list)
			end
			local entry = list[index + 1]
			if entry then
				return entry, entry.id, index
			end
			return nil, fallbackId, index
		end

		local apiKey = trim(params.apiKey or "")

		local baseUrl = normalizeBaseUrl(params.baseUrl or "")
		local versionedBase = baseUrl
		if not versionedBase:match("/v%d+$") then
			versionedBase = versionedBase .. "/v1"
		end
		local url = versionedBase .. "/audio/speech"

		local models = cfg.models or {}
		local modelEntry, modelId = selectEntry(
			models,
			items.OpenAIModelCombo,
			App.State.openai and App.State.openai.modelIndex,
			App.State.openai and App.State.openai.model or "gpt-4o-mini-tts"
		)
		modelId = modelId or (models[1] and models[1].id) or "gpt-4o-mini-tts"

		local voices = cfg.voices or {}
		local voiceEntry, voiceId = selectEntry(
			voices,
			items.OpenAIVoiceCombo,
			App.State.openai and App.State.openai.voiceIndex,
			App.State.openai and App.State.openai.voice or "alloy"
		)
		voiceId = voiceId or (voices[1] and voices[1].id) or "alloy"

		local formatId = (App.Settings.getSharedFormatId() or "mp3"):lower()

		local speed = tonumber(params.rate) or (App.State.openai and App.State.openai.rate) or 1.0
		if speed < 0.25 then
			speed = 0.25
		end
		if speed > 4.0 then
			speed = 4.0
		end

		local instructions = trim(params.instruction or "")
		if instructions ~= "" and (modelId == "tts-1" or modelId == "tts-1-hd") then
			instructions = ""
		end

		local outputDir = trim(params.outputDir or "")

		local payload = {
			model = modelId,
			input = text,
			voice = voiceId,
			response_format = formatId,
			speed = speed,
			stream = false,
		}
		if instructions ~= "" then
			payload.instructions = instructions
		end

		local payloadStr = json.encode(payload)
		local headers = {
			Authorization = "Bearer " .. apiKey,
			["Content-Type"] = "application/json",
		}

		local function decodeJson(bodyStr)
			local ok, decoded = pcall(json.decode, bodyStr)
			if ok and type(decoded) == "table" then
				return decoded
			end
			return nil
		end

		local body, status = App.Services.httpPostJson(url, payloadStr, headers, 120)
		logInfo(string.format("OpenAI HTTP status: %s", tostring(status or "unknown")))
		if not body then
			return false, localizedFormat("OpenAI 请求失败：%s", "OpenAI request failed: %s", tostring(status))
		end
		if body == "" then
			logInfo("OpenAI response body is empty")
			return false, localizedText("OpenAI 返回空响应", "OpenAI returned an empty response")
		end
		local firstNonWhitespace = body:match("^%s*(.)")
		if firstNonWhitespace == "{" or firstNonWhitespace == "[" then
			logInfo(string.format("OpenAI response JSON: %s", truncateForLog(body, 1200)))
		else
			logInfo(string.format("OpenAI response size: %d bytes", #body))
		end

		local numericStatus = tonumber(status)
		if numericStatus and (numericStatus < 200 or numericStatus >= 300) then
			local decoded = decodeJson(body)
			local errMessage = string.format("HTTP %d", numericStatus)
			if decoded then
				if decoded.error then
					if type(decoded.error) == "table" then
						errMessage = decoded.error.message or decoded.error.type or errMessage
					else
						errMessage = tostring(decoded.error)
					end
				elseif decoded.message then
					errMessage = decoded.message
				end
			end
			return false, localizedFormat("OpenAI 请求失败：%s", "OpenAI request failed: %s", tostring(errMessage))
		end

		if firstNonWhitespace == "{" or firstNonWhitespace == "[" then
			local decoded = decodeJson(body)
			if decoded then
				local errMessage = localizedText("未知错误", "Unknown error")
				if decoded.error then
					if type(decoded.error) == "table" then
						errMessage = decoded.error.message or decoded.error.type or errMessage
					else
						errMessage = tostring(decoded.error)
					end
				elseif decoded.message then
					errMessage = decoded.message
				end
				return false, localizedFormat("OpenAI 错误：%s", "OpenAI error: %s", tostring(errMessage))
			end
		end

		local outputPath, nameErr = App.Utils.nextAvailableFile(outputDir, {
			baseName = text,
			extension = formatId,
			maxBaseLength = 24,
			maxAttempts = 99,
		})
		if not outputPath then
			local reason = nameErr and (": " .. tostring(nameErr)) or ""
			return false,
				localizedText("OpenAI 无法生成输出文件名", "OpenAI failed to create output filename") .. reason
		end

		local wrote, writeErr = App.Utils.writeFile(outputPath, body)
		if not wrote then
			return false,
				localizedFormat(
					"OpenAI 写入音频失败：%s",
					"OpenAI failed to write audio file: %s",
					tostring(writeErr)
				)
		end

		return true,
			{
				path = outputPath,
				durationSamples = params.durationSamples or 0,
				sampleRate = 44100,
			}
	end

	function Providers.Azure.buildAsyncTask(params)
		local outputPath, pathErr = App.Azure.buildOutputPath(params)
		if not outputPath then
			return false,
				localizedText("无法准备保存输出文件：", "Unable to prepare output file: ") .. tostring(
					pathErr or "unknown"
				)
		end

		local task =
			makeAsyncTaskBase("azure", params, (params.useApi and 120 or (App.Config.Const.SUPABASE_TIMEOUT + 120)))
		task.outputPath = outputPath
		task.workPath = outputPath .. ".part"

		function task:startCredentialFetch()
			local cached = trim((App.State.providerSecrets or {})[App.Config.Const.AZURE_SPEECH_PROVIDER] or "")
			if cached ~= "" then
				return self:startSynthesis(cached, "eastus")
			end

			local bodyPath, bodyErr = Utils.makeTempPath("json")
			if not bodyPath then
				return false, "tmpname_failed:" .. tostring(bodyErr)
			end
			local infoPath, infoErr = Utils.makeTempPath("info")
			if not infoPath then
				removeTaskPaths({ bodyPath })
				return false, "tmpname_failed:" .. tostring(infoErr)
			end
			local errPath, errErr = Utils.makeTempPath("err")
			if not errPath then
				removeTaskPaths({ bodyPath, infoPath })
				return false, "tmpname_failed:" .. tostring(errErr)
			end

			self.secretBodyPath = bodyPath
			self.secretInfoPath = infoPath
			self.secretErrPath = errPath
			self:addCleanupPath(bodyPath)
			self:addCleanupPath(infoPath)
			self:addCleanupPath(errPath)

			local url = string.format(
				"%s/functions/v1/getApiKey?provider=%s",
				App.Config.Const.SUPABASE_URL,
				Utils.urlEncode(App.Config.Const.AZURE_SPEECH_PROVIDER)
			)
			local headers = {
				Authorization = "Bearer " .. App.Config.Const.SUPABASE_ANON_KEY,
				apikey = App.Config.Const.SUPABASE_ANON_KEY,
				["Content-Type"] = "application/json",
				["User-Agent"] = string.format("%s/%s", App.Config.Const.SCRIPT_NAME, App.Config.Const.SCRIPT_VERSION),
			}
			local headerParts = App.Services._buildCurlHeaders(headers)
			local command = string.format(
				'curl %s -m %d %s %s -o %s -w "%%{http_code}" > %s 2> %s',
				buildStandardCurlFlags(self.secretTlsCompatFlag),
				App.Config.Const.SUPABASE_TIMEOUT,
				table.concat(headerParts, " "),
				quoteShellArg(url),
				quoteShellArg(bodyPath),
				quoteShellArg(infoPath),
				quoteShellArg(errPath)
			)
			local handle, launchErr = launchAsyncCommand(command)
			if not handle then
				return false,
					localizedText("启动 Azure Key 获取失败：", "Failed to start Azure key fetch: ") .. tostring(
						launchErr or "unknown"
					)
			end
			self.processHandle = handle
			self.stage = "fetch_secret"
			return true
		end

		function task:startSynthesis(apiKey, region)
			local ssmlPath, ssmlErr = Utils.makeTempPath("ssml")
			if not ssmlPath then
				return false,
					localizedText("创建临时 SSML 文件失败：", "Failed to create temporary SSML file: ")
						.. tostring(ssmlErr)
			end
			local infoPath, infoErr = Utils.makeTempPath("info")
			if not infoPath then
				removeTaskPaths({ ssmlPath })
				return false,
					localizedText(
						"创建临时信息文件失败：",
						"Failed to create temporary response info file: "
					) .. tostring(infoErr)
			end
			local errPath, errErr = Utils.makeTempPath("err")
			if not errPath then
				removeTaskPaths({ ssmlPath, infoPath })
				return false,
					localizedText("创建临时错误文件失败：", "Failed to create temporary error file: ")
						.. tostring(errErr)
			end

			local wrote, writeErr = Utils.writeFile(ssmlPath, App.Azure.buildSsml(params))
			if not wrote then
				removeTaskPaths({ ssmlPath, infoPath, errPath })
				return false,
					localizedText("写入 SSML 文件失败：", "Failed to write SSML file: ") .. tostring(writeErr)
			end

			Utils.removeFile(self.workPath)

			self.ssmlPath = ssmlPath
			self.synthInfoPath = infoPath
			self.synthErrPath = errPath
			self.region = region
			self:addCleanupPath(ssmlPath)
			self:addCleanupPath(infoPath)
			self:addCleanupPath(errPath)
			self:addCleanupPath(self.workPath)

			local safeApiKey = tostring(apiKey or ""):gsub('"', '\\"')
			local command = string.format(
				'curl %s -m %d -X POST -H "Content-Type: application/ssml+xml" -H "X-Microsoft-OutputFormat: %s" -H "Ocp-Apim-Subscription-Key: %s" -H "User-Agent: heiba-azure-tts-curl/1.0" --data-binary @%s %s -o %s -w "%%{http_code}" > %s 2> %s',
				buildStandardCurlFlags(self.synthTlsCompatFlag),
				120,
				params.outputFormat or "riff-24khz-16bit-mono-pcm",
				safeApiKey,
				quoteShellArg(ssmlPath),
				quoteShellArg(string.format("https://%s.tts.speech.microsoft.com/cognitiveservices/v1", region)),
				quoteShellArg(self.workPath),
				quoteShellArg(infoPath),
				quoteShellArg(errPath)
			)
			local handle, launchErr = launchAsyncCommand(command)
			if not handle then
				return false,
					localizedText("启动 Azure 合成失败：", "Failed to start Azure synthesis: ") .. tostring(
						launchErr or "unknown"
					)
			end
			self.processHandle = handle
			self.stage = "synth"
			return true
		end

		function task:start()
			if params.useApi then
				return self:startSynthesis(params.apiKey, params.region)
			end
			return self:startCredentialFetch()
		end

		function task:poll()
			local finished, exitCode = self.processHandle:poll(0)
			if not finished then
				return false
			end
			closeTaskProcess(self.processHandle, false)
			self.processHandle = nil

			if self.stage == "fetch_secret" then
				local body = Utils.readFile(self.secretBodyPath) or ""
				local httpCode = parseHttpCode(readTrimmedFileSafe(self.secretInfoPath))
				local errBody = readTrimmedFileSafe(self.secretErrPath)
				removeTaskPaths({ self.secretBodyPath, self.secretInfoPath, self.secretErrPath })
				self.secretBodyPath = nil
				self.secretInfoPath = nil
				self.secretErrPath = nil

				if tonumber(exitCode or 1) ~= 0 then
					local retried, retryErr = tryStartWindowsCurlCompatRetry(
						self.secretTlsCompatFlag,
						table.concat({ errBody, body }, "\n"),
						"azure_key_fetch",
						function(nextFlag)
							self.secretTlsCompatFlag = nextFlag
							return self:startCredentialFetch()
						end
					)
					if retried == true then
						return false
					elseif retried == nil then
						return true, { ok = false, error = tostring(retryErr) }
					end
					return true,
						{
							ok = false,
							error = localizedFormat(
								"获取 Azure Key 失败：%s",
								"Failed to fetch Azure key: %s",
								errBody ~= "" and errBody or tostring(exitCode or 1)
							),
						}
				end
				if httpCode and (httpCode < 200 or httpCode >= 300) then
					return true,
						{
							ok = false,
							error = localizedFormat(
								"获取 Azure Key 失败：HTTP %s",
								"Failed to fetch Azure key: HTTP %s",
								tostring(httpCode)
							),
						}
				end

				local okDecode, decoded = pcall(json.decode, body)
				if not okDecode or type(decoded) ~= "table" then
					return true,
						{
							ok = false,
							error = localizedText(
								"自动获取 Azure Key 失败：返回内容无法解析。",
								"Failed to fetch Azure key: response could not be parsed."
							),
						}
				end
				local apiKey = trim(decoded.api_key or decoded.apiKey or decoded.key or decoded.secret or "")
				if apiKey == "" then
					return true,
						{
							ok = false,
							error = localizedText(
								"自动获取 Azure Key 失败：返回内容中没有可用 Key。",
								"Failed to fetch Azure key: response did not include a usable key."
							),
						}
				end
				App.State.providerSecrets[App.Config.Const.AZURE_SPEECH_PROVIDER] = apiKey
				local okStart, startErr = self:startSynthesis(apiKey, "eastus")
				if not okStart then
					return true, { ok = false, error = startErr }
				end
				return false
			end

			local httpInfo = readTrimmedFileSafe(self.synthInfoPath)
			local errBody = readTrimmedFileSafe(self.synthErrPath)
			local httpCode = parseHttpCode(httpInfo)
			removeTaskPaths({ self.ssmlPath, self.synthInfoPath, self.synthErrPath })
			self.ssmlPath = nil
			self.synthInfoPath = nil
			self.synthErrPath = nil

			if tonumber(exitCode or 1) ~= 0 then
				local retried, retryErr = tryStartWindowsCurlCompatRetry(
					self.synthTlsCompatFlag,
					table.concat({ errBody, httpInfo }, "\n"),
					"azure_synthesis",
					function(nextFlag)
						self.synthTlsCompatFlag = nextFlag
						return self:startSynthesis(
							params.useApi and params.apiKey or App.State.providerSecrets[App.Config.Const.AZURE_SPEECH_PROVIDER],
							self.region or params.region or "eastus"
						)
					end
				)
				if retried == true then
					return false
				elseif retried == nil then
					return true, { ok = false, error = tostring(retryErr) }
				end
				Utils.removeFile(self.workPath)
				return true,
					{
						ok = false,
						error = localizedFormat(
							"调用 Azure API 失败：%s",
							"Azure API request failed: %s",
							errBody ~= "" and errBody or (httpInfo ~= "" and httpInfo or tostring(exitCode or 1))
						),
					}
			end
			if httpCode and (httpCode < 200 or httpCode >= 300) then
				Utils.removeFile(self.workPath)
				return true,
					{
						ok = false,
						error = localizedFormat(
							"Azure HTTP 状态码异常：%s",
							"Azure HTTP status is unexpected: %s",
							tostring(httpCode)
						),
					}
			end

			local size = Utils.getFileSize(self.workPath) or 0
			if size <= 0 then
				Utils.removeFile(self.workPath)
				return true,
					{
						ok = false,
						error = localizedText(
							"Azure API 返回空音频文件。",
							"Azure API returned an empty audio file."
						),
					}
			end

			local renamed, renameErr = Utils.renameFile(self.workPath, self.outputPath)
			if not renamed then
				Utils.removeFile(self.workPath)
				return true,
					{
						ok = false,
						error = localizedFormat(
							"Azure 音频文件落盘失败：%s",
							"Azure failed to finalize the audio file: %s",
							tostring(renameErr)
						),
					}
			end

			return true,
				{
					ok = true,
					path = self.outputPath,
					durationSamples = params.durationSamples or 0,
					sampleRate = App.Azure.deriveSampleRate(params.outputFormat),
				}
		end

		return true, task
	end

	function Providers.OpenAI.buildAsyncTask(params)
		local request = buildOpenAIRequestContext(params)
		local outputPath, nameErr = Utils.nextAvailableFile(request.outputDir, {
			baseName = request.text,
			extension = request.formatId,
			maxBaseLength = 24,
			maxAttempts = 99,
		})
		if not outputPath then
			local reason = nameErr and (": " .. tostring(nameErr)) or ""
			return false,
				localizedText("OpenAI 无法生成输出文件名", "OpenAI failed to create output filename") .. reason
		end

		local payloadPath, payloadErr = App.Services._writeTempPayload(request.payloadStr)
		if not payloadPath then
			return false, payloadErr
		end
		local infoPath, infoErr = Utils.makeTempPath("info")
		if not infoPath then
			removeTaskPaths({ payloadPath })
			return false, "tmpname_failed:" .. tostring(infoErr)
		end
		local errPath, errErr = Utils.makeTempPath("err")
		if not errPath then
			removeTaskPaths({ payloadPath, infoPath })
			return false, "tmpname_failed:" .. tostring(errErr)
		end

		local task = makeAsyncTaskBase("openai", params, 120)
		task.outputPath = outputPath
		task.workPath = outputPath .. ".part"
		task.payloadPath = payloadPath
		task.infoPath = infoPath
		task.errPath = errPath
		task:addCleanupPath(payloadPath)
		task:addCleanupPath(infoPath)
		task:addCleanupPath(errPath)
		task:addCleanupPath(task.workPath)

		function task:start()
			Utils.removeFile(self.workPath)
			local headerParts = App.Services._buildCurlHeaders(request.headers, { contentType = "application/json" })
			local command = string.format(
				'curl %s -m %d -X POST %s --data-binary @%s %s -o %s -w "%%{http_code}" > %s 2> %s',
				buildStandardCurlFlags(self.tlsCompatFlag),
				120,
				table.concat(headerParts, " "),
				quoteShellArg(self.payloadPath),
				quoteShellArg(request.url),
				quoteShellArg(self.workPath),
				quoteShellArg(self.infoPath),
				quoteShellArg(self.errPath)
			)
			local handle, launchErr = launchAsyncCommand(command)
			if not handle then
				return false,
					localizedText("启动 OpenAI 合成失败：", "Failed to start OpenAI synthesis: ") .. tostring(
						launchErr or "unknown"
					)
			end
			self.processHandle = handle
			return true
		end

		function task:poll()
			local finished, exitCode = self.processHandle:poll(0)
			if not finished then
				return false
			end
			closeTaskProcess(self.processHandle, false)
			self.processHandle = nil

			local body = Utils.readFile(self.workPath) or ""
			local httpCode = parseHttpCode(readTrimmedFileSafe(self.infoPath))
			local errBody = readTrimmedFileSafe(self.errPath)

			if tonumber(exitCode or 1) ~= 0 then
				local retried, retryErr = tryStartWindowsCurlCompatRetry(
					self.tlsCompatFlag,
					table.concat({ errBody, body }, "\n"),
					"openai_synthesis",
					function(nextFlag)
						self.tlsCompatFlag = nextFlag
						return self:start()
					end
				)
				if retried == true then
					return false
				elseif retried == nil then
					return true, { ok = false, error = tostring(retryErr) }
				end
				Utils.removeFile(self.workPath)
				return true,
					{
						ok = false,
						error = localizedFormat(
							"OpenAI 请求失败：%s",
							"OpenAI request failed: %s",
							errBody ~= "" and errBody or tostring(exitCode or 1)
						),
					}
			end
			if body == "" then
				Utils.removeFile(self.workPath)
				return true,
					{
						ok = false,
						error = localizedText("OpenAI 返回空响应", "OpenAI returned an empty response"),
					}
			end

			local numericStatus = tonumber(httpCode)
			if numericStatus and (numericStatus < 200 or numericStatus >= 300) then
				local decoded = decodeOpenAIJson(body)
				local errMessage = string.format("HTTP %d", numericStatus)
				if decoded then
					if decoded.error then
						if type(decoded.error) == "table" then
							errMessage = decoded.error.message or decoded.error.type or errMessage
						else
							errMessage = tostring(decoded.error)
						end
					elseif decoded.message then
						errMessage = decoded.message
					end
				end
				Utils.removeFile(self.workPath)
				return true,
					{
						ok = false,
						error = localizedFormat(
							"OpenAI 请求失败：%s",
							"OpenAI request failed: %s",
							tostring(errMessage)
						),
					}
			end

			local firstNonWhitespace = body:match("^%s*(.)")
			if firstNonWhitespace == "{" or firstNonWhitespace == "[" then
				local decoded = decodeOpenAIJson(body)
				if decoded then
					local errMessage = localizedText("未知错误", "Unknown error")
					if decoded.error then
						if type(decoded.error) == "table" then
							errMessage = decoded.error.message or decoded.error.type or errMessage
						else
							errMessage = tostring(decoded.error)
						end
					elseif decoded.message then
						errMessage = decoded.message
					end
					Utils.removeFile(self.workPath)
					return true,
						{
							ok = false,
							error = localizedFormat("OpenAI 错误：%s", "OpenAI error: %s", tostring(errMessage)),
						}
				end
			end

			local size = Utils.getFileSize(self.workPath) or 0
			if size <= 0 then
				Utils.removeFile(self.workPath)
				return true,
					{
						ok = false,
						error = localizedText("OpenAI 返回空响应", "OpenAI returned an empty response"),
					}
			end

			local renamed, renameErr = Utils.renameFile(self.workPath, self.outputPath)
			if not renamed then
				Utils.removeFile(self.workPath)
				return true,
					{
						ok = false,
						error = localizedFormat(
							"OpenAI 音频文件落盘失败：%s",
							"OpenAI failed to finalize the audio file: %s",
							tostring(renameErr)
						),
					}
			end

			return true,
				{
					ok = true,
					path = self.outputPath,
					durationSamples = params.durationSamples or 0,
					sampleRate = 44100,
				}
		end

		return true, task
	end

	local function buildMiniMaxAsyncNonStreamTask(params, context)
		local outputPath, nameErr = Utils.nextAvailableFile(context.outputDir, {
			baseName = params.text or "audio",
			extension = context.formatId,
			maxBaseLength = 24,
			maxAttempts = 99,
		})
		if not outputPath then
			local reason = nameErr and (": " .. tostring(nameErr)) or ""
			return false,
				localizedText("MiniMax 无法生成输出文件名", "MiniMax failed to create output filename")
					.. reason
		end

		local payloadPath, payloadErr = App.Services._writeTempPayload(context.payloadStr)
		if not payloadPath then
			return false, payloadErr
		end
		local bodyPath, bodyErr = Utils.makeTempPath("json")
		if not bodyPath then
			removeTaskPaths({ payloadPath })
			return false, "tmpname_failed:" .. tostring(bodyErr)
		end
		local infoPath, infoErr = Utils.makeTempPath("info")
		if not infoPath then
			removeTaskPaths({ payloadPath, bodyPath })
			return false, "tmpname_failed:" .. tostring(infoErr)
		end
		local errPath, errErr = Utils.makeTempPath("err")
		if not errPath then
			removeTaskPaths({ payloadPath, bodyPath, infoPath })
			return false, "tmpname_failed:" .. tostring(errErr)
		end

		local task = makeAsyncTaskBase("minimax", params, context.timeout or 120)
		task.outputPath = outputPath
		task.bodyPath = bodyPath
		task.infoPath = infoPath
		task.errPath = errPath
		task.payloadPath = payloadPath
		task:addCleanupPath(payloadPath)
		task:addCleanupPath(bodyPath)
		task:addCleanupPath(infoPath)
		task:addCleanupPath(errPath)

		function task:start()
			local headerParts = App.Services._buildCurlHeaders(context.headers, { contentType = "application/json" })
			local command = string.format(
				'curl %s -m %d -X POST %s --data-binary @%s %s -o %s -w "%%{http_code}" > %s 2> %s',
				buildStandardCurlFlags(self.tlsCompatFlag),
				context.timeout or 120,
				table.concat(headerParts, " "),
				quoteShellArg(self.payloadPath),
				quoteShellArg(context.url),
				quoteShellArg(self.bodyPath),
				quoteShellArg(self.infoPath),
				quoteShellArg(self.errPath)
			)
			local handle, launchErr = launchAsyncCommand(command)
			if not handle then
				return false,
					localizedText("启动 MiniMax 合成失败：", "Failed to start MiniMax synthesis: ") .. tostring(
						launchErr or "unknown"
					)
			end
			self.processHandle = handle
			return true
		end

		function task:poll()
			local finished, exitCode = self.processHandle:poll(0)
			if not finished then
				return false
			end
			closeTaskProcess(self.processHandle, false)
			self.processHandle = nil

			local body = Utils.readFile(self.bodyPath) or ""
			local httpCode = parseHttpCode(readTrimmedFileSafe(self.infoPath))
			local errBody = readTrimmedFileSafe(self.errPath)

			if tonumber(exitCode or 1) ~= 0 then
				local retried, retryErr = tryStartWindowsCurlCompatRetry(
					self.tlsCompatFlag,
					table.concat({ errBody, body }, "\n"),
					"minimax_nonstream",
					function(nextFlag)
						self.tlsCompatFlag = nextFlag
						return self:start()
					end
				)
				if retried == true then
					return false
				elseif retried == nil then
					return true, { ok = false, error = tostring(retryErr) }
				end
				return true,
					{
						ok = false,
						error = localizedFormat(
							"MiniMax 请求失败：%s",
							"MiniMax request failed: %s",
							errBody ~= "" and errBody or tostring(exitCode or 1)
						),
					}
			end
			if httpCode and httpCode ~= 200 then
				local parsed, parseErr = parseMiniMaxResponseBody(body)
				return true,
					{
						ok = false,
						error = parseErr or localizedFormat(
							"MiniMax HTTP 状态码异常：%s",
							"MiniMax HTTP status is unexpected: %s",
							tostring(httpCode)
						),
					}
			end

			local parsed, parseErr = parseMiniMaxResponseBody(body)
			if not parsed then
				return true, { ok = false, error = parseErr }
			end

			local audioBinary, hexErr = minimaxHexToBinary(parsed.audioHex)
			if not audioBinary then
				return true,
					{
						ok = false,
						error = localizedFormat(
							"MiniMax 音频解码失败：%s",
							"MiniMax audio decode failed: %s",
							tostring(hexErr)
						),
					}
			end

			local wrote, writeErr = Utils.writeFile(self.outputPath, audioBinary)
			if not wrote then
				return true,
					{
						ok = false,
						error = localizedFormat(
							"MiniMax 写入音频失败：%s",
							"MiniMax failed to write audio file: %s",
							tostring(writeErr)
						),
					}
			end

			local sampleRate = (
				context.payload
				and context.payload.audio_setting
				and context.payload.audio_setting.sample_rate
			) or 24000
			logInfo(
				string.format(
					"MiniMax non-stream completed. subtitleUrl=%s",
					tostring(parsed.data and parsed.data.subtitle_file or "")
				)
			)
			return true,
				{
					ok = true,
					path = self.outputPath,
					durationSamples = params.durationSamples or 0,
					sampleRate = sampleRate,
					subtitleUrl = parsed.data and parsed.data.subtitle_file,
				}
		end

		return true, task
	end

	local function buildMiniMaxAsyncStreamTask(params, context)
		local outputPath, nameErr = Utils.nextAvailableFile(context.outputDir, {
			baseName = params.text or "audio",
			extension = "mp3",
			maxBaseLength = 24,
			maxAttempts = 99,
		})
		if not outputPath then
			local reason = nameErr and (": " .. tostring(nameErr)) or ""
			return false,
				localizedText("MiniMax 无法生成输出文件名", "MiniMax failed to create output filename")
					.. reason
		end

		local payloadPath, payloadErr = App.Services._writeTempPayload(context.payloadStr)
		if not payloadPath then
			return false, payloadErr
		end
		local streamPath, streamErr = Utils.makeTempPath("stream")
		if not streamPath then
			removeTaskPaths({ payloadPath })
			return false, "tmpname_failed:" .. tostring(streamErr)
		end
		local infoPath, infoErr = Utils.makeTempPath("info")
		if not infoPath then
			removeTaskPaths({ payloadPath, streamPath })
			return false, "tmpname_failed:" .. tostring(infoErr)
		end
		local errPath, errErr = Utils.makeTempPath("err")
		if not errPath then
			removeTaskPaths({ payloadPath, streamPath, infoPath })
			return false, "tmpname_failed:" .. tostring(errErr)
		end

		local task = makeAsyncTaskBase("minimax", params, context.timeout or 120)
		task.outputPath = outputPath
		task.partialPath = outputPath .. ".partial"
		task.payloadPath = payloadPath
		task.streamPath = streamPath
		task.infoPath = infoPath
		task.errPath = errPath
		task.readOffset = 0
		task.streamDone = false
		task.chunkCount = 0
		task.totalBytes = 0
		task.subtitleUrl = nil
		task.partialFile = nil
		task:addCleanupPath(payloadPath)
		task:addCleanupPath(streamPath)
		task:addCleanupPath(infoPath)
		task:addCleanupPath(errPath)
		task:addCleanupPath(task.partialPath)
		local onStreamEvent

		function task:resetStreamAttemptState()
			self.readOffset = 0
			self.streamDone = false
			self.chunkCount = 0
			self.totalBytes = 0
			self.subtitleUrl = nil
			self.processor = createEventStreamProcessor(onStreamEvent)
		end

		function task:closePartial()
			if self.partialFile then
				pcall(function()
					self.partialFile:close()
				end)
				self.partialFile = nil
			end
		end

		function onStreamEvent(eventObj)
			if type(eventObj) ~= "table" then
				return false, "stream_event_not_table"
			end
			local baseResp = eventObj.base_resp or eventObj.baseResp or {}
			local statusCode = tonumber(baseResp.status_code or baseResp.statusCode)
			if statusCode and statusCode ~= 0 then
				local statusMsg = baseResp.status_msg
					or baseResp.statusMsg
					or localizedText("未知错误", "Unknown error")
				return false,
					localizedFormat(
						"MiniMax API 错误 (%s)：%s",
						"MiniMax API error (%s): %s",
						tostring(statusCode),
						tostring(statusMsg)
					)
			end

			local eventError = eventObj.error
			if eventError then
				if type(eventError) == "table" then
					local msg = eventError.message or eventError.msg or eventError.type or "unknown_error"
					return false,
						localizedFormat("MiniMax 流式错误：%s", "MiniMax stream error: %s", tostring(msg))
				end
				return false,
					localizedFormat("MiniMax 流式错误：%s", "MiniMax stream error: %s", tostring(eventError))
			end

			local data = eventObj.data
			if type(data) == "table" and type(data.subtitle_file) == "string" and data.subtitle_file ~= "" then
				task.subtitleUrl = data.subtitle_file
			elseif type(eventObj.subtitle_file) == "string" and eventObj.subtitle_file ~= "" then
				task.subtitleUrl = eventObj.subtitle_file
			end

			if minimaxIsDoneEvent(eventObj) then
				task.streamDone = true
				return true
			end

			local audioHex = minimaxExtractStreamAudioHex(eventObj)
			if audioHex and audioHex ~= "" then
				local audioBinary, hexErr = minimaxHexToBinary(audioHex)
				if not audioBinary then
					return false,
						localizedFormat(
							"MiniMax 流式音频解码失败：%s",
							"MiniMax stream audio decode failed: %s",
							tostring(hexErr)
						)
				end
				local okWrite, writeErr = task.partialFile:write(audioBinary)
				if not okWrite then
					return false,
						localizedFormat(
							"MiniMax 流式写入失败：%s",
							"MiniMax stream write failed: %s",
							tostring(writeErr)
						)
				end
				local okFlush, flushErr = task.partialFile:flush()
				if not okFlush then
					return false,
						localizedFormat(
							"MiniMax 流式写入失败：%s",
							"MiniMax stream write failed: %s",
							tostring(flushErr)
						)
				end
				task.chunkCount = task.chunkCount + 1
				task.totalBytes = task.totalBytes + #audioBinary
			end

			return true
		end

		task:resetStreamAttemptState()

		function task:start()
			self:closePartial()
			self:resetStreamAttemptState()
			Utils.removeFile(self.partialPath)
			Utils.removeFile(self.streamPath)
			Utils.removeFile(self.infoPath)
			Utils.removeFile(self.errPath)
			local partialFile, openErr = Utils.openBinaryWriter(self.partialPath)
			if not partialFile then
				return false,
					localizedFormat(
						"MiniMax 流式写入文件失败：%s",
						"MiniMax failed to open stream output file: %s",
						tostring(openErr)
					)
			end
			self.partialFile = partialFile

			local headerParts = App.Services._buildCurlHeaders(context.headers, {
				contentType = "application/json",
				accept = "application/json",
				clearExpect = true,
			})
			local command = string.format(
				'curl %s -m %d -X POST %s --data-binary @%s %s -o %s -w "__CURL_HTTP_CODE__:%s" > %s 2> %s',
				buildStreamCurlFlags(self.tlsCompatFlag),
				context.timeout or 120,
				table.concat(headerParts, " "),
				quoteShellArg(self.payloadPath),
				quoteShellArg(context.url),
				quoteShellArg(self.streamPath),
				"%{http_code}",
				quoteShellArg(self.infoPath),
				quoteShellArg(self.errPath)
			)
			local handle, launchErr = launchAsyncCommand(command)
			if not handle then
				self:closePartial()
				return false,
					localizedText("启动 MiniMax 流式合成失败：", "Failed to start MiniMax stream synthesis: ")
						.. tostring(launchErr or "unknown")
			end
			self.processHandle = handle
			return true
		end

		function task:poll()
			if Utils.fileExists(self.streamPath) then
				local chunk, readErr, nextOffset = App.Audio.readGrowingFileChunk(self.streamPath, self.readOffset)
				if chunk == nil then
					return true,
						{
							ok = false,
							error = localizedFormat(
								"MiniMax 流式读取失败：%s",
								"MiniMax stream read failed: %s",
								tostring(readErr)
							),
						}
				end
				self.readOffset = nextOffset or self.readOffset
				if chunk ~= "" then
					local okChunk, chunkErr = self.processor.processChunkText(chunk, false)
					if not okChunk then
						return true, { ok = false, error = tostring(chunkErr) }
					end
				end
			end

			local finished, exitCode = self.processHandle:poll(0)
			if not finished then
				return false
			end
			closeTaskProcess(self.processHandle, false)
			self.processHandle = nil

			if Utils.fileExists(self.streamPath) then
				local finalChunk, finalErr, finalOffset =
					App.Audio.readGrowingFileChunk(self.streamPath, self.readOffset)
				if finalChunk == nil then
					return true,
						{
							ok = false,
							error = localizedFormat(
								"MiniMax 流式读取失败：%s",
								"MiniMax stream read failed: %s",
								tostring(finalErr)
							),
						}
				end
				self.readOffset = finalOffset or self.readOffset
				if finalChunk ~= "" then
					local okChunk, chunkErr = self.processor.processChunkText(finalChunk, false)
					if not okChunk then
						return true, { ok = false, error = tostring(chunkErr) }
					end
				end
			end
			local okFinalize, finalizeErr = self.processor.processChunkText("", true)
			if not okFinalize then
				return true, { ok = false, error = tostring(finalizeErr) }
			end

			local streamStatus = parseHttpCode(readTrimmedFileSafe(self.infoPath))
			local errBody = readTrimmedFileSafe(self.errPath)
			self:closePartial()

			if tonumber(exitCode or 1) ~= 0 then
				local retried, retryErr = tryStartWindowsCurlCompatRetry(
					self.tlsCompatFlag,
					table.concat({ errBody, tostring(streamStatus or "") }, "\n"),
					"minimax_stream",
					function(nextFlag)
						self.tlsCompatFlag = nextFlag
						return self:start()
					end
				)
				if retried == true then
					return false
				elseif retried == nil then
					return true, { ok = false, error = tostring(retryErr) }
				end
				return true,
					{
						ok = false,
						error = localizedFormat(
							"MiniMax 流式请求失败：%s",
							"MiniMax stream request failed: %s",
							errBody ~= "" and errBody or tostring(exitCode or 1)
						),
					}
			end
			if streamStatus and streamStatus ~= 200 then
				return true,
					{
						ok = false,
						error = localizedFormat(
							"MiniMax HTTP 状态码异常：%s",
							"MiniMax HTTP status is unexpected: %s",
							tostring(streamStatus)
						),
					}
			end
			if not self.streamDone then
				return true,
					{
						ok = false,
						error = localizedText("MiniMax 流式返回未完成", "MiniMax stream did not complete."),
					}
			end
			if self.chunkCount == 0 or self.totalBytes <= 0 then
				return true,
					{
						ok = false,
						error = localizedText(
							"MiniMax 流式返回空音频数据",
							"MiniMax stream returned empty audio data."
						),
					}
			end

			local fileSize = Utils.getFileSize(self.partialPath) or 0
			if fileSize <= 0 then
				return true,
					{
						ok = false,
						error = localizedText(
							"MiniMax 流式落盘后音频为空",
							"MiniMax stream audio file is empty after writing."
						),
					}
			end

			local renamed, renameErr = Utils.renameFile(self.partialPath, self.outputPath)
			if not renamed then
				Utils.removeFile(self.partialPath)
				return true,
					{
						ok = false,
						error = localizedFormat(
							"MiniMax 流式音频文件落盘失败：%s",
							"MiniMax failed to finalize stream audio file: %s",
							tostring(renameErr)
						),
					}
			end

			local sampleRate = (
				context.payload
				and context.payload.audio_setting
				and context.payload.audio_setting.sample_rate
			) or 24000
			return true,
				{
					ok = true,
					path = self.outputPath,
					durationSamples = params.durationSamples or 0,
					sampleRate = sampleRate,
					subtitleUrl = self.subtitleUrl,
				}
		end

		function task:cleanup(options)
			options = options or {}
			closeTaskProcess(self.processHandle, options.terminateProcess == true)
			self.processHandle = nil
			self:closePartial()
			removeTaskPaths(self.cleanupPaths)
			self.cleanupPaths = {}
		end

		return true, task
	end

	function Providers.MiniMax.buildAsyncTask(params)
		local okContext, contextOrErr = Providers.MiniMax._buildContext(params)
		if not okContext then
			return false, contextOrErr
		end
		local context = contextOrErr
		local mode = context.isStreamMp3 and "stream_mp3" or "non_stream"
		local payload, payloadStr = Providers.MiniMax._buildPayload(context, mode, params)
		context.payload = payload
		context.payloadStr = payloadStr

		if context.isStreamMp3 then
			return buildMiniMaxAsyncStreamTask(params, context)
		end
		return buildMiniMaxAsyncNonStreamTask(params, context)
	end

	App.Providers = Providers
end

---
--- 6c. Azure 试听模块 (App.Preview)
---
do
	local Preview = App.Preview
	local Audio = App.Audio
	local Utils = App.Utils

	Preview.PCM_OUTPUT_FORMAT = "riff-48khz-16bit-mono-pcm"
	Preview.activeSession = nil
	Preview.timer = nil
	Preview._sessionCounter = 0
	Preview.AzureLanguagePresets = {
		{
			id = "english",
			labels = buildLabelPair("英文", "English"),
			localePrefixes = { "en", "en-" },
			text = "Hello, it's a pleasure to provide voiceover services for you!",
		},
		{
			id = "chinese",
			labels = buildLabelPair("中文", "Chinese"),
			localePrefixes = { "zh", "zh-" },
			text = "您好，很高兴能为您提供配音服务！",
		},
	}

	local function previewLog(message)
		if type(logInfo) == "function" then
			logInfo("[AzurePreview] " .. tostring(message))
		end
	end

	local function localeMatchesPreviewPreset(localeId, preset)
		localeId = trim(localeId or "")
		if localeId == "" or type(preset) ~= "table" then
			return false
		end
		for _, exactLocale in ipairs(preset.locales or {}) do
			if localeId == exactLocale then
				return true
			end
		end
		for _, prefix in ipairs(preset.localePrefixes or {}) do
			prefix = trim(prefix or "")
			if prefix ~= "" and (localeId == prefix or localeId:sub(1, #prefix) == prefix) then
				return true
			end
		end
		return false
	end

	local function getAzurePreviewPreset(localeId)
		for _, preset in ipairs(Preview.AzureLanguagePresets or {}) do
			if localeMatchesPreviewPreset(localeId, preset) then
				return preset
			end
		end
		return nil
	end

	local function listAzurePreviewSupportedLanguages()
		local names = {}
		for _, preset in ipairs(Preview.AzureLanguagePresets or {}) do
			names[#names + 1] = App.UI.localizeLabel(preset.labels or buildLabelPair(preset.id, preset.id))
		end
		return table.concat(names, ", ")
	end

	local function getAzurePreviewUnsupportedMessage()
		local names = listAzurePreviewSupportedLanguages()
		return localizedFormat(
			"当前语言暂不支持试听，仅支持：%s。",
			"Preview is currently available only for: %s.",
			names ~= "" and names or localizedText("未配置", "not configured")
		)
	end

	local function buildAzurePreviewParams(params)
		params = params or {}
		local previewParams = {}
		for key, value in pairs(params) do
			previewParams[key] = value
		end
		local localeId =
			trim(previewParams.locale or previewParams.language or (App.State.azure and App.State.azure.language) or "")
		local preset = getAzurePreviewPreset(localeId)
		if not preset then
			return nil, getAzurePreviewUnsupportedMessage()
		end
		previewParams.text = preset.text or ""
		previewParams.outputFormat = Preview.PCM_OUTPUT_FORMAT
		previewParams.outputPath = nil
		previewParams.outputDir = nil
		previewParams.source = "preview_stream"
		return previewParams, preset
	end

	local function raisePreviewError(message)
		error(tostring(message or "preview_failed"), 0)
	end

	local function readTrimmedFile(path)
		if not path or path == "" then
			return ""
		end
		local body = Utils.readFile(path) or ""
		return body:gsub("%s+$", "")
	end

	local function notifyPreviewError(message)
		if not message or trim(message) == "" then
			return
		end
		if App.UI and App.UI.Events and App.UI.Events.notifyUser then
			App.UI.Events.notifyUser(message)
		else
			previewLog(message)
		end
	end

	local function removePreviewFiles(session)
		local paths = {
			session and session.ssmlPath,
			session and session.wavPath,
			session and session.stderrPath,
			session and session.infoPath,
		}
		for _, path in ipairs(paths) do
			if path and path ~= "" then
				Utils.removeFile(path)
			end
		end
	end

	local function escapeQuotes(str)
		return (str or ""):gsub('"', '\\"')
	end

	local function buildPreviewCurlCommand(session)
		return string.format(
			'curl %s -f -w "%%{http_code}" -X POST "https://%s.tts.speech.microsoft.com/cognitiveservices/v1" -H "Content-Type: application/ssml+xml" -H "X-Microsoft-OutputFormat: %s" -H "Ocp-Apim-Subscription-Key: %s" --data-binary @"%s" --output "%s" > "%s" 2> "%s"',
			buildStandardCurlFlags(session.tlsCompatFlag),
			escapeQuotes(session.region or ""),
			escapeQuotes(session.outputFormat or Preview.PCM_OUTPUT_FORMAT),
			escapeQuotes(session.apiKey or ""),
			escapeQuotes(session.ssmlPath or ""),
			escapeQuotes(session.wavPath or ""),
			escapeQuotes(session.infoPath or ""),
			escapeQuotes(session.stderrPath or "")
		)
	end

	local function removePreviewAttemptFiles(session)
		local paths = {
			session and session.wavPath,
			session and session.stderrPath,
			session and session.infoPath,
		}
		for _, path in ipairs(paths) do
			if path and path ~= "" then
				Utils.removeFile(path)
			end
		end
	end

	local function resetPreviewAttemptState(session)
		if session.sink and session.sink.abort then
			pcall(function()
				session.sink:abort()
			end)
		end
		session.sink = nil
		session.parser = Audio.WavStreamParser.new()
		session.readOffset = 0
		session.processDone = false
		session.exitCode = nil
		session.httpInfo = nil
		session.stderr = nil
		session.drainRequested = false
		session.state = "starting"
	end

	local function startPreviewProcess(session, tlsCompatFlag)
		if not session then
			return false, "preview_session_missing"
		end
		if session.processHandle and session.processHandle.close then
			pcall(function()
				session.processHandle:close()
			end)
		end
		session.processHandle = nil
		session.tlsCompatFlag = tlsCompatFlag
		removePreviewAttemptFiles(session)
		resetPreviewAttemptState(session)
		session.command = buildPreviewCurlCommand(session)
		local processHandle, launchErr = launchAsyncCommand(session.command)
		if not processHandle then
			return false,
				localizedText("启动 Azure 试听请求失败：", "Failed to start Azure preview request: ")
					.. tostring(launchErr or "unknown")
		end
		session.processHandle = processHandle
		return true
	end

	local function stopPreviewTimer()
		if Preview.timer and Preview.timer.Stop then
			pcall(function()
				Preview.timer:Stop()
			end)
		end
	end

	local function startPreviewTimer()
		if Preview.timer and Preview.timer.Start then
			pcall(function()
				Preview.timer:Start()
			end)
		end
	end

	function Preview.updateAzureButtonState()
		local button = App.UI and App.UI.items and App.UI.items.azurePlayButton
		if not button then
			return
		end
		local previewPreset = getAzurePreviewPreset(App.State.azure and App.State.azure.language)
		if Preview.activeSession then
			setTextSafe(button, localizedText("停止", "Stop"))
			setEnabledSafe(button, true)
		else
			setTextSafe(button, localizedText("试听", "Preview"))
			setEnabledSafe(button, previewPreset ~= nil)
		end
	end

	function Preview.isActive()
		return Preview.activeSession ~= nil
	end

	function Preview.ensureTimer()
		if Preview.timer then
			return Preview.timer
		end
		local core = App.Core or {}
		local ui = core.ui
		if not (ui and core.registerTimeoutHandler) then
			return nil, "preview_timer_unavailable"
		end
		Preview.timer = ui:Timer({
			ID = Audio.Const.TIMER_ID,
			Interval = Audio.Const.TIMER_INTERVAL_MS,
			SingleShot = false,
		})
		local ok, err = core.registerTimeoutHandler(Audio.Const.TIMER_ID, function(ev)
			return Preview.onTimeout(ev)
		end)
		if not ok then
			Preview.timer = nil
			return nil, err or "preview_timer_bind_failed"
		end
		return Preview.timer
	end

	local function finalizeSession(session, options)
		options = options or {}
		if not session or session.finalized then
			return
		end
		session.finalized = true
		stopPreviewTimer()
		if session.processHandle then
			if options.terminateProcess and session.processHandle.terminate then
				pcall(function()
					session.processHandle:terminate(15)
				end)
			end
			if session.processHandle.close then
				pcall(function()
					session.processHandle:close()
				end)
			end
			session.processHandle = nil
		end
		if session.sink and session.sink.abort then
			pcall(function()
				session.sink:abort()
			end)
		end
		session.sink = nil
		removePreviewFiles(session)
		if Preview.activeSession == session then
			Preview.activeSession = nil
		end
		Preview.updateAzureButtonState()
		if options.notifyMessage then
			notifyPreviewError(options.notifyMessage)
		end
	end

	local function failSession(session, message)
		session.state = "failed"
		session.errorMessage = trim(message or "") ~= "" and tostring(message)
			or localizedText("试听失败。", "Preview failed.")
		previewLog("failed: " .. tostring(session.errorMessage))
		finalizeSession(session, {
			terminateProcess = true,
			notifyMessage = session.errorMessage,
		})
	end

	local function completeSession(session)
		session.state = "stopped"
		previewLog("completed")
		finalizeSession(session, {
			terminateProcess = false,
		})
	end

	local function buildPreviewArtifacts(params)
		local credentials, credentialErr = App.Providers.Azure.resolveCredentials(params)
		if not credentials then
			return nil, credentialErr
		end

		local ssmlPath, ssmlErr = Utils.makeTempPath("ssml")
		if not ssmlPath then
			return nil, "ssml_tmp_failed:" .. tostring(ssmlErr)
		end
		local wavPath, wavErr = Utils.makeTempPath("wav.part")
		if not wavPath then
			Utils.removeFile(ssmlPath)
			return nil, "wav_tmp_failed:" .. tostring(wavErr)
		end
		local stderrPath, stderrErr = Utils.makeTempPath("stderr")
		if not stderrPath then
			Utils.removeFile(ssmlPath)
			Utils.removeFile(wavPath)
			return nil, "stderr_tmp_failed:" .. tostring(stderrErr)
		end
		local infoPath, infoErr = Utils.makeTempPath("httpinfo")
		if not infoPath then
			Utils.removeFile(ssmlPath)
			Utils.removeFile(wavPath)
			Utils.removeFile(stderrPath)
			return nil, "info_tmp_failed:" .. tostring(infoErr)
		end

		local wrote, writeErr = Utils.writeFile(ssmlPath, App.Azure.buildSsml(params))
		if not wrote then
			Utils.removeFile(ssmlPath)
			Utils.removeFile(wavPath)
			Utils.removeFile(stderrPath)
			Utils.removeFile(infoPath)
			return nil,
				localizedText("写入试听 SSML 失败：", "Failed to write preview SSML: ") .. tostring(
					writeErr or "unknown"
				)
		end

		Preview._sessionCounter = Preview._sessionCounter + 1
		local session = {
			id = Preview._sessionCounter,
			platform = IS_WINDOWS and "windows" or (IS_MACOS and "macos" or "other"),
			timer = Preview.timer,
			ssmlPath = ssmlPath,
			wavPath = wavPath,
			stderrPath = stderrPath,
			infoPath = infoPath,
			readOffset = 0,
			parser = Audio.WavStreamParser.new(),
			sink = nil,
			startedAt = os.time(),
			state = "starting",
			outputFormat = Preview.PCM_OUTPUT_FORMAT,
			apiKey = credentials.apiKey,
			region = credentials.region,
			params = params,
		}
		if type(runShellCommandAsync) ~= "function" then
			removePreviewFiles(session)
			return nil,
				localizedText(
					"当前环境不支持异步网络请求，无法直接流式试听。",
					"Async shell execution is unavailable in this environment, so direct streaming preview cannot start."
					)
		end
		local okStart, startErr = startPreviewProcess(session)
		if not okStart then
			removePreviewFiles(session)
			return nil, startErr
		end
		return session
	end

	function Preview.stopActivePreview(reason)
		local session = Preview.activeSession
		if not session then
			Preview.updateAzureButtonState()
			return
		end
		session.state = "stopped"
		session.stopReason = reason or "stopped"
		previewLog("stopped: " .. tostring(session.stopReason))
		finalizeSession(session, {
			terminateProcess = true,
		})
	end

	local function ensureSinkReady(session)
		if session.sink or not session.parser:isReady() then
			return true
		end
		local sink, sinkErr = Audio.Sink.create(session.parser:getFormatInfo())
		if not sink then
			return false, sinkErr
		end
		session.sink = sink
		local ok, err = session.sink:start()
		if not ok then
			return false, err
		end
		session.state = "buffering"
		return true
	end

	local function pumpPreviewAudio(session)
		if Utils.fileExists(session.wavPath) then
			local payload, readErr, nextOffset = Audio.readGrowingFileChunk(session.wavPath, session.readOffset)
			if payload == nil then
				return false,
					localizedText("读取试听音频失败：", "Failed to read preview audio: ") .. tostring(
						readErr or "unknown"
					)
			end
			session.readOffset = nextOffset or session.readOffset
			if payload ~= "" then
				local ok, err = session.parser:push(payload)
				if not ok then
					return false, err
				end
			end
		end

		local sinkOk, sinkErr = ensureSinkReady(session)
		if not sinkOk then
			return false, sinkErr
		end

		if session.sink then
			while true do
				local chunk = session.parser:popPcmChunk(Audio.Const.CHUNK_BYTES)
				if not chunk then
					break
				end
				local ok, err = session.sink:write(chunk)
				if ok then
					session.state = "playing"
				elseif err == "buffer_full" then
					session.parser:pushBackPcm(chunk)
					break
				else
					return false, err or "preview_sink_write_failed"
				end
			end
		end

		return true
	end

	function Preview.onTimeout(_)
		local session = Preview.activeSession
		if not session then
			stopPreviewTimer()
			return false
		end

		local ok, err = pcall(function()
			local pumped, pumpErr = pumpPreviewAudio(session)
			if not pumped then
				raisePreviewError(pumpErr)
			end

				local finished, exitCode = session.processHandle:poll(0)
				if finished and not session.processDone then
					session.processDone = true
					session.exitCode = exitCode or 1
					session.httpInfo = readTrimmedFile(session.infoPath)
					session.stderr = readTrimmedFile(session.stderrPath)
					if session.exitCode ~= 0 then
						local detail = session.stderr ~= "" and session.stderr or session.httpInfo
						local retried, retryErr = tryStartWindowsCurlCompatRetry(
							session.tlsCompatFlag,
							detail,
							"azure_preview",
							function(nextFlag)
								return startPreviewProcess(session, nextFlag)
							end
						)
						if retried == true then
							return
						elseif retried == nil then
							raisePreviewError(
								localizedText("试听失败：", "Preview failed: ")
									.. tostring(retryErr or detail or session.exitCode)
							)
						end
						raisePreviewError(
							localizedText("试听失败：", "Preview failed: ")
								.. tostring(detail ~= "" and detail or session.exitCode)
					)
				end
				if not session.parser:isReady() then
					local fileSize = Utils.getFileSize(session.wavPath) or 0
					if fileSize <= 0 then
						raisePreviewError(
							localizedText("试听音频生成失败。", "Preview audio was not created.")
						)
					end
					raisePreviewError(localizedText("试听音频格式无效。", "Preview audio format is invalid."))
				end
			end

			if session.processDone then
				local queuedBytes = session.sink and session.sink:getQueuedBytes() or 0
				local bufferedBytes = session.parser:getBufferedBytes()
				if session.sink and not session.drainRequested and bufferedBytes <= 0 then
					session.drainRequested = true
					session.state = "draining"
					session.sink:drainAndStop()
					queuedBytes = session.sink:getQueuedBytes()
				end
				if bufferedBytes <= 0 and queuedBytes <= 0 then
					completeSession(session)
				end
			end
		end)

		if not ok then
			failSession(session, tostring(err))
		end
		return true
	end

	function Preview.startAzurePreview(params)
		local previewParams, previewErr = buildAzurePreviewParams(params)
		if not previewParams then
			return false, previewErr
		end
		local okConfig, configErr = App.Controller.validateProviderConfig("azure", previewParams)
		if not okConfig then
			return false, configErr
		end

		local timer, timerErr = Preview.ensureTimer()
		if not timer then
			return false,
				localizedText(
					"当前环境不支持 Azure 直接流式试听：",
					"Azure direct streaming preview is unavailable in this environment: "
				) .. tostring(timerErr or "timer_unavailable")
		end

		Preview.stopActivePreview("replace")

		local session, buildErr = buildPreviewArtifacts(previewParams)
		if not session then
			return false, buildErr
		end

		Preview.activeSession = session
		Preview.updateAzureButtonState()
		startPreviewTimer()
		previewLog("started")
		return true
	end

	Preview.getAzurePreviewPreset = getAzurePreviewPreset
	Preview.getAzurePreviewUnsupportedMessage = getAzurePreviewUnsupportedMessage
	Preview.refreshUI = Preview.updateAzureButtonState
end

local function timecodeToFrames(timecode, frameRate)
	if not timecode or timecode == "" then
		return 0
	end
	frameRate = tonumber(frameRate) or 0
	if frameRate <= 0 then
		return 0
	end

	local hours, minutes, seconds, separator, frames = timecode:match("^(%d%d):(%d%d):(%d%d)([:;])(%d%d%d?)$")
	if not hours then
		return 0
	end

	hours = tonumber(hours)
	minutes = tonumber(minutes)
	seconds = tonumber(seconds)
	frames = tonumber(frames)

	local isDropFrame = separator == ";"
	local function isRate(target)
		return math.abs(frameRate - target) < 0.01
	end
	if isDropFrame then
		local nominalFrameRate
		if isRate(23.976) or isRate(29.97) or isRate(59.94) or isRate(119.88) then
			nominalFrameRate = math.floor(frameRate * 1000 / 1001 + 0.5)
		else
			nominalFrameRate = math.floor(frameRate + 0.5)
		end
		local dropFrames = math.floor(nominalFrameRate / 15 + 0.5)
		local totalMinutes = hours * 60 + minutes
		local totalDroppedFrames = dropFrames * (totalMinutes - math.floor(totalMinutes / 10))
		local frameCount = ((hours * 3600) + (minutes * 60) + seconds) * nominalFrameRate + frames
		return frameCount - totalDroppedFrames
	else
		local nominalFrameRate
		if isRate(23.976) or isRate(29.97) or isRate(47.952) or isRate(59.94) or isRate(95.904) or isRate(119.88) then
			nominalFrameRate = math.floor(frameRate * 1000 / 1001 + 0.5)
		else
			nominalFrameRate = frameRate
		end
		return ((hours * 3600) + (minutes * 60) + seconds) * nominalFrameRate + frames
	end
end

---
--- 8a. 时间线 I/O 模块 (App.TimelineIO)
---
do
	local TimelineIO = App.TimelineIO or {}

	function TimelineIO.getFirstEmptyTrack(timeline, startFrame, endFrame, mediaType)
		local trackIndex = 1
		while true do
			local items = timeline:GetItemListInTrack(mediaType, trackIndex)
			if not items or #items == 0 then
				return trackIndex
			end

			local isEmpty = true
			for _, item in ipairs(items) do
				local itemStart = item:GetStart()
				local itemEnd = item:GetEnd()
				if itemStart and itemEnd and itemStart <= endFrame and startFrame <= itemEnd then
					isEmpty = false
					break
				end
			end

			if isEmpty then
				return trackIndex
			end

			trackIndex = trackIndex + 1
		end
	end
	function TimelineIO.insertAudio(path, startOffsetSamples, durationSamples, recordFrame)
		if not path or path == "" then
			return false, "Audio path is empty"
		end

		logInfo(string.format("TimelineIO.insertAudio start. path=%s", tostring(path)))
		local resolveInstance, project, timeline, err = App.ResolveCtx.get()
		if err then
			logInfo(string.format("TimelineIO.insertAudio aborted: %s", tostring(err)))
			return false, err
		end
		if not project or not timeline then
			logInfo("TimelineIO.insertAudio aborted: project or timeline unavailable.")
			return false, "Project or timeline unavailable"
		end

		local mediaPool = project:GetMediaPool()
		if not mediaPool then
			logInfo("TimelineIO.insertAudio aborted: media pool unavailable.")
			return false, "Media pool unavailable"
		end

		local rootFolder = mediaPool:GetRootFolder()
		if not rootFolder then
			logInfo("TimelineIO.insertAudio aborted: root folder unavailable.")
			return false, "Root folder unavailable"
		end

		local ttsFolder = nil
		local subFolders = rootFolder:GetSubFolderList() or {}
		for _, folder in ipairs(subFolders) do
			if folder:GetName() == "TTS" then
				ttsFolder = folder
				break
			end
		end
		if not ttsFolder then
			ttsFolder = mediaPool:AddSubFolder(rootFolder, "TTS")
		end
		if not ttsFolder then
			logInfo("TimelineIO.insertAudio aborted: failed to locate/create TTS folder.")
			return false, "Failed to locate or create TTS folder"
		end

		mediaPool:SetCurrentFolder(ttsFolder)
		local importedItems = mediaPool:ImportMedia({ path })
		if not importedItems or not importedItems[1] then
			logInfo(string.format("TimelineIO.insertAudio aborted: failed to import media %s", tostring(path)))
			return false, string.format("Failed to import media: %s", tostring(path))
		end

		local clip = importedItems[1]
		logInfo(string.format("TimelineIO.insertAudio imported clip '%s'", tostring(clip:GetName() or "?")))

		local frameRateSetting
		if timeline.GetSetting then
			frameRateSetting = timeline:GetSetting("timelineFrameRate")
		end
		if not frameRateSetting and project.GetSetting then
			frameRateSetting = project:GetSetting("timelineFrameRate")
		end
		local frameRate = tonumber(frameRateSetting) or 24

		local startFrame
		if recordFrame ~= nil then
			startFrame = math.floor(recordFrame + 0.5)
		end
		if not startFrame then
			local currentTimecode = timeline:GetCurrentTimecode()
			if not currentTimecode or currentTimecode == "" then
				if timeline.GetStartTimecode then
					currentTimecode = timeline:GetStartTimecode()
				else
					currentTimecode = "00:00:00:00"
				end
			end
			startFrame = timecodeToFrames(currentTimecode, frameRate)
		end
		if (not startFrame or startFrame < 0) and timeline.GetCurrentFrame then
			local currentFrame = timeline:GetCurrentFrame()
			if type(currentFrame) == "number" and currentFrame >= 0 then
				startFrame = math.floor(currentFrame + 0.5)
			end
		end
		startFrame = startFrame or 0
		local clipSampleRate = tonumber(clip:GetClipProperty("SampleRate") or clip:GetClipProperty("AudioSampleRate"))
		if clipSampleRate and clipSampleRate > 0 and startOffsetSamples and startOffsetSamples > 0 then
			local offsetFrames = math.floor((startOffsetSamples / clipSampleRate) * frameRate + 0.5)
			startFrame = startFrame + offsetFrames
		end

		local durationTimecode = clip:GetClipProperty("Duration")
		local clipDurationFrames = timecodeToFrames(durationTimecode, frameRate)
		if clipDurationFrames <= 0 and durationSamples and clipSampleRate and clipSampleRate > 0 then
			clipDurationFrames = math.floor((durationSamples / clipSampleRate) * frameRate + 0.5)
		end
		if clipDurationFrames <= 0 then
			clipDurationFrames = 1
		end

		local endFrame = startFrame + clipDurationFrames - 1
		local trackIndex = TimelineIO.getFirstEmptyTrack(timeline, startFrame, endFrame, "audio")

		local audioTrackCount = timeline:GetTrackCount("audio") or 0
		while audioTrackCount < trackIndex do
			timeline:AddTrack("audio")
			audioTrackCount = audioTrackCount + 1
		end

		local clipInfo = {
			mediaPoolItem = clip,
			mediaType = 2,
			startFrame = 0,
			--endFrame = clipDurationFrames - 1,
			trackIndex = trackIndex,
			recordFrame = startFrame,
			stereoEye = "both",
		}

		local appended, appendErr = mediaPool:AppendToTimeline({ clipInfo })
		if appended == nil or appended == false then
			logInfo(
				string.format("AppendToTimeline failed for '%s': %s", tostring(clip:GetName()), tostring(appendErr))
			)
			return false, appendErr or "Failed to append clip to timeline"
		end

		logInfo(
			string.format(
				"Appended audio clip '%s' to timeline at frame %d on audio track %d",
				tostring(clip:GetName()),
				startFrame,
				trackIndex
			)
		)
		return true
	end

	App.TimelineIO = TimelineIO
end

do
	local Status = App.Status

	local function coerceStatusPair(value)
		if type(value) == "table" then
			return value[1], value[2]
		end
		return nil, nil
	end

	function Status.resolvePair(key, fallback)
		local entries = App.Config.Status or {}
		local entry = key and entries[key] or nil
		local enText, zhText = coerceStatusPair(entry)
		if enText ~= nil or zhText ~= nil then
			return enText or "", zhText or ""
		end
		if type(fallback) == "table" then
			local fallbackEn, fallbackZh = coerceStatusPair(fallback)
			if fallbackEn ~= nil or fallbackZh ~= nil then
				return fallbackEn or "", fallbackZh or ""
			end
		elseif type(fallback) == "string" then
			local fallbackEntry = entries[fallback]
			local fallbackEn, fallbackZh = coerceStatusPair(fallbackEntry)
			if fallbackEn ~= nil or fallbackZh ~= nil then
				return fallbackEn or "", fallbackZh or ""
			end
			return fallback, fallback
		end
		if type(key) == "string" then
			return key, key
		end
		return "", ""
	end

	function Status.resolve(key, fallback)
		local enText, zhText = Status.resolvePair(key, fallback)
		if (App.State.locale or "en") == "cn" then
			return zhText ~= "" and zhText or enText or ""
		end
		return enText ~= "" and enText or zhText or ""
	end

	function Status.apply(text)
		local value = text == nil and "" or tostring(text)
		local msgItems = App.UI.msgboxItems
		if value == "" then
			if msgItems then
				setTextSafe(msgItems.InfoLabel, "")
			end
			if msgbox and msgbox.Hide then
				msgbox:Hide()
			end
			return
		end
		if msgItems then
			setTextSafe(msgItems.InfoLabel, value)
		end
		if msgbox and msgbox.Show then
			msgbox:Show()
		else
			logInfo(value)
		end
	end

	function Status.show(key, fallback)
		Status.apply(Status.resolve(key, fallback))
	end

	function Status.showError(code, defaultKey)
		local fallbackKey = defaultKey or "error_1000"
		local key = code and ("error_" .. tostring(code)) or fallbackKey
		Status.show(key, fallbackKey)
	end
end

