do
	local SynthesisAsync = App.SynthesisAsync or {}
	local TIMER_ID = "SynthesisAsyncTimer"
	local TIMER_INTERVAL_MS = 250
	local BUSY_CONTROL_IDS = {
		"azureFromTxtButton",
		"azureFromSubButton",
		"minimaxFromTxtButton",
		"minimaxFromSubButton",
		"OpenAIFromTxtButton",
		"OpenAIFromSubButton",
		"azureGetSubButton",
		"minimaxGetSubButton",
		"OpenAIGetSubButton",
		"azureResetButton",
		"minimaxResetButton",
		"OpenAIResetButton",
	}

	local function captureBusyState()
		local snapshot = {}
		local items = App.UI.items or {}
		for _, controlId in ipairs(BUSY_CONTROL_IDS) do
			local control = items[controlId]
			if control and control.Enabled ~= nil then
				snapshot[controlId] = control.Enabled and true or false
			end
		end
		return snapshot
	end

	local function applyBusyState(isBusy, snapshot)
		local items = App.UI.items or {}
		for _, controlId in ipairs(BUSY_CONTROL_IDS) do
			local control = items[controlId]
			if control then
				if isBusy then
					setEnabledSafe(control, false)
				else
					local enabled = snapshot and snapshot[controlId]
					if enabled == nil then
						enabled = true
					end
					setEnabledSafe(control, enabled)
				end
			end
		end
	end

	local function startTimer()
		if SynthesisAsync.timer and SynthesisAsync.timer.Start then
			SynthesisAsync.timer:Start()
		end
	end

	local function stopTimer()
		if SynthesisAsync.timer and SynthesisAsync.timer.Stop then
			pcall(function()
				SynthesisAsync.timer:Stop()
			end)
		end
	end

	function SynthesisAsync.isActive()
		return SynthesisAsync.activeTask ~= nil
	end

	function SynthesisAsync.ensureTimer()
		if SynthesisAsync.timer then
			return SynthesisAsync.timer
		end
		local core = App.Core or {}
		local ui = core.ui
		if not (ui and core.registerTimeoutHandler) then
			return nil, "synthesis_timer_unavailable"
		end
		SynthesisAsync.timer = ui:Timer({
			ID = TIMER_ID,
			Interval = TIMER_INTERVAL_MS,
			SingleShot = false,
		})
		local ok, err = core.registerTimeoutHandler(TIMER_ID, function(ev)
			return SynthesisAsync.poll(ev)
		end)
		if not ok then
			SynthesisAsync.timer = nil
			return nil, err or "synthesis_timer_bind_failed"
		end
		return SynthesisAsync.timer
	end

	function SynthesisAsync.finish(result, options)
		options = options or {}
		local task = SynthesisAsync.activeTask
		if not task or task.finalized then
			return
		end
		task.finalized = true
		stopTimer()
		if task.cleanup then
			pcall(function()
				task:cleanup({
					terminateProcess = options.terminateProcess == true,
					success = result and result.ok == true,
					reason = options.reason,
				})
			end)
		end
		SynthesisAsync.activeTask = nil
		applyBusyState(false, task.uiSnapshot)
		if not options.suppressCallback and task.onComplete then
			pcall(function()
				task.onComplete(result or { ok = false, error = localizedText("未知错误", "Unknown error") })
			end)
		end
	end

	function SynthesisAsync.cancel(reason)
		if not SynthesisAsync.activeTask then
			return
		end
		SynthesisAsync.finish({ ok = false, cancelled = true }, {
			reason = reason or "cancelled",
			terminateProcess = true,
			suppressCallback = (reason == "window_close"),
		})
	end

	function SynthesisAsync.poll(_)
		local task = SynthesisAsync.activeTask
		if not task then
			stopTimer()
			return false
		end

		if task.deadlineAt and os.time() > task.deadlineAt then
			SynthesisAsync.finish(
				{ ok = false, error = localizedText("语音生成超时。", "Speech generation timed out.") },
				{ reason = "timeout", terminateProcess = true }
			)
			return true
		end

		local ok, done, result = pcall(function()
			return task:poll()
		end)
		if not ok then
			SynthesisAsync.finish(
				{ ok = false, error = tostring(done) },
				{ reason = "poll_error", terminateProcess = true }
			)
			return true
		end
		if done then
			SynthesisAsync.finish(result, {
				reason = (result and result.ok) and "success" or "failed",
				terminateProcess = false,
			})
		end
		return true
	end

	function SynthesisAsync.start(task)
		if SynthesisAsync.activeTask then
			return false,
				localizedText(
					"已有生成任务正在进行，请等待当前任务完成。",
					"A synthesis task is already running. Please wait for it to finish."
				)
		end
		local timer, timerErr = SynthesisAsync.ensureTimer()
		if not timer then
			return false,
				localizedText(
					"当前环境不支持异步合成：",
					"Async synthesis is unavailable in this environment: "
				) .. tostring(timerErr or "timer_unavailable")
		end
		if type(task) ~= "table" or type(task.start) ~= "function" or type(task.poll) ~= "function" then
			return false, localizedText("异步任务配置无效。", "Async task configuration is invalid.")
		end

		task.uiSnapshot = captureBusyState()
		local started, startErr = task:start()
		if not started then
			if task.cleanup then
				pcall(function()
					task:cleanup({ terminateProcess = true, reason = "start_failed" })
				end)
			end
			return false,
				tostring(startErr or localizedText("启动异步任务失败。", "Failed to start async task."))
		end

		task.finalized = false
		task.deadlineAt = os.time() + math.ceil(tonumber(task.timeoutSeconds) or 120) + 20
		SynthesisAsync.activeTask = task
		applyBusyState(true, task.uiSnapshot)
		startTimer()
		return true
	end

	App.SynthesisAsync = SynthesisAsync
end

App.MiniMaxClone = {}
do
	local Clone = App.MiniMaxClone
	Clone.markerKey = "clone"
	Clone.previewUrls = {
		intl = "https://www.minimax.io/audio/voices",
		cn = "https://www.minimaxi.com/audio/voices",
	}
	Clone.tempDir = App.Utils.joinPath(App.Paths.scriptDir, "clone_cache")

	Clone.showStatus = App.Status.show

	local function minimaxItems()
		return App.UI.minimaxItems or {}
	end

	local function cloneItems()
		return App.UI.minimaxCloneItems or {}
	end

	local function getVoiceFilePath()
		if App.Config.MiniMax and App.Config.MiniMax.voiceFilePath then
			return App.Config.MiniMax.voiceFilePath
		end
		return App.Paths.inVoices("minimax_voices.json")
	end

	local function ensureTempDir()
		App.Utils.ensureDir(Clone.tempDir)
		return Clone.tempDir
	end

	local function addLanguageIfMissing(language)
		local cfg = App.Config.MiniMax
		cfg.cloneLangCounts = cfg.cloneLangCounts or {}
		cfg.cloneMap = cfg.cloneMap or {}
		if not cfg.voices[language] then
			cfg.voices[language] = {}
		end
		local exists = false
		for _, entry in ipairs(cfg.languages or {}) do
			if entry.id == language then
				exists = true
				break
			end
		end
		if not exists then
			table.insert(cfg.languages, { id = language, labels = buildLabelPair(language, language) })
		end
		if cfg.cloneLangCounts[language] == nil then
			cfg.cloneLangCounts[language] = 0
		end
	end

	local function insertCloneIntoCache(voiceName, voiceId, language)
		local cfg = App.Config.MiniMax
		language = language or App.State.minimax.language or "中文（普通话）"
		addLanguageIfMissing(language)
		local entry = {
			id = voiceId,
			labels = buildLabelPair(voiceName or voiceId, voiceName or voiceId),
			isClone = true,
		}
		table.insert(cfg.voices[language], 1, entry)
		cfg.cloneLangCounts[language] = (cfg.cloneLangCounts[language] or 0) + 1
		cfg.cloneMap[voiceId] = language
	end

	local function removeCloneFromCache(voiceId)
		local cfg = App.Config.MiniMax
		cfg.cloneMap = cfg.cloneMap or {}
		cfg.cloneLangCounts = cfg.cloneLangCounts or {}
		local language = cfg.cloneMap[voiceId]
		if not language then
			for lang, list in pairs(cfg.voices or {}) do
				for idx, entry in ipairs(list) do
					if entry.isClone and entry.id == voiceId then
						table.remove(list, idx)
						cfg.cloneLangCounts[lang] = math.max((cfg.cloneLangCounts[lang] or 1) - 1, 0)
						cfg.cloneMap[voiceId] = nil
						return true
					end
				end
			end
			return false
		end
		local list = cfg.voices[language]
		if not list then
			return false
		end
		for idx, entry in ipairs(list) do
			if entry.isClone and entry.id == voiceId then
				table.remove(list, idx)
				cfg.cloneLangCounts[language] = math.max((cfg.cloneLangCounts[language] or 1) - 1, 0)
				cfg.cloneMap[voiceId] = nil
				return true
			end
		end
		return false
	end

	local function syncRawVoiceData(data)
		local cfg = App.Config.MiniMax
		if type(cfg) ~= "table" then
			return
		end
		if type(cfg.rawVoicesData) ~= "table" then
			cfg.rawVoicesData = {}
		end
		cfg.rawVoicesData.minimax_clone_voices = data.minimax_clone_voices or {}
		cfg.rawVoicesData.minimax_clone_voices_cn = nil
		cfg.rawVoicesData.minimax_clone_voices_en = nil
	end

	function Clone.refreshVoices(selectVoiceId)
		if selectVoiceId then
			App.State.minimax.voice = selectVoiceId
		end
		App.UI.refreshMiniMaxVoices({
			selectVoiceId = selectVoiceId,
		})
	end

	function Clone.loadVoiceData()
		local path = getVoiceFilePath()
		local content, err = App.Utils.readFile(path)
		if not content then
			return nil, err or "read_failed"
		end
		local data, decodeErr = App.Utils.decodeJsonWithOrder(content)
		if not data then
			return nil, decodeErr
		end
		if normalizeCloneVoiceStorage(data) then
			local ok, writeErr = Clone.saveVoiceData(data)
			if not ok then
				return nil, writeErr
			end
		end
		syncRawVoiceData(data)
		return data, path
	end

	function Clone.saveVoiceData(data)
		local path = getVoiceFilePath()
		return App.Utils.writeJsonOrdered(path, data, { indent = "  " })
	end

	function Clone.addCloneVoice(voiceName, voiceId, language)
		local data, err = Clone.loadVoiceData()
		if not data then
			return false, err
		end
		if normalizeCloneVoiceStorage(data) then
			local normalizedOk, normalizedErr = Clone.saveVoiceData(data)
			if not normalizedOk then
				return false, normalizedErr
			end
		end
		if type(data.minimax_clone_voices) ~= "table" then
			data.minimax_clone_voices = {}
		end
		local normalizedName = voiceName and voiceName:lower()
		for _, entry in ipairs(data.minimax_clone_voices) do
			if
				(voiceId ~= "" and entry.voice_id == voiceId)
				or (normalizedName and entry.voice_name and entry.voice_name:lower() == normalizedName)
			then
				return false, App.Status.resolve("error_2039")
			end
		end
		table.insert(data.minimax_clone_voices, 1, {
			voice_id = voiceId,
			voice_name = voiceName,
			description = {},
			created_time = os.date("%Y-%m-%d"),
			language = language,
		})
		local ok, writeErr = Clone.saveVoiceData(data)
		if not ok then
			return false, writeErr
		end
		syncRawVoiceData(data)
		insertCloneIntoCache(voiceName, voiceId, language)
		return true
	end

	function Clone.deleteCloneVoice(entry)
		if not entry or not entry.isClone then
			return false, App.Status.resolve("delete_clone_error")
		end
		local data, err = Clone.loadVoiceData()
		if not data then
			return false, err
		end
		if normalizeCloneVoiceStorage(data) then
			local normalizedOk, normalizedErr = Clone.saveVoiceData(data)
			if not normalizedOk then
				return false, normalizedErr
			end
		end
		if type(data.minimax_clone_voices) ~= "table" then
			return false, App.Status.resolve("delete_clone_error")
		end
		local filtered = {}
		local removed = false
		for _, v in ipairs(data.minimax_clone_voices) do
			if v.voice_id == entry.id or (entry.labels and entry.labels.en and v.voice_name == entry.labels.en) then
				removed = true
			else
				table.insert(filtered, v)
			end
		end
		if not removed then
			return false, App.Status.resolve("delete_clone_error")
		end
		data.minimax_clone_voices = filtered
		local ok, writeErr = Clone.saveVoiceData(data)
		if not ok then
			return false, writeErr
		end
		syncRawVoiceData(data)
		removeCloneFromCache(entry.id)
		return true
	end

	local function removeCloneMarker()
		local _, _, timeline = App.ResolveCtx.get()
		if not timeline then
			return
		end
		local deleted = false
		if timeline.DeleteMarkerByCustomData then
			pcall(function()
				timeline:DeleteMarkerByCustomData(Clone.markerKey)
			end)
		end
		if timeline.DeleteMarkerAtFrame then
			local markers = timeline.GetMarkers and timeline:GetMarkers() or nil
			if type(markers) == "table" then
				for frame, markerInfo in pairs(markers) do
					local customData = type(markerInfo) == "table"
							and (markerInfo.customData or markerInfo.CustomData or markerInfo.customdata)
						or nil
					if customData == Clone.markerKey then
						pcall(function()
							timeline:DeleteMarkerAtFrame(frame)
						end)
						deleted = true
					end
				end
			end
			if not deleted and Clone.markerFrame ~= nil then
				pcall(function()
					timeline:DeleteMarkerAtFrame(Clone.markerFrame)
				end)
			end
		end
		Clone.markerFrame = nil
	end

	local function addCloneMarker()
		local _, project, timeline, err = App.ResolveCtx.get()
		if err or not project or not timeline then
			App.Status.show("create_timeline")
			return false
		end
		removeCloneMarker()
		local name = (App.State.locale == "cn") and "克隆标记" or "Clone Marker"
		local note = (App.State.locale == "cn")
				and "拖拽Mark点范围确定克隆音频的范围，大于10秒，小于5分钟"
			or "Drag the marker points to mark audio range (10 seconds to 5 minutes)."
		local frameRate = tonumber(project:GetSetting("timelineFrameRate"))
			or tonumber(timeline:GetSetting("timelineFrameRate"))
			or 24
		local currentFrame = nil
		if timeline.GetCurrentFrame then
			local value = timeline:GetCurrentFrame()
			if type(value) == "number" and value >= 0 then
				currentFrame = math.floor(value + 0.5)
			end
		end
		if (not currentFrame or currentFrame < 0) and timeline.GetCurrentTimecode then
			local timecode = timeline:GetCurrentTimecode()
			if timecode and timecode ~= "" then
				local frame = timecodeToFrames(timecode, frameRate)
				if frame and frame >= 0 then
					currentFrame = frame
				end
			end
		end
		local timelineStart = tonumber(timeline:GetStartFrame() or 0) or 0
		local markerFrame = (currentFrame ~= nil and currentFrame or timelineStart) - timelineStart
		if markerFrame < 0 then
			markerFrame = 0
		end
		local defaultDurationFrames = math.max(1, math.floor((frameRate * 10) + 0.5))
		local ok, result = pcall(function()
			return timeline:AddMarker(markerFrame, "Red", name, note, defaultDurationFrames, Clone.markerKey)
		end)
		if not ok or not result then
			logInfo("Failed to add clone marker: " .. tostring(result))
			return false
		end
		Clone.markerFrame = markerFrame
		return true
	end

	function Clone.toggleMode(isAddOnly)
		local items = cloneItems()
		if not items then
			return
		end
		setEnabledSafe(items.minimaxNeedNoiseReduction, not isAddOnly)
		setEnabledSafe(items.minimaxNeedVolumeNormalization, not isAddOnly)
		setEnabledSafe(items.minimaxClonePreviewText, not isAddOnly)
		local addText = (App.State.locale == "cn") and "添加" or "Add"
		local cloneText = (App.State.locale == "cn") and "克隆" or "Clone"
		setTextSafe(items.MiniMaxCloneConfirm, isAddOnly and addText or cloneText)
		if isAddOnly then
			removeCloneMarker()
		else
			addCloneMarker()
		end
	end

	function Clone.onShowWindow()
		local items = cloneItems()
		if not items then
			return
		end
		ensureTempDir()
		setTextSafe(items.minimaxCloneFileID, "")
		setCheckedSafe(items.minimaxOnlyAddID, true)
		Clone.toggleMode(true)
		minimaxCloneWin:Show()
		win:Hide()
	end

	function Clone.onCloseWindow()
		removeCloneMarker()
		local items = cloneItems()
		if items then
			setTextSafe(items.minimaxCloneFileID, "")
		end
		win:Show()
		minimaxCloneWin:Hide()
	end

	local function loadAudioPreset(project)
		local ok = false
		local list = project:GetRenderPresetList() or {}
		for _, preset in ipairs(list) do
			local name = preset
			if type(preset) == "table" then
				name = preset.PresetName or preset.Name
			end
			if type(name) == "string" and name:lower():find("audio only", 1, true) then
				ok = project:LoadRenderPreset(name)
				if ok then
					break
				end
			end
		end
		if not ok then
			ok = project:LoadRenderPreset("Audio Only")
		end
		return ok
	end

	function Clone.renderAudioByMarker()
		local resolveInstance, project, timeline, err = App.ResolveCtx.get()
		if err or not project or not timeline then
			return nil, err or "timeline_unavailable"
		end
		local ok = pcall(function()
			project:SetCurrentRenderMode(1)
		end)
		if not ok then
			return nil, "render_mode_failed"
		end
		if not loadAudioPreset(project) then
			logInfo("Failed to load audio render preset.")
		end
		local markers = timeline:GetMarkers()
		if not markers or not next(markers) then
			App.Status.show("insert_mark")
			return nil, "no_markers"
		end
		local firstFrame = nil
		local markerInfo = nil
		for frame, info in pairs(markers) do
			local customData = type(info) == "table" and (info.customData or info.CustomData or info.customdata) or nil
			if customData == Clone.markerKey then
				firstFrame = frame
				markerInfo = info
				break
			end
		end
		if (firstFrame == nil or markerInfo == nil) and Clone.markerFrame ~= nil then
			firstFrame = Clone.markerFrame
			markerInfo = markers[firstFrame]
		end
		if firstFrame == nil or not markerInfo or not markerInfo.duration then
			App.Status.show("insert_mark")
			return nil, "invalid_marker"
		end
		local frameRate = tonumber(project:GetSetting("timelineFrameRate"))
			or tonumber(timeline:GetSetting("timelineFrameRate"))
			or 24
		local durationFrames = tonumber(markerInfo.duration) or 0
		local durationSeconds = durationFrames / frameRate
		if durationSeconds < 10 or durationSeconds > 300 then
			App.Status.show("duration_seconds")
			return nil, "invalid_duration"
		end
		local timelineStart = timeline:GetStartFrame() or 0
		local markIn = timelineStart + firstFrame
		local markOut = markIn + durationFrames - 1
		local dir = ensureTempDir()
		local uniqueId = os.date("%Y%m%d%H%M%S")
		if timeline.GetUniqueId then
			local ok, value = pcall(function()
				return timeline:GetUniqueId()
			end)
			if ok and value and tostring(value) ~= "" then
				uniqueId = tostring(value)
			end
		end
		local baseName = string.format("clone_%s", uniqueId)
		local settings = {
			SelectAllFrames = false,
			MarkIn = markIn,
			MarkOut = markOut,
			TargetDir = dir,
			CustomName = baseName,
			UniqueFilenameStyle = 1,
			ExportVideo = false,
			ExportAudio = true,
			AudioCodec = "LinearPCM",
			AudioBitDepth = 16,
			AudioSampleRate = 48000,
		}
		project:SetRenderSettings(settings)
		local jobId = project:AddRenderJob()
		if not jobId then
			return nil, "add_job_failed"
		end
		local started = project:StartRendering({ jobId }, false)
		if not started then
			project:DeleteRenderJob(jobId)
			return nil, "render_start_failed"
		end
		App.Status.show("render_audio")
		while project:IsRenderingInProgress() do
			sleepSeconds(0.5)
		end
		project:DeleteRenderJob(jobId)
		local outputPath = App.Utils.joinPath(dir, baseName .. ".wav")
		if not App.Utils.fileExists(outputPath) then
			return nil, "render_output_missing"
		end
		if resolve and resolve.OpenPage then
			pcall(function()
				resolve:OpenPage("edit")
			end)
		end
		return outputPath
	end

	local function escapeShell(str)
		return (str or ""):gsub('"', '\\"')
	end

	function Clone.uploadFileForClone(filePath, apiKey, groupId, isIntl)
		local baseUrl = isIntl and "https://api.minimax.io" or "https://api.minimaxi.com"
		local url = string.format("%s/v1/files/upload?GroupId=%s", baseUrl, App.Utils.urlEncode(groupId or ""))
		local responsePath, err = App.Utils.makeTempPath("upload")
		if not responsePath then
			return nil, err
		end
		local errPath, errPathErr = App.Utils.makeTempPath("upload.stderr")
		if not errPath then
			App.Utils.removeFile(responsePath)
			return nil, errPathErr
		end
		local body = ""
		local stderr = ""
		local ok = false
		if IS_WINDOWS and App.Services and App.Services.CurlCompat then
			local runResult = App.Services.CurlCompat.runWindowsSync(function(tlsCompatFlag)
				return string.format(
					'curl %s -f -X POST "%s" -H "Authorization: Bearer %s" -F "purpose=voice_clone" -F "file=@%s" -o "%s" 2> "%s"',
					buildStandardCurlFlags(tlsCompatFlag),
					url,
					escapeShell(apiKey),
					escapeShell(filePath),
					escapeShell(responsePath),
					escapeShell(errPath)
				)
			end, {
				bodyPath = responsePath,
				errPath = errPath,
				resetPaths = { responsePath, errPath },
				context = "minimax_clone_upload",
			})
			ok = runResult.ok == true
			body = runResult.body or ""
			stderr = runResult.stderr or ""
		else
			local command = string.format(
				'curl %s -f -X POST "%s" -H "Authorization: Bearer %s" -F "purpose=voice_clone" -F "file=@%s" -o "%s" 2> "%s"',
				buildStandardCurlFlags(),
				url,
				escapeShell(apiKey),
				escapeShell(filePath),
				escapeShell(responsePath),
				escapeShell(errPath)
			)
			ok = runShellCommand(command) == true
			body = App.Utils.readFile(responsePath) or ""
			stderr = App.Utils.readFile(errPath) or ""
		end
		App.Utils.removeFile(responsePath)
		App.Utils.removeFile(errPath)
		logInfo(string.format("MiniMax clone upload response: %s", truncateForLog(body or "<empty>", 800)))
		if stderr ~= "" then
			logInfo(string.format("MiniMax clone upload stderr: %s", truncateForLog(stderr, 800)))
		end
		if not ok then
			return nil, stderr ~= "" and stderr or body or "upload_failed"
		end
		local resp, decodeErr = json.decode(body)
		if not resp then
			return nil, decodeErr
		end
		local base = resp.base_resp or resp.baseResp or {}
		local statusCode = tonumber(base.status_code or base.statusCode)
		if statusCode and statusCode ~= 0 then
			return {
				error_code = statusCode,
				error_message = base.status_msg or base.statusMsg or "unknown_error",
			}
		end
		local fileId = resp.file and resp.file.file_id
		if type(fileId) == "number" then
			fileId = string.format("%.0f", fileId)
		elseif fileId ~= nil then
			fileId = tostring(fileId)
		end
		return {
			file_id = fileId,
		}
	end

	function Clone.submitCloneJob(payload)
		local cfg = App.Config.MiniMax or {}
		local baseUrl = payload.isIntl and "https://api.minimax.io" or "https://api.minimaxi.com"
		local url = string.format("%s/v1/voice_clone?GroupId=%s", baseUrl, App.Utils.urlEncode(payload.groupId or ""))
		local fileIdDigits = tostring(payload.fileId or "")
		if not fileIdDigits:match("^%d+$") then
			return nil, "invalid_file_id"
		end
		local fileIdLiteral = { value = fileIdDigits }
		setmetatable(fileIdLiteral, {
			__tojson = function(t)
				return t.value
			end,
		})
		local body = {
			file_id = fileIdLiteral,
			voice_id = payload.voiceId,
			need_noise_reduction = payload.needNoiseReduction and true or false,
			need_volume_normalization = payload.needVolumeNormalization and true or false,
		}
		if payload.previewText and payload.previewText ~= "" then
			body.text = payload.previewText
			body.model = "speech-2.6-hd"
		end
		local headers = {
			Authorization = "Bearer " .. tostring(payload.apiKey or ""),
			["Content-Type"] = "application/json",
		}
		local logPayload = {}
		for k, v in pairs(body) do
			logPayload[k] = v
		end
		logPayload.file_id = payload.fileId
		local bodyStr = json.encode(body)
		logInfo(string.format("MiniMax clone submit payload: %s", truncateForLog(json.encode(logPayload), 800)))
		local respBody, status = App.Services.httpPostJson(url, bodyStr, headers, 120)
		logInfo(
			string.format(
				"MiniMax clone submit response (%s): %s",
				tostring(status or "unknown"),
				truncateForLog(respBody or "<empty>", 800)
			)
		)
		if not respBody then
			return nil, status or "clone_request_failed"
		end
		local resp, decodeErr = json.decode(respBody)
		if not resp then
			return nil, decodeErr
		end
		local base = resp.base_resp or resp.baseResp or {}
		local statusCode = tonumber(base.status_code or base.statusCode)
		if statusCode and statusCode ~= 0 then
			return {
				error_code = statusCode,
				error_message = base.status_msg or base.statusMsg or "clone_failed",
			}
		end
		return {
			demo_url = resp.demo_audio,
		}
	end

	function Clone.downloadDemo(url, destPath)
		local body, status = App.Services.httpGet(url, nil, 120)
		if not body or (status and tonumber(status) ~= 200) then
			return false
		end
		local ok, err = App.Utils.writeFile(destPath, body)
		if not ok then
			return false, err
		end
		return true
	end

	function Clone.showErrorCode(code)
		App.Status.showError(code)
	end

	function Clone.handleConfirm()
		local uiItems = App.UI.items
		local cloneUI = cloneItems()
		local miniItems = minimaxItems()
		if not uiItems or not cloneUI or not miniItems then
			return
		end
		local apiKey = trim((miniItems.minimaxApiKey and miniItems.minimaxApiKey.Text) or "")
		local groupId = trim((miniItems.minimaxGroupID and miniItems.minimaxGroupID.Text) or "")
		if apiKey == "" or groupId == "" then
			App.Status.show("enter_api_key")
			return
		end
		local outputDir = trim((uiItems.Path and uiItems.Path.Text) or App.Config.Settings.outputPath or "")
		if outputDir == "" then
			App.Status.show("select_save_path")
			return
		end
		App.Utils.ensureDir(outputDir)
		local voiceName = trim((cloneUI.minimaxCloneVoiceName and cloneUI.minimaxCloneVoiceName.Text) or "")
		local voiceId = trim((cloneUI.minimaxCloneVoiceID and cloneUI.minimaxCloneVoiceID.Text) or "")
		if voiceName == "" or voiceId == "" then
			App.Status.show("clone_id_error")
			return
		end
		local language = (uiItems.minimaxLanguageCombo and uiItems.minimaxLanguageCombo.CurrentText)
			or App.State.minimax.language
			or "中文（普通话）"
		local addOnly = cloneUI.minimaxOnlyAddID and cloneUI.minimaxOnlyAddID.Checked
		if addOnly then
			local ok, err = Clone.addCloneVoice(voiceName, voiceId, language)
			if not ok then
				App.Status.show(nil, err)
				return
			end
			Clone.refreshVoices(voiceId)
			App.Status.show("add_clone_succeed")
			setTextSafe(cloneUI.minimaxCloneVoiceName, "")
			setTextSafe(cloneUI.minimaxCloneVoiceID, "")
			setTextSafe(cloneUI.minimaxCloneFileID, "")
			return
		end
		App.Status.show("clone_params_check")
		local fileIdText = trim((cloneUI.minimaxCloneFileID and cloneUI.minimaxCloneFileID.Text) or "")
		local fileId
		if not fileIdText or fileIdText == "" then
			local audioPath, audioErr = Clone.renderAudioByMarker()
			if not audioPath then
				App.Status.show(nil, audioErr or "render_failed")
				return
			end
			local size = App.Utils.getFileSize(audioPath)
			if size and size > 20 * 1024 * 1024 then
				App.Status.show("file_size")
				return
			end
			App.Status.show("file_upload")
			local uploadResult, uploadErr = Clone.uploadFileForClone(
				audioPath,
				apiKey,
				groupId,
				miniItems.intlCheckBox and miniItems.intlCheckBox.Checked
			)
			if not uploadResult then
				App.Status.show(nil, uploadErr or "upload_failed")
				return
			end
			if uploadResult.error_code then
				Clone.showErrorCode(uploadResult.error_code)
				return
			end
			if type(uploadResult.file_id) == "number" then
				fileId = string.format("%.0f", uploadResult.file_id)
			else
				fileId = uploadResult.file_id and tostring(uploadResult.file_id) or ""
			end
			setTextSafe(cloneUI.minimaxCloneFileID, fileId)
		else
			fileId = fileIdText
		end
		if not fileId or fileId == "" then
			App.Status.show(
				nil,
				localizedText(
					"上传完成，但未返回 file_id。",
					"Upload completed, but no file_id was returned."
				)
			)
			return
		end
		local submitFileId = fileId
		App.Status.show("file_clone")
		local cloneResp, cloneErr = Clone.submitCloneJob({
			apiKey = apiKey,
			groupId = groupId,
			fileId = submitFileId,
			voiceId = voiceId,
			isIntl = miniItems.intlCheckBox and miniItems.intlCheckBox.Checked,
			needNoiseReduction = cloneUI.minimaxNeedNoiseReduction and cloneUI.minimaxNeedNoiseReduction.Checked,
			needVolumeNormalization = cloneUI.minimaxNeedVolumeNormalization
				and cloneUI.minimaxNeedVolumeNormalization.Checked,
			previewText = (cloneUI.minimaxClonePreviewText and cloneUI.minimaxClonePreviewText.PlainText) or "",
		})
		if not cloneResp then
			App.Status.show(nil, cloneErr)
			return
		end
		if cloneResp.error_code then
			Clone.showErrorCode(cloneResp.error_code)
			return
		end
		if cloneResp.demo_url then
			App.Status.show("download_preclone")
			local demoPath = App.Utils.joinPath(outputDir, string.format("preview_%s.mp3", voiceId))
			local ok, err = Clone.downloadDemo(cloneResp.demo_url, demoPath)
			if ok then
				App.TimelineIO.insertAudio(demoPath, 0, 0, nil)
			else
				logInfo("Failed to download demo: " .. tostring(err))
			end
		end
		local ok, err = Clone.addCloneVoice(voiceName, voiceId, language)
		if not ok then
			App.Status.show(nil, err)
			return
		end
		Clone.refreshVoices(voiceId)
		App.Status.show("clone_success")
	end
end

---
--- 8b. Resolve + 字幕模块 (App.ResolveCtx/App.Subtitles)
---
do
	local ResolveCtx = App.ResolveCtx or {}
	local Subtitles = App.Subtitles or {}

	function ResolveCtx.get()
		local resolveInstance = resolve or Resolve()
		if not resolveInstance then
			return nil, nil, nil, "Resolve not available"
		end
		local projectManager = resolveInstance:GetProjectManager()
		if not projectManager then
			return resolveInstance, nil, nil, "ProjectManager unavailable"
		end
		local project = projectManager:GetCurrentProject()
		if not project then
			return resolveInstance, nil, nil, "No active project"
		end
		local timeline = project:GetCurrentTimeline()
		if not timeline then
			return resolveInstance, project, nil, "No active timeline"
		end
		return resolveInstance, project, timeline, nil
	end

	local function resolveTimelineFrameRate(project, timeline)
		if timeline and timeline.GetSetting then
			local value = timeline:GetSetting("timelineFrameRate")
			local frameRate = tonumber(value)
			if frameRate and frameRate > 0 then
				return frameRate
			end
		end
		if project and project.GetSetting then
			local value = project:GetSetting("timelineFrameRate")
			local frameRate = tonumber(value)
			if frameRate and frameRate > 0 then
				return frameRate
			end
		end
		return nil
	end

	local function getCurrentFrameNumber(timeline, frameRate)
		if timeline and timeline.GetCurrentFrame then
			local currentFrame = timeline:GetCurrentFrame()
			if type(currentFrame) == "number" and currentFrame >= 0 then
				return math.floor(currentFrame + 0.5)
			end
		end
		if timeline and timeline.GetCurrentTimecode then
			local timecode = timeline:GetCurrentTimecode()
			if timecode and timecode ~= "" then
				local frame = timecodeToFrames(timecode, frameRate)
				if frame and frame >= 0 then
					return frame
				end
			end
		end
		return nil
	end

	local function isTrackEnabled(timeline, trackIndex)
		if not timeline then
			return false
		end
		if timeline.GetIsTrackEnabled then
			local ok, enabled = pcall(function()
				return timeline:GetIsTrackEnabled("subtitle", trackIndex)
			end)
			if ok and enabled ~= nil then
				return enabled and true or false
			end
		end
		return true
	end

	local function sortSubtitles(entries)
		table.sort(entries, function(a, b)
			if a.startFrame == b.startFrame then
				if a.trackIndex == b.trackIndex then
					return (a.index or 0) < (b.index or 0)
				end
				return (a.trackIndex or 0) < (b.trackIndex or 0)
			end
			return (a.startFrame or 0) < (b.startFrame or 0)
		end)
	end

	local function stripUtf8Bom(text)
		return tostring(text or ""):gsub("^\239\187\191", "")
	end

	local function formatSrtTimestamp(seconds)
		local value = tonumber(seconds) or 0
		if value < 0 then
			value = 0
		end
		local totalMilliseconds = math.floor((value * 1000) + 0.5)
		local hours = math.floor(totalMilliseconds / 3600000)
		totalMilliseconds = totalMilliseconds % 3600000
		local minutes = math.floor(totalMilliseconds / 60000)
		totalMilliseconds = totalMilliseconds % 60000
		local secs = math.floor(totalMilliseconds / 1000)
		local milliseconds = totalMilliseconds % 1000
		return string.format("%02d:%02d:%02d,%03d", hours, minutes, secs, milliseconds)
	end

	local function extractBaseName(path)
		local value = tostring(path or "")
		return value:match("([^/\\]+)$") or value
	end

	local function isMediaPoolItem(value)
		local valueType = type(value)
		if valueType ~= "table" and valueType ~= "userdata" then
			return false
		end
		return value.GetName ~= nil and value.GetClipProperty ~= nil and value.GetUniqueId ~= nil
	end

	local function isFolderObject(value)
		local valueType = type(value)
		if valueType ~= "table" and valueType ~= "userdata" then
			return false
		end
		return value.GetName ~= nil and value.GetSubFolderList ~= nil and value.GetClipList ~= nil
	end

	local function getOrCreateRootSubFolder(mediaPool, rootFolder, folderName)
		local subFolders = rootFolder:GetSubFolderList() or {}
		for index, folder in ipairs(subFolders) do
			if not isFolderObject(folder) then
				return nil, string.format("invalid_subfolder_entry_at_index_%s", tostring(index))
			end
			if folder:GetName() == folderName then
				return folder
			end
		end

		local createdFolder = mediaPool:AddSubFolder(rootFolder, folderName)
		if not createdFolder or not isFolderObject(createdFolder) then
			return nil, string.format("failed_to_create_%s_folder", tostring(folderName))
		end
		return createdFolder
	end

	function Subtitles.getCurrent()
		local resolveInstance, project, timeline, err = ResolveCtx.get()
		if err then
			return nil, err
		end
		if not project or not timeline then
			return nil,
				localizedText("当前项目或时间线不可用。", "Current project or timeline is unavailable.")
		end

		local frameRate = resolveTimelineFrameRate(project, timeline)
		if not frameRate then
			return nil, localizedText("无法获取时间线帧率。", "Unable to read the timeline frame rate.")
		end

		local currentFrame = getCurrentFrameNumber(timeline, frameRate)
		if not currentFrame then
			return nil,
				localizedText("无法确定当前帧位置。", "Unable to determine the current frame position.")
		end

		local trackCount = timeline:GetTrackCount("subtitle") or 0
		for trackIndex = 1, trackCount do
			if isTrackEnabled(timeline, trackIndex) then
				local items = timeline:GetItemListInTrack("subtitle", trackIndex) or {}
				for itemIndex, item in ipairs(items) do
					local startFrame = item:GetStart()
					local endFrame = item:GetEnd()
					if startFrame and endFrame and startFrame <= currentFrame and currentFrame <= endFrame then
						local text = item:GetName() or ""
						return {
							text = text,
							startFrame = startFrame,
							endFrame = endFrame,
							trackIndex = trackIndex,
							index = itemIndex,
							frameRate = frameRate,
						}
					end
				end
			end
		end
		return nil,
			localizedText(
				"未在当前播放头找到字幕，请将播放头移至字幕块。",
				"No subtitle was found under the playhead. Move the playhead onto a subtitle clip."
			)
	end

	function Subtitles.collectAll()
		local resolveInstance, project, timeline, err = ResolveCtx.get()
		if err then
			return nil, err
		end
		if not project or not timeline then
			return nil,
				localizedText("当前项目或时间线不可用。", "Current project or timeline is unavailable.")
		end

		local frameRate = resolveTimelineFrameRate(project, timeline)
		if not frameRate then
			return nil, localizedText("无法获取时间线帧率。", "Unable to read the timeline frame rate.")
		end

		local results = {}
		local trackCount = timeline:GetTrackCount("subtitle") or 0
		for trackIndex = 1, trackCount do
			if isTrackEnabled(timeline, trackIndex) then
				local items = timeline:GetItemListInTrack("subtitle", trackIndex) or {}
				for itemIndex, item in ipairs(items) do
					local startFrame = item:GetStart()
					local endFrame = item:GetEnd()
					local text = item:GetName() or ""
					results[#results + 1] = {
						text = text,
						startFrame = startFrame,
						endFrame = endFrame,
						trackIndex = trackIndex,
						index = itemIndex,
					}
				end
			end
		end

		if #results > 0 then
			sortSubtitles(results)
		end

		return {
			subtitles = results,
			frameRate = frameRate,
		}
	end

	function Subtitles.concatText(subtitles)
		if not subtitles then
			return ""
		end
		local buffer = {}
		for _, entry in ipairs(subtitles) do
			local text = entry.text
			if text and text ~= "" then
				buffer[#buffer + 1] = text
			end
		end
		return table.concat(buffer, "\n")
	end

	function Subtitles.formatSrtTimestamp(seconds)
		return formatSrtTimestamp(seconds)
	end

	function Subtitles.buildMiniMaxSrtContent(entries, startOffsetSeconds)
		if type(entries) ~= "table" then
			return nil, "invalid_subtitle_entries"
		end

		local offset = tonumber(startOffsetSeconds) or 0
		if offset < 0 then
			offset = 0
		end

		local output = {}
		local subtitleId = 1
		for _, entry in ipairs(entries) do
			if type(entry) ~= "table" then
				return nil, "invalid_subtitle_entry"
			end

			local timeBegin = tonumber(entry.time_begin)
			local timeEnd = tonumber(entry.time_end)
			if timeBegin == nil or timeEnd == nil then
				return nil, "invalid_subtitle_time"
			end

			output[#output + 1] = tostring(subtitleId)
			output[#output + 1] = string.format(
				"%s --> %s",
				formatSrtTimestamp((timeBegin / 1000) + offset),
				formatSrtTimestamp((timeEnd / 1000) + offset)
			)
			output[#output + 1] = stripUtf8Bom(entry.text or "")
			output[#output + 1] = ""
			subtitleId = subtitleId + 1
		end

		return table.concat(output, "\n")
	end

	function Subtitles.saveMiniMaxSrtFromJsonBody(body, srtPath, startOffsetSeconds)
		if type(body) ~= "string" or body == "" then
			return false, "empty_subtitle_body"
		end
		if type(srtPath) ~= "string" or srtPath == "" then
			return false, "invalid_srt_path"
		end

		local decoded, pos, err = json.decode(body)
		if not decoded then
			return false, err or ("subtitle_json_decode_failed:" .. tostring(pos))
		end

		local content, buildErr = Subtitles.buildMiniMaxSrtContent(decoded, startOffsetSeconds)
		if not content then
			return false, buildErr
		end

		return App.Utils.writeFile(srtPath, content)
	end

	function Subtitles.importSrtToTimeline(srtPath)
		if type(srtPath) ~= "string" or srtPath == "" then
			return false, "invalid_srt_path"
		end
		if not App.Utils.fileExists(srtPath) then
			return false, "srt_file_not_found"
		end

		local resolveInstance, project, timeline, err = ResolveCtx.get()
		if err then
			return false, err
		end
		if not project or not timeline then
			return false, "project_or_timeline_unavailable"
		end

		local trackCount = timeline:GetTrackCount("subtitle") or 0
		local targetTrack = nil
		for trackIndex = 1, trackCount do
			if timeline.SetTrackEnable then
				pcall(function()
					timeline:SetTrackEnable("subtitle", trackIndex, false)
				end)
			end
			if targetTrack == nil then
				local items = timeline:GetItemListInTrack("subtitle", trackIndex) or {}
				if #items == 0 then
					targetTrack = trackIndex
				end
			end
		end
		if targetTrack == nil then
			if not timeline:AddTrack("subtitle") then
				return false, "subtitle_track_create_failed"
			end
			local newTrackCount = timeline:GetTrackCount("subtitle") or trackCount
			if newTrackCount > trackCount then
				trackCount = newTrackCount
				targetTrack = trackCount
			else
				targetTrack = trackCount > 0 and trackCount or 1
			end
		end
		if timeline.SetTrackEnable then
			pcall(function()
				timeline:SetTrackEnable("subtitle", targetTrack, true)
			end)
		end

		local mediaPool = project:GetMediaPool()
		if not mediaPool then
			return false, "media_pool_unavailable"
		end

		local rootFolder = mediaPool:GetRootFolder()
		if not rootFolder then
			return false, "root_folder_unavailable"
		end
		local srtFolder, folderErr = getOrCreateRootSubFolder(mediaPool, rootFolder, "srt")
		if not srtFolder then
			return false, folderErr or "srt_folder_unavailable"
		end
		mediaPool:SetCurrentFolder(srtFolder)

		if srtFolder.GetClipList and mediaPool.DeleteClips then
			local okList, clips = pcall(function()
				return srtFolder:GetClipList() or {}
			end)
			if okList and type(clips) == "table" then
				local fileName = extractBaseName(srtPath)
				for index, clip in ipairs(clips) do
					if not isMediaPoolItem(clip) then
						return false, string.format("invalid_clip_entry_at_index_%s", tostring(index))
					end
					if clip:GetName() == fileName then
						local okDelete, deleted = pcall(function()
							return mediaPool:DeleteClips({ clip })
						end)
						if not okDelete or deleted == false then
							logInfo(
								string.format(
									"Failed to delete existing subtitle clip '%s' before import.",
									tostring(fileName)
								)
							)
						end
						break
					end
				end
			end
		end

		local importedItems = mediaPool:ImportMedia({ srtPath })
		if not importedItems or not importedItems[1] then
			return false, "subtitle_import_failed"
		end

		local okAppend, appendedItems = pcall(function()
			return mediaPool:AppendToTimeline({ importedItems[1] })
		end)

		local finalTrackCount = timeline:GetTrackCount("subtitle") or trackCount
		for trackIndex = 1, finalTrackCount do
			if timeline.SetTrackEnable then
				pcall(function()
					timeline:SetTrackEnable("subtitle", trackIndex, trackIndex == targetTrack)
				end)
			end
		end

		if not okAppend then
			return false, tostring(appendedItems)
		end
		if appendedItems == nil or appendedItems == false then
			return false, "subtitle_append_failed"
		end

		logInfo(string.format("Imported subtitle file to timeline: %s", tostring(srtPath)))
		return true
	end

	App.ResolveCtx = ResolveCtx
	App.Subtitles = Subtitles
end

---
--- 9. 控制器 + UI 模块 (App.Controller/App.UI)
---
do
	App.Controller = App.Controller or {}
	if not App.Controller.activeProvider then
		App.Controller.activeProvider = "azure"
	end
	App.UI = App.UI or {}
	App.UI.Events = App.UI.Events or {}
	local Controller = App.Controller
	local UI = App.UI
	local Events = UI.Events

	local TEXT_COUNTER_BINDINGS = {
		azure = {
			textId = "azureText",
			labelId = "azureTextCountLabel",
		},
		minimax = {
			textId = "minimaxText",
			labelId = "minimaxTextCountLabel",
		},
		openai = {
			textId = "OpenAIText",
			labelId = "OpenAITextCountLabel",
		},
	}

	local function controllerSetStatus(_, message)
		local text = ""
		if message ~= nil then
			text = trim(tostring(message))
		end
		App.Status.apply(text)
	end

	local function readPlainText(control)
		if not control then
			return ""
		end
		return control.PlainText or control.Text or ""
	end

	function UI.updateTextCounter(providerId)
		local binding = TEXT_COUNTER_BINDINGS[providerId]
		if not binding then
			return 0, false
		end
		local uiItems = App.UI.items or {}
		local textControl = uiItems[binding.textId]
		local labelControl = uiItems[binding.labelId]
		local counter = utf8CharCount or (App.Utils and App.Utils.utf8CharCount)
		if type(counter) ~= "function" then
			counter = function(text)
				return string.len(tostring(text or ""))
			end
		end
		local count = counter(readPlainText(textControl))
		local overLimit = count > App.Config.Const.TEXT_LIMIT
		if labelControl then
			setTextSafe(labelControl, string.format("%d/%d", count, App.Config.Const.TEXT_LIMIT))
			labelControl.StyleSheet = overLimit and App.Config.Const.TEXT_COUNTER_OVER_LIMIT_STYLE
				or App.Config.Const.TEXT_COUNTER_NORMAL_STYLE
		end
		return count, overLimit
	end

	function UI.refreshAllTextCounters()
		for _, providerId in ipairs({ "azure", "minimax", "openai" }) do
			App.UI.updateTextCounter(providerId)
		end
	end

	function Controller.setAllTextInputs(text)
		if text == nil then
			return
		end
		local items = App.UI.items or {}
		setTextSafe(items.azureText, text)
		setTextSafe(items.minimaxText, text)
		setTextSafe(items.OpenAIText, text)
		App.UI.refreshAllTextCounters()
	end

	function Controller.validateTextLength(providerId, source, rawText)
		if source ~= "text" then
			return true
		end
		local count = utf8CharCount(rawText or "")
		if count <= App.Config.Const.TEXT_LIMIT then
			return true
		end
		controllerSetStatus(
			providerId,
			localizedText(
				string.format(
					"文本长度为 %d，已超过 %d 字符上限，无法朗读文本框。",
					count,
					App.Config.Const.TEXT_LIMIT
				),
				string.format(
					"Text length is %d, exceeding the %d-character limit. Read Textbox is blocked.",
					count,
					App.Config.Const.TEXT_LIMIT
				)
			)
		)
		return false
	end

	function Controller.validateOutputDir(params)
		local outputDir = trim(params.outputDir or "")
		if outputDir == "" then
			return false, localizedText("请先设置保存路径。", "Please set a save path before synthesizing.")
		end
		if not App.Utils.ensureDir(outputDir) then
			return false,
				localizedText("保存路径无效或无法创建。", "Save path is invalid or cannot be created.")
		end
		params.outputDir = outputDir
		return true
	end

	function Controller.validateProviderConfig(providerId, params)
		if providerId == "azure" then
			if params.useApi then
				local apiKey = trim(params.apiKey or "")
				local region = trim(params.region or "")
				if apiKey == "" or region == "" then
					return false,
						localizedText("Azure API Key 或 Region 未配置", "Azure API Key or Region is not configured")
				end
				params.apiKey = apiKey
				params.region = region
			end
			return true
		end

		if providerId == "minimax" then
			local apiKey = trim(params.apiKey or "")
			local groupId = trim(params.groupId or "")
			if apiKey == "" then
				return false, localizedText("MiniMax API Key 未配置", "MiniMax API Key is not configured")
			end
			if groupId == "" then
				return false, localizedText("MiniMax Group ID 未配置", "MiniMax Group ID is not configured")
			end
			params.apiKey = apiKey
			params.groupId = groupId
			return true
		end

		if providerId == "openai" then
			local apiKey = trim(params.apiKey or "")
			if apiKey == "" then
				return false, localizedText("OpenAI API Key 未配置", "OpenAI API Key is not configured")
			end
			params.apiKey = apiKey
			return true
		end

		return true
	end

	function Controller.collectAzureParams(source)
		local items = App.UI.items
		local azureItems = App.UI.azureItems or {}
		local stateAzure = App.State.azure or {}
		local outputDir = trim((items.Path and items.Path.Text) or App.Config.Settings.outputPath or "")
		local params = {
			source = source,
			text = readPlainText(items.azureText),
			breakMs = items.azureBreakSpinBox and items.azureBreakSpinBox.Value or stateAzure.breakMs,
			styleDegree = items.azureStyleDegreeSpinBox and items.azureStyleDegreeSpinBox.Value
				or stateAzure.styleDegree,
			rate = items.azureRateSpinBox and items.azureRateSpinBox.Value or stateAzure.rate,
			pitch = items.azurePitchSpinBox and items.azurePitchSpinBox.Value or stateAzure.pitch,
			volume = items.azureVolumeSpinBox and items.azureVolumeSpinBox.Value or stateAzure.volume,
			outputFormat = App.Settings.getAzureFormatId(),
			languageDisplay = items.azureLanguageCombo and items.azureLanguageCombo.CurrentText or "",
			voiceDisplay = items.azureVoiceCombo and items.azureVoiceCombo.CurrentText or "",
			voiceTypeDisplay = items.azureVoiceTypeCombo and items.azureVoiceTypeCombo.CurrentText or "",
			styleDisplay = items.azureStyleCombo and items.azureStyleCombo.CurrentText or "",
			multilingualDisplay = items.azureMultilingualCombo and items.azureMultilingualCombo.CurrentText or "",
			locale = stateAzure.language,
			startOffsetSamples = 0,
			durationSamples = 0,
			outputDir = outputDir,
			style = stateAzure.style or "default",
		}
		local formatEntry, fmtIndex = App.Settings.getSharedFormat()
		if formatEntry then
			params.outputFormat = formatEntry.azureId or formatEntry.id or params.outputFormat
			stateAzure.outputFormat = params.outputFormat
			stateAzure.outputFormatIndex = fmtIndex or 0
		end
		local voiceEntry = App.State.azure.voiceList
			and App.State.azure.voiceList[(items.azureVoiceCombo and (items.azureVoiceCombo.CurrentIndex or 0) or 0) + 1]
		if voiceEntry then
			params.voiceId = voiceEntry.id
			params.voiceGender = voiceEntry.type
		else
			params.voiceId = stateAzure.voiceId
		end
		params.multilingualCode = stateAzure.multilingual
		params.multilingualOptions = stateAzure.multilingualOptions
		params.provider = "azure"
		params.apiKey = trim((azureItems.ApiKey and azureItems.ApiKey.Text) or App.Config.Azure.defaults.apiKey or "")
		params.region = trim((azureItems.Region and azureItems.Region.Text) or App.Config.Azure.defaults.region or "")
		local useApi = readChecked(azureItems.UseAPICheckBox, stateAzure.useApi ~= false)
		params.useApi = useApi
		App.State.azure.useApi = useApi
		if not params.outputFormat or params.outputFormat == "" then
			local defaultFmt = App.Config.Azure.outputFormats and App.Config.Azure.outputFormats[1]
			params.outputFormat = defaultFmt and defaultFmt.id or "riff-24khz-16bit-mono-pcm"
		end
		return params
	end

