	function UI.updateMiniMaxSubtitleCheckboxState()
		local items = App.UI.items or {}
		local checkbox = items.minimaxSubtitleCheckBox
		if not checkbox then
			return
		end

		local locale = (App.State.locale == "cn") and "cn" or "en"
		local translations = App.UI.translations or App.UI.buildTranslations()
		local texts = translations[locale] or {}
		local formatId = tostring(App.Settings.getSharedFormatId() or "mp3"):lower()
		local isMp3 = (formatId == "mp3")

		if isMp3 then
			setCheckedSafe(checkbox, false)
			App.State.minimax.subtitle = false
			setEnabledSafe(checkbox, false)
			setTextSafe(checkbox, texts.minimaxSubtitleCheckBoxWavOnly or "生成SRT字幕，仅在WAV格式下可用")
			return
		end

		setEnabledSafe(checkbox, true)
		setTextSafe(checkbox, texts.minimaxSubtitleCheckBox or "生成SRT字幕")
	end

	function UI.updateMiniMaxIntlCheckboxText()
		local minimaxItems = App.UI.minimaxItems or {}
		local checkbox = minimaxItems.intlCheckBox
		if not checkbox then
			return
		end
		local isIntl = checkbox.Checked and true or false
		local locale = (App.State.locale == "cn") and "cn" or "en"
		local text
		if locale == "cn" then
			if isIntl then
				text = "当前：国际站（minimax.io）"
			else
				text = "当前：国内站（minimaxi.com）"
			end
		else
			if isIntl then
				text = "Current: Intl Site (minimax.io)"
			else
				text = "Current: CN Site (minimaxi.com)"
			end
		end
		setTextSafe(checkbox, text)
	end

