	function Events.bindWindowEvent(windowObj, controlId, eventName, handler)
		if not windowObj or type(windowObj.On) ~= "table" then
			return false
		end
		if not controlId or not eventName or type(handler) ~= "function" then
			return false
		end
		local target = windowObj.On[controlId]
		if target == nil then
			return false
		end
		-- Resolve/Fusion 的 On[controlId] 可能是 userdata 事件代理；不能用普通 table 覆盖。
		local ok = pcall(function()
			target[eventName] = handler
		end)
		return ok
	end

	function Events.bindTextCounterEvents()
		local bindings = {
			{ "azureText", "azure" },
			{ "minimaxText", "minimax" },
			{ "OpenAIText", "openai" },
		}
		for _, pair in ipairs(bindings) do
			local controlId = pair[1]
			local providerId = pair[2]
			local function onCounterTextChange()
				App.UI.updateTextCounter(providerId)
			end
			-- TextEdit 在不同 Resolve/Fusion 版本里可触发的事件名有差异，统一做兜底绑定。
			App.UI.Events.bindWindowEvent(win, controlId, "TextChanged", onCounterTextChange)
			App.UI.Events.bindWindowEvent(win, controlId, "TextEdited", onCounterTextChange)
