	function Events.bindVoiceModifyValueEvents()
		local directBindings = {
			{ "minimaxTimbreSlider", "timbre", "minimaxTimbreSlider" },
			{ "minimaxIntensitySlider", "intensity", "minimaxIntensitySlider" },
			{ "minimaxModifyPitchSlider", "pitch", "minimaxModifyPitchSlider" },
		}
		for _, entry in ipairs(directBindings) do
			local controlId = entry[1]
			local key = entry[2]
			local sourceId = entry[3]
			App.UI.Events.bindWindowEvent(minimaxVoiceModifyWin, controlId, "ValueChanged", function(ev)
				syncVoiceModifyFromControl(key, sourceId, eventNumericValue(ev))
			end)
		end

		local signedSpinBindings = {
			{ "minimaxTimbreSpinBoxLeft", "timbre", "minimaxTimbreSpinBoxLeft", -1 },
			{ "minimaxTimbreSpinBoxRight", "timbre", "minimaxTimbreSpinBoxRight", 1 },
			{ "minimaxIntensitySpinBoxLeft", "intensity", "minimaxIntensitySpinBoxLeft", -1 },
			{ "minimaxIntensitySpinBoxRight", "intensity", "minimaxIntensitySpinBoxRight", 1 },
			{ "minimaxModifyPitchSpinBoxLeft", "pitch", "minimaxModifyPitchSpinBoxLeft", -1 },
			{ "minimaxModifyPitchSpinBoxRight", "pitch", "minimaxModifyPitchSpinBoxRight", 1 },
		}
		for _, entry in ipairs(signedSpinBindings) do
			local controlId = entry[1]
			local key = entry[2]
			local sourceId = entry[3]
			local sign = entry[4]
			App.UI.Events.bindWindowEvent(minimaxVoiceModifyWin, controlId, "ValueChanged", function(ev)
				local value = math.abs(eventNumericValue(ev) or 0)
				if sign < 0 then
					value = -value
				end
				syncVoiceModifyFromControl(key, sourceId, value)
			end)
		end

		App.UI.Events.bindWindowEvent(
			minimaxVoiceModifyWin,
			"minimaxSoundEffectCombo",
			"CurrentIndexChanged",
			handleVoiceModifyEffectChange
		)
	end

