	function Events.onMainWinClose(ev)
		if App.SynthesisAsync and App.SynthesisAsync.cancel then
			App.SynthesisAsync.cancel("window_close")
		end
		if App.Preview and App.Preview.isActive and App.Preview.isActive() then
			App.Preview.stopActivePreview("window_close")
		end
		local savedOk, savedErr = App.Settings.save()
		if not savedOk then
			logInfo(string.format("Settings save on close failed: %s", tostring(savedErr)))
		end
		App.Utils.removeDir(App.Paths.tempDir)
		local cloneDir = App.MiniMaxClone and App.MiniMaxClone.tempDir
		if cloneDir then
			App.Utils.removeDir(cloneDir)
		end
		win:Hide()
		minimaxCloneWin:Hide()
		minimaxConfigWin:Hide()
		openaiConfigWin:Hide()
		azureConfigWin:Hide()
		msgbox:Hide()
		dispatcher:ExitLoop()
	end

