	function win.On.Browse.Clicked(ev)
		local fusionInstance = fusion or (resolve and resolve:Fusion())
		if not (fusionInstance and fusionInstance.RequestDir) then
			App.UI.Events.notifyUser(
				localizedText(
					"当前环境不支持选择路径。",
					"Directory picker is not available in this context."
				)
			)
			return
		end
		local uiItems = App.UI.items or {}
		local startDir = trim((uiItems.Path and uiItems.Path.Text) or App.Config.Settings.outputPath or "")
		if startDir == "" and fusionInstance.MapPath then
			local ok, mapped = pcall(function()
				return fusionInstance:MapPath("UserData:/")
			end)
			if ok and mapped and mapped ~= "" then
				startDir = mapped
			end
		end
		local selected = fusionInstance:RequestDir((startDir ~= "" and startDir) or nil)
		if not selected or selected == "" then
			return
		end
		if not App.Utils.ensureDir(selected) then
			App.UI.Events.notifyUser(
				localizedText("无法访问所选目录。", "Selected directory is not accessible.")
			)
			return
		end
		local _, project = App.ResolveCtx.get()
		local projectName = (project and project.GetName and project:GetName()) or "DaVinci"
		local safeName = App.Utils.sanitizeFileName(projectName, 48)
		if safeName == "" then
			safeName = "DaVinci"
		end
		local folderName = safeName
		if not safeName:lower():match("_tts$") then
			folderName = safeName .. "_TTS"
		end
		local targetDir = App.Utils.joinPath(selected, folderName)
		if not App.Utils.ensureDir(targetDir) then
			App.UI.Events.notifyUser(
				localizedText("无法创建保存路径。", "Unable to create the save directory.")
			)
			return
		end
		if uiItems.Path then
			setTextSafe(uiItems.Path, targetDir)
		end
		App.Config.Settings.outputPath = targetDir
		if App.Config.Settings.saved then
			App.Config.Settings.saved.Path = targetDir
		end
		App.UI.Events.notifyUser(localizedText("保存路径已更新。", "Save path updated."))
		logInfo("Output path updated to " .. targetDir)
	end

	function win.On.DonationButtonSettings.Clicked(ev)
		local uiItems = App.UI.items or {}
		local useEnglish = false
		if uiItems.LangEnCheckBox and uiItems.LangEnCheckBox.Checked then
			useEnglish = true
		elseif uiItems.LangCnCheckBox and uiItems.LangCnCheckBox.Checked then
			useEnglish = false
		else
			useEnglish = (App.State.locale ~= "cn")
		end
		local url = useEnglish and App.Config.Const.SCRIPT_KOFI_URL or App.Config.Const.SCRIPT_TAOBAO_URL
		if not openUrl(url) then
			App.UI.Events.notifyUser(localizedText("无法打开链接：", "Unable to open link:") .. "\n" .. url)
		end
	end

	for _, buttonId in ipairs({ "SponsorPaypalQrButton", "SponsorWechatQrButton" }) do
		if win.On[buttonId] then
			win.On[buttonId].Clicked = win.On.DonationButtonSettings.Clicked
		end
	end

	function minimaxConfigWin.On.minimaxRegisterButton.Clicked(ev)
		local miniItems = App.UI.minimaxItems or {}
		local url = App.Config.URLS.MiniMaxRegisterCn
		if miniItems.intlCheckBox and miniItems.intlCheckBox.Checked then
			url = App.Config.URLS.MiniMaxRegisterIntl
		end
		openUrl(url)
	end

	-- intlCheckBox 切换时刷新 MiniMax 语音列表
	function minimaxConfigWin.On.intlCheckBox.Clicked(ev)
		local miniItems = App.UI.minimaxItems or {}
		local isIntl = miniItems.intlCheckBox and miniItems.intlCheckBox.Checked or false
		App.UI.updateMiniMaxIntlCheckboxText()
		App.UI.reloadMiniMaxVoicesForIntl(isIntl)
	end
end

---
--- 10. 运行入口 (App.Run)
---
function App.Run()
	if not (App.UI and App.UI.Events and win and dispatcher) then
		return
	end
	App.UI.Events.bindProviderActions()
	App.UI.Events.bindConfigWindows()
	App.UI.Events.bindLocaleAndTabs()
	App.UI.Events.bindUtilityActions()
	win:Show()
	dispatcher:RunLoop()
	win:Hide()
end

App.Run()
